window.__RF_DATA=window.__RF_DATA||{};window.__RF_DATA["fathersData"]="{\"v\":1,\"src\":{\"title\":\"أقوال الآباء الشيوخ\",\"series\":\"آباء الكنيسة ٦\",\"pub\":\"ترجمة معهد القديس يوحنا الدمشقي – البلمند، منشورات النور ١٩٩٠\"},\"tags\":[\"الصلاة\",\"التوبة\",\"الاتضاع\",\"الصبر\",\"المحبة\",\"الصمت\",\"الغفران\",\"الرجاء\",\"الإيمان\",\"الشكر\",\"الطاعة\",\"السهر\",\"الجهاد\",\"الأفكار\",\"الزهد\",\"الرحمة\",\"الخدمة\",\"الحكمة\",\"التمييز\",\"الخلوة\",\"ذكر الموت\",\"الوداعة\",\"الغضب\",\"اللسان\",\"الضيقات\",\"الصوم\",\"الكتاب المقدس\",\"الكنيسة\",\"الضيافة\",\"العمل\",\"الشركة\",\"الإدانة\",\"الفرح\",\"السلام\",\"خوف الله\",\"الدموع\",\"الكبرياء\",\"الطمع\",\"الشهوة\",\"المجد الباطل\"],\"items\":[{\"i\":1,\"f\":\"القديس أنطونيوس الكبير\",\"p\":39,\"n\":3,\"c\":\"جوابًا لرجل سأل: ماذا يجب عليّ أن أحفظ لكي أرضي الله؟\",\"t\":\"احفظ ما أوصيك به. حيثما تذهب ليكن الله نصب عينيك. ومهما فعلت، لتكن لديك الشهادة من الأسفار المقدسة. حيثما جلست، لا تتحرك بسرعة. احفظ هذه الثلاثة، تخلص.\",\"g\":[\"الكتاب المقدس\",\"السهر\",\"الصبر\"],\"k\":\"39.3\"},{\"i\":2,\"f\":\"القديس أنطونيوس الكبير\",\"p\":39,\"n\":4,\"c\":\"قاله للقديس بيمن\",\"t\":\"هذا هو العمل العظيم: أن يحمل الإنسان خطيئته ويضعها أمام الله منتظراً حتى نسمته الأخيرة.\",\"g\":[\"التوبة\",\"الاتضاع\",\"الصبر\"],\"k\":\"39.4\"},{\"i\":3,\"f\":\"القديس أنطونيوس الكبير\",\"p\":40,\"n\":5,\"t\":\"لا أحد يقدر أن يدخل ملكوت السموات بدون تجارب، لأنه قال: ارفعْ التجارب فلا يخلص أحد.\",\"g\":[\"الضيقات\",\"الجهاد\"],\"k\":\"40.5\"},{\"i\":4,\"f\":\"القديس أنطونيوس الكبير\",\"p\":40,\"n\":6,\"c\":\"جوابًا للقديس بموا حين سأله: ماذا أعمل؟\",\"t\":\"لا تثق ببرك ولا تندم على أمر قد عبر. وأمسك بطنك ولسانك.\",\"g\":[\"الاتضاع\",\"اللسان\",\"الصوم\"],\"k\":\"40.6\"},{\"i\":5,\"f\":\"القديس أنطونيوس الكبير\",\"p\":40,\"n\":7,\"t\":\"رأيت كل فخاخ العدو ممدودةً على الأرض، فقلت متنهداً: ترى من ينجو منها؟ فسمعت للحال صوتاً يقول: التواضع.\",\"g\":[\"الاتضاع\",\"الكبرياء\"],\"k\":\"40.7\"},{\"i\":6,\"f\":\"القديس أنطونيوس الكبير\",\"p\":40,\"n\":8,\"t\":\"ثمة أناس أفنوا أجسادهم بالنسك، لكنهم ظلوا بعيدين عن الله كونهم لم يقتنوا فضيلة التمييز.\",\"g\":[\"التمييز\",\"الجهاد\"],\"k\":\"40.8\"},{\"i\":7,\"f\":\"القديس أنطونيوس الكبير\",\"p\":40,\"n\":9,\"t\":\"الموت والحياة يعتمدان على القريب. لأننا إذا ربحنا أخانا، فإننا نربح الله، وإذا ما أعثرنا أخانا، نخطأ إلى المسيح.\",\"g\":[\"المحبة\",\"الشركة\"],\"k\":\"40.9\"},{\"i\":8,\"f\":\"القديس أنطونيوس الكبير\",\"p\":40,\"n\":11,\"t\":\"إن من يقيم في البرية ويمارس حياة السكينة ينعتق من حروب ثلاث: السمع، والكلام، والنظر، وتبقى عليه حرب واحدة هي حرب الزنى.\",\"g\":[\"الخلوة\",\"الصمت\"],\"k\":\"40.11\"},{\"i\":9,\"f\":\"القديس أنطونيوس الكبير\",\"p\":41,\"n\":13,\"c\":\"بعد أن أراه صياداً أن القوس إذا شُدّ فوق القياس انكسر\",\"t\":\"هكذا الحال تماماً في عمل الله، إذا ما شددنا على الإخوة فوق القياس ينكسرون بسرعة. إذن ينبغي علينا أن نتنازل لهم بين الحين والآخر.\",\"g\":[\"الرحمة\",\"الحكمة\"],\"k\":\"41.13\"},{\"i\":10,\"f\":\"القديس أنطونيوس الكبير\",\"p\":42,\"n\":15,\"c\":\"قاله لراهب لم يحتمل الإهانة بعد أن امتُدح أمامه\",\"t\":\"أنت تشبه قرية تبدو جميلة ومزيّنة من الأمام، لكن اللصوص يسلبونها من الخلف.\",\"g\":[\"الاتضاع\",\"المجد الباطل\"],\"k\":\"42.15\"},{\"i\":11,\"f\":\"القديس أنطونيوس الكبير\",\"p\":42,\"n\":16,\"c\":\"جوابًا لأخ قال: يا أبت، صلِّ لأجلي\",\"t\":\"لا أنا أرحمك، ولا الله، إذا كنت أنت نفسك لا تسرع لتطلب هذا منه.\",\"g\":[\"الصلاة\",\"الجهاد\"],\"k\":\"42.16\"},{\"i\":12,\"f\":\"القديس أنطونيوس الكبير\",\"p\":44,\"n\":23,\"t\":\"الله لا يترك الحروب تعمل في هذا الجيل كما كانت تعمل في الأجيال السالفة، لأنه يعرف أن الناس الآن هم مرضى ولا يحتملون.\",\"g\":[\"الضيقات\",\"الرحمة\"],\"k\":\"44.23\"},{\"i\":13,\"f\":\"القديس أنطونيوس الكبير\",\"p\":44,\"n\":25,\"t\":\"سيأتي وقت يصير فيه البشر مجانين، وعندما يرون إنساناً عاقلاً، سينهضون عليه قائلين: أنت مجنون. والسبب، كونه يختلف عنهم.\",\"g\":[\"الحكمة\",\"الضيقات\"],\"k\":\"44.25\"},{\"i\":14,\"f\":\"القديس أنطونيوس الكبير\",\"p\":44,\"n\":27,\"c\":\"قاله الأب أنطونيوس لأحد ثلاثة آباء كانوا يزورونه كل سنة، وكان هذا الثالث يصمت ولا يسأل\",\"t\":\"لك زمان تزورني دون أن تسألني شيئاً. أجاب ذلك الأب: يكفيني أن أراك يا أبت.\",\"g\":[\"الصمت\",\"الاتضاع\"],\"k\":\"44.27\"},{\"i\":15,\"f\":\"القديس أنطونيوس الكبير\",\"p\":44,\"n\":28,\"t\":\"قالوا إن أحد الآباء طلب من الله أن يعاين الآباء القديسين. فرآهم دون أن يرى الأب أنطونيوس. فقال للذي أراه إياهم: وأين الأب أنطونيوس؟ قال ذاك: إنه في المكان الذي يقيم فيه الله.\",\"g\":[\"الخلوة\",\"الاتضاع\"],\"k\":\"44.28\"},{\"i\":16,\"f\":\"القديس أنطونيوس الكبير\",\"p\":45,\"n\":31,\"c\":\"جواب القديس بولس، تلميذ أنطونيوس، حين سأله أنطونيوس هل يذهب إلى القسطنطينية بناءً على دعوة الملك قسطنطين\",\"t\":\"إذا ذهبت، يقولون لك أنطونيوس، أما إذا بقيت فيقولون الأب أنطونيوس.\",\"g\":[\"الاتضاع\",\"الخلوة\"],\"k\":\"45.31\"},{\"i\":17,\"f\":\"القديس أنطونيوس الكبير\",\"p\":45,\"n\":32,\"t\":\"أنا لا أخاف الله أبداً إنما أحبه، «لأن المحبة تطرد الخوف خارجاً» (١ يوحنا ٤: ١٨).\",\"g\":[\"المحبة\",\"خوف الله\"],\"k\":\"45.32\"},{\"i\":18,\"f\":\"القديس أنطونيوس الكبير\",\"p\":45,\"n\":33,\"t\":\"ضع مخافة الله نصب عينيك دائماً. وتذكّر هذا الذي يُميت ويُحيي. امقتوا العالم وكل ما فيه. امقتوا كل راحة جسدية. ارفضوا هذه الحياة لتحبوا الله. تذكّروا وعدكم له.\",\"g\":[\"ذكر الموت\",\"الزهد\",\"خوف الله\"],\"k\":\"45.33\"},{\"i\":19,\"f\":\"القديس أنطونيوس الكبير\",\"p\":46,\"n\":35,\"t\":\"إن من يضرب كتلة الحديد، يفكر أولا في نفسه ماذا ينوي أن يصنع منها. هل يريد منجلاً أو فأساً؟ هكذا ينبغي أن نفكر نحن أيضاً أية فضيلة ننشد، لئلا نتعب عبثاً.\",\"g\":[\"الحكمة\",\"الجهاد\"],\"k\":\"46.35\"},{\"i\":20,\"f\":\"القديس أنطونيوس الكبير\",\"p\":46,\"n\":36,\"t\":\"الطاعة مع الامساك تخضع الوحوش.\",\"g\":[\"الطاعة\",\"الصوم\"],\"k\":\"46.36\"},{\"i\":21,\"f\":\"القديس أنطونيوس الكبير\",\"p\":46,\"n\":37,\"t\":\"أعرف رهباناً قد سقطوا بعد أتعاب كثيرة وتشوّش فكرهم، لأنهم ألقوا رجاءهم على أعمالهم واحتقروا وصية القائل: «اسأل أباك فيقول لك» (تثنية ٣٢: ٧).\",\"g\":[\"الاتضاع\",\"الطاعة\"],\"k\":\"46.37\"},{\"i\":22,\"f\":\"القديس أنطونيوس الكبير\",\"p\":46,\"n\":38,\"t\":\"إذا كان ممكناً، فليكشف الراهب للآباء كل خطواته وكل قطرات الماء التي يشربها في قلايته، لكي يتأكد من أنه لا يخطأ.\",\"g\":[\"التمييز\",\"الاتضاع\"],\"k\":\"46.38\"},{\"i\":23,\"f\":\"القديس أرسانيوس\",\"p\":47,\"n\":1,\"t\":\"عندما كان الأب أرسانيوس في البلاط، كان يصلي إلى الله قائلاً: يا رب، عرّفني كيف أخلص. فجاءه صوت يقول: أرسانيوس أرسانيوس، اهرب من الناس تخلص.\",\"g\":[\"الخلوة\",\"الصلاة\"],\"k\":\"47.1\"},{\"i\":24,\"f\":\"القديس أرسانيوس\",\"p\":47,\"n\":2,\"t\":\"عندما انقطع أرسانيوس إلى حياة التوحد، صلّى الكلام نفسه، فسمع صوتاً يقول له: أرسانيوس، اهرب واصمت واهدأ، لأن هذه هي جذور عدم الخطيئة.\",\"g\":[\"الصمت\",\"الخلوة\"],\"k\":\"47.2\"},{\"i\":25,\"f\":\"القديس أرسانيوس\",\"p\":47,\"n\":3,\"c\":\"صلاة الأب أرسانيوس حين اقتربت الشياطين من صومعته لتحزنه\",\"t\":\"يا إلهي، لا تتركني لوحدي لأني لم أعمل الصلاح أمامك. لكن بصلاحك ومحبتك أعطني أن أبدأ من جديد.\",\"g\":[\"التوبة\",\"الرجاء\"],\"k\":\"47.3\"},{\"i\":26,\"f\":\"القديس أرسانيوس\",\"p\":47,\"n\":5,\"c\":\"جوابًا لمن سأل: كيف نملك نحن كل هذه التربية والحكمة ولا نملك شيئاً صالحاً، والمصريون القرويون اقتنوا فضائل كثيرة؟\",\"t\":\"نحن لا نملك شيئاً من تربية العالم، أما هؤلاء المصريون فقد اقتنوا الفضائل بأتعابهم.\",\"g\":[\"الاتضاع\",\"الجهاد\"],\"k\":\"47.5\"},{\"i\":27,\"f\":\"القديس أرسانيوس\",\"p\":48,\"n\":6,\"c\":\"جوابًا لمن سأله: كيف تسأل هذا الفلاح المصري عن أفكارك وأنت تتقن العلم اليوناني والروماني؟\",\"t\":\"إنني أتقن التربية اليونانية والرومانية، لكنني لم أتعلم الأبجدية البدويّة التي يعرفها هذا المصري.\",\"g\":[\"الاتضاع\",\"الحكمة\"],\"k\":\"48.6\"},{\"i\":28,\"f\":\"القديس أرسانيوس\",\"p\":48,\"n\":7,\"c\":\"قاله لرئيس الأساقفة ثيوفيلس ومن معه حين طلبوا منه كلمة، بعد أن سألهم: هل تحفظانها؟\",\"t\":\"حيثما تسمعان بأرسانيوس لا تقتربا.\",\"g\":[\"الخلوة\",\"الاتضاع\"],\"k\":\"48.7\"},{\"i\":29,\"f\":\"القديس أرسانيوس\",\"p\":48,\"n\":9,\"t\":\"جاهد بكل قوتك لكي يكون عملك الداخلي وفقاً لإرادة الله، فتتغلب الأهواء الخارجية.\",\"g\":[\"الجهاد\",\"الأفكار\"],\"k\":\"48.9\"},{\"i\":30,\"f\":\"القديس أرسانيوس\",\"p\":48,\"n\":10,\"t\":\"إذا طلبنا الله، يظهر لنا، وإذا تمسكنا به، يقيم فينا.\",\"g\":[\"الصلاة\",\"الإيمان\"],\"k\":\"48.10\"},{\"i\":31,\"f\":\"القديس أرسانيوس\",\"p\":48,\"n\":11,\"c\":\"جوابًا لأخ أزعجته أفكاره فقالت له إنه لا يقدر أن يصوم ولا أن يعمل\",\"t\":\"اذهب، كل، إشرب، ونم، ولا تعمل، فقط لا تبارح قلايتك. هذا الكلام قاله لأنه كان يعرف أن صبر القلاية يعيد الراهب إلى الصراط المستقيم.\",\"g\":[\"الصبر\",\"الخلوة\",\"الأفكار\"],\"k\":\"48.11\"},{\"i\":32,\"f\":\"القديس أرسانيوس\",\"p\":48,\"n\":12,\"t\":\"عندما يكون الراهب في بلد غريب، لا يجوز له أن يتدخل في أي من الأمور، وهكذا يجد راحة.\",\"g\":[\"الصمت\",\"الاتضاع\"],\"k\":\"48.12\"},{\"i\":33,\"f\":\"القديس أرسانيوس\",\"p\":49,\"n\":13,\"c\":\"جوابًا للأب مرقس حين سأله: لماذا تتحاشانا يا أبت؟\",\"t\":\"يعلم الله أني أحبكم، إلا أني لا أقدر أن أكون مع الله ومع الناس. فالقوات السماوية وآلاف الطغمات العلوية عندها إرادة واحدة، أمّا البشر فبإراداتهم كثيرة. لهذا لا أستطيع أن أترك الله وأكون مع الناس.\",\"g\":[\"الخلوة\",\"الصلاة\"],\"k\":\"49.13\"},{\"i\":34,\"f\":\"القديس أرسانيوس\",\"p\":49,\"n\":15,\"t\":\"يكفي الراهب أن ينام ساعة واحدة فقط إذا كان مجاهداً.\",\"g\":[\"السهر\",\"الجهاد\"],\"k\":\"49.15\"},{\"i\":35,\"f\":\"القديس أرسانيوس\",\"p\":49,\"n\":18,\"c\":\"جوابًا للآباء حين سألوه لماذا لا يغيّر ماء الأغصان الذي قد أنتن\",\"t\":\"بدل المسك والعطور التي تنتشقها في العالم، ينبغي لي أن أتنشق هذه الرائحة.\",\"g\":[\"الزهد\",\"الاتضاع\"],\"k\":\"49.18\"},{\"i\":36,\"f\":\"القديس أرسانيوس\",\"p\":49,\"n\":19,\"t\":\"قيل عنه أيضاً إنه حينما سمع أن كل أجناس الثمار قد أينعت، أخذ يقول في نفسه: أحضروا لي. فكان يذوق قليلا من كل نوع، مرة واحدة فقط، ويشكر الله.\",\"g\":[\"الشكر\",\"الصوم\"],\"k\":\"49.19\"},{\"i\":37,\"f\":\"القديس أرسانيوس\",\"p\":50,\"n\":20,\"c\":\"قالها الأب أرسانيوس وهو مريض في الأسقيط حين أخذ حسنة من أحدهم لعوزه\",\"t\":\"أشكرك ربي، لأنك أهلتني أن آخذ حسنة من أجل اسمك.\",\"g\":[\"الشكر\",\"الاتضاع\"],\"k\":\"50.20\"},{\"i\":38,\"f\":\"القديس أرسانيوس\",\"p\":51,\"n\":25,\"c\":\"لما زار مكاناً فيه قصب حركته الريح فاهتز، وقال الإخوة: إنه القصب\",\"t\":\"في الحقيقة إذا أقام الإنسان في السكينة وسمع صوت عصفور لا يكون في قلبه الهدوء نفسه. فكم بالحري حالكم أنتم الذين عندكم اهتزاز القصب هذا.\",\"g\":[\"الصمت\",\"الخلوة\",\"الأفكار\"],\"k\":\"51.25\"},{\"i\":39,\"f\":\"القديس أرسانيوس\",\"p\":53,\"n\":31,\"c\":\"قالوا عنهما إنهما كانا يمقتان مجد الناس أكثر من الجميع\",\"t\":\"الأب أرسانيوس لم يكن يقابل أحداً بسهولة، في حين أن الأب ثيوذورس كان يستقبل الناس، لكنه كان كالسيف.\",\"g\":[\"المجد الباطل\",\"الاتضاع\"],\"k\":\"53.31\"},{\"i\":40,\"f\":\"القديس أرسانيوس\",\"p\":55,\"n\":35,\"c\":\"قاله لتلميذه الأب دانيال\",\"t\":\"أرح أباك، حتى أنه عندما ينتقل إلى الرب، يصلي من أجلك لكي يأتيك الخير.\",\"g\":[\"الطاعة\",\"المحبة\"],\"k\":\"55.35\"},{\"i\":41,\"f\":\"القديس أرسانيوس\",\"p\":57,\"n\":39,\"c\":\"عند اقترابه من الموت\",\"t\":\"لا تهتموا بفعل أعمال المحبة من أجلي، لأني إذا كنت قد قمت بها لنفسي، فهذا ما سوف أجد.\",\"g\":[\"المحبة\",\"الرحمة\",\"ذكر الموت\"],\"k\":\"57.39\"},{\"i\":42,\"f\":\"القديس أرسانيوس\",\"p\":57,\"n\":40,\"c\":\"قاله لتلاميذه قبيل رحيله\",\"t\":\"مراراً كثيرة ندمت لأني تكلمت، ولكن عن الصمت لم أندم.\",\"g\":[\"الصمت\",\"اللسان\"],\"k\":\"57.40a\"},{\"i\":43,\"f\":\"القديس أرسانيوس\",\"p\":57,\"n\":40,\"c\":\"أجاب الإخوة الذين سألوه: هل تخاف أنت أيضاً يا أبانا؟\",\"t\":\"إن الخوف الذي يلازمني الآن كان معي منذ أن صرت راهباً.\",\"g\":[\"خوف الله\",\"السهر\"],\"k\":\"57.40b\"},{\"i\":44,\"f\":\"القديس أرسانيوس\",\"p\":57,\"n\":41,\"c\":\"قاله الأب بيمن لما رأى الأب أرسانيوس يبكي نفسه\",\"t\":\"من لا يبكي نفسه هنا، سيبكي هناك أبداً. فالإنسان لا بد له أن يبكي، إما هنا طوعاً، أو هناك من العذابات.\",\"g\":[\"الدموع\",\"التوبة\",\"ذكر الموت\"],\"k\":\"57.41\"},{\"i\":45,\"f\":\"القديس أرسانيوس\",\"p\":58,\"n\":44,\"c\":\"قاله لشيوخ جاءوا يطلبون منه كلمة عن الهدوئيين\",\"t\":\"هكذا هي أمور النفس، من اللحظة التي تعلن فيها لا تقدر أن ترضي الجميع.\",\"g\":[\"الخلوة\",\"المجد الباطل\",\"الحكمة\"],\"k\":\"58.44\"},{\"i\":46,\"f\":\"القديس أغاثون\",\"p\":59,\"n\":2,\"t\":\"على الراهب ألا يترك ضميره يؤنبه لأي شيء مهما كان.\",\"g\":[\"التمييز\",\"التوبة\",\"الحكمة\"],\"k\":\"59.2\"},{\"i\":47,\"f\":\"القديس أغاثون\",\"p\":59,\"n\":3,\"t\":\"بدون حفظ الوصايا الإلهية، لا يستطيع الإنسان أن يتقدم ولا في فضيلة واحدة.\",\"g\":[\"الكتاب المقدس\",\"الجهاد\"],\"k\":\"59.3\"},{\"i\":48,\"f\":\"القديس أغاثون\",\"p\":59,\"n\":4,\"t\":\"لم أخلد إلى النوم يوماً وفي قلبي شيء على أحد، ولم أترك أحداً ينام وفي قلبه عليّ شيء. هذا كنت أفعله على قدر طاقتي.\",\"g\":[\"الغفران\",\"السلام\",\"الغضب\"],\"k\":\"59.4\"},{\"i\":49,\"f\":\"القديس أغاثون\",\"p\":60,\"n\":8,\"c\":\"سُئل: ما الأعظم، التعب الجسدي أم ضبط ما في الداخل؟\",\"t\":\"الإنسان يشبه شجرة، والتعب الجسدي هو الورق. أما ضبط ما في الداخل فهو الثمر. من الواضح أن كل اهتمامنا يجب أن ينصبّ على الثمر، أي على حفظ العقل الأعلى. ولكن غطاء الورق وزينته ضروريان.\",\"g\":[\"الجهاد\",\"الأفكار\",\"الحكمة\"],\"k\":\"60.8\"},{\"i\":50,\"f\":\"القديس أغاثون\",\"p\":61,\"n\":9,\"c\":\"جوابًا للإخوة: ما هي الفضيلة التي تتطلب تعباً أكثر من سواها؟\",\"t\":\"لا يوجد تعب كتعب الصلاة إلى الله. لأن الإنسان عندما يريد أن يصلّي إلى الله، يسعى الأعداء لإيقافه، لأنهم يعرفون أن لا شيء يعيقهم كالصلاة. إلا أن الصلاة تحتاج إلى جهاد يدوم حتى النسمة الأخيرة.\",\"g\":[\"الصلاة\",\"الجهاد\",\"الصبر\"],\"k\":\"61.9\"},{\"i\":51,\"f\":\"القديس أغاثون\",\"p\":61,\"n\":10,\"t\":\"كان الأب أغاثون حكيماً في التفكير، عديم التعب في الجسد، مكتفياً في كل شيء، في العمل والمأكل والملبس.\",\"g\":[\"الحكمة\",\"الزهد\"],\"k\":\"61.10\"},{\"i\":52,\"f\":\"القديس أغاثون\",\"p\":62,\"n\":15,\"c\":\"قالوا عن الأب أغاثون\",\"t\":\"أمضى ثلاث سنين جاعلاً في فمه حجراً، حتى تعلّم أن يصمت.\",\"g\":[\"الصمت\",\"اللسان\"],\"k\":\"62.15\"},{\"i\":53,\"f\":\"القديس أغاثون\",\"p\":62,\"n\":18,\"t\":\"عندما يرى شيئاً ويتحرك فكره للحكم عليه، يقول لنفسه: يا أغاثون، لا تفعل أنت هذا. وهكذا كانت أفكاره تهدأ.\",\"g\":[\"الإدانة\",\"الأفكار\"],\"k\":\"62.18\"},{\"i\":54,\"f\":\"القديس أغاثون\",\"p\":62,\"n\":19,\"t\":\"لو أقام الغضوب ميتاً، لن يكون مقبولاً عند الله.\",\"g\":[\"الغضب\",\"الوداعة\"],\"k\":\"62.19\"},{\"i\":55,\"f\":\"القديس أغاثون\",\"p\":62,\"n\":21,\"c\":\"جوابًا لأخ سأله عن الزنى\",\"t\":\"اذهب واطرح ضعفك أمام الله تجد راحة.\",\"g\":[\"الشهوة\",\"التوبة\",\"الصلاة\"],\"k\":\"62.21\"},{\"i\":56,\"f\":\"القديس أغاثون\",\"p\":63,\"n\":23,\"t\":\"إذا كان هناك إنسان أحبه بإفراط، ولكن فهمت أنه يقودني إلى السوء، أقطعه عني.\",\"g\":[\"التمييز\",\"الجهاد\",\"الشركة\"],\"k\":\"63.23\"},{\"i\":57,\"f\":\"القديس أغاثون\",\"p\":63,\"n\":24,\"t\":\"يجب على الإنسان أن يضع المحبة الرهبية نصب عينيه على الدوام.\",\"g\":[\"المحبة\",\"السهر\"],\"k\":\"63.24\"},{\"i\":58,\"f\":\"القديس أغاثون\",\"p\":63,\"n\":26,\"t\":\"لو كان ممكناً أن أجد أبرص أعطيه جسدي وآخذ جسده لكنت سعيداً. لأن هذه هي المحبة الكاملة.\",\"g\":[\"المحبة\",\"الرحمة\",\"الخدمة\"],\"k\":\"63.26\"},{\"i\":59,\"f\":\"القديس أغاثون\",\"p\":64,\"n\":29,\"t\":\"بدون صحو كثير لا يستطيع الإنسان أن يتقدم ولا في فضيلة واحدة.\",\"g\":[\"السهر\",\"الجهاد\"],\"k\":\"64.29\"},{\"i\":60,\"f\":\"القديس أمون\",\"p\":66,\"n\":1,\"c\":\"جوابًا لأخ قال له: قل لي كلمة\",\"t\":\"اذهب وافحص أفكارك كما يفعل فاعلو الشر في السجن، لأن هؤلاء دائماً يسألون الناس أين الرئيس؟ متى يأتي؟ ويكون من طول الانتظار. هكذا الراهب عليه أن يتيقظ دائماً ويحاسب نفسه قائلاً: ويل لي! كيف سأقف أمام منبر المسيح؟ ماذا سأجيبه؟ وأنت أيضاً، إذا فكرت هكذا دائماً، تقدر أن تخلص.\",\"g\":[\"الأفكار\",\"السهر\",\"خوف الله\",\"التوبة\"],\"k\":\"66.1\"},{\"i\":61,\"f\":\"القديس أمون\",\"p\":66,\"n\":3,\"t\":\"لقد أمضيت أربع عشرة سنة في الاسقيط متضرعاً إلى الله ليل نهار أن يمنحني القوة لأتغلب على الغضب.\",\"g\":[\"الغضب\",\"الصلاة\",\"الصبر\"],\"k\":\"66.3\"},{\"i\":62,\"f\":\"القديس أمون\",\"p\":66,\"n\":4,\"c\":\"لشيخ كان يلبس مسوحاً ويفكر أن يطوف في البراري أو يغترب أو يحبس نفسه\",\"t\":\"امكثْ في قلايتك وكلْ قليلاً كلَّ يوم، وليكن في قلبك كلام العشّار، فتخلص.\",\"g\":[\"الاتضاع\",\"الخلوة\",\"التوبة\"],\"k\":\"66.4\"},{\"i\":63,\"f\":\"القديس أمون\",\"p\":67,\"n\":6,\"c\":\"جوابًا لمن سأله: لماذا أصعد إلى مركب خاص وأنا أحيك الخوص؟\",\"t\":\"لكي لا أجاري أفكاري. وهذا كان مثلاً لنا لكي نسلك طريق الرب بهدوء وسكينة.\",\"g\":[\"الصمت\",\"الأفكار\",\"الخلوة\"],\"k\":\"67.6\"},{\"i\":64,\"f\":\"القديس أمون\",\"p\":68,\"n\":11,\"c\":\"سُئل: ما هي الطريق الضيقة المحزنة؟ (متى 7: 14)\",\"t\":\"الطريق الضيقة والمحزنة هي أن يمسك الإنسان أفكاره ويقطع مشيئته حباً بالله. وهذا هو معناه: «ها نحن قد تركنا كل شيء وتبعناك».\",\"g\":[\"الأفكار\",\"الجهاد\",\"الطاعة\"],\"k\":\"68.11\"},{\"i\":65,\"f\":\"القديس أمون\",\"p\":68,\"n\":8,\"c\":\"عن امرأة اتُّهمت، فأطلقها ولم يتجاسر أن يدين أحداً\",\"t\":\"انظروا يا إخوتي، إنها على وشك أن تموت. أما أنا، فما عساني أقدر أن أفعل؟\",\"g\":[\"الإدانة\",\"الرحمة\"],\"k\":\"68.8\"},{\"i\":66,\"f\":\"الأب أموي\",\"p\":72,\"n\":4,\"c\":\"قاله بيمين: زار أخ الأب أموي طالباً منه كلمة، وبعد سبعة أيام من الصمت قال له\",\"t\":\"اذهب وانتبه لنفسك. أما أنا فخطاياي قد صارت جداراً مظلماً بيني وبين الله.\",\"g\":[\"التوبة\",\"الاتضاع\",\"الصمت\"],\"k\":\"72.4\"},{\"i\":67,\"f\":\"الأب أموي\",\"p\":72,\"n\":5,\"c\":\"لتلاميذه وقد حزنوا لرحيلهم عن مكان رآه غير نافع\",\"t\":\"أتحزنون من أجل الخبز؟ في الواقع إني رأيت البعض يغادرون بيوتهم تاركين كل شيء دون أن يغلقوا الأبواب، بل تركوها مفتوحة على مصراعيها.\",\"g\":[\"الزهد\",\"الرجاء\"],\"k\":\"72.5\"},{\"i\":68,\"f\":\"القديس أمون النطروني\",\"p\":73,\"n\":1,\"c\":\"جواب القديس أنطونيوس لأمون الذي قال له: أنا أتعب أكثر منك، فكيف يتمجد اسمك بين الناس أكثر مني؟\",\"t\":\"أنا أحب الله أكثر منك.\",\"g\":[\"المحبة\",\"الاتضاع\",\"المجد الباطل\"],\"k\":\"73.1\"},{\"i\":69,\"f\":\"القديس أمون النطروني\",\"p\":73,\"n\":3,\"c\":\"لأخ أرسله أبوه في خدمة وخاف الزنى\",\"t\":\"عندما تأتيك التجربة قل: يا إله القوات، بصلوات أبي أعتقني.\",\"g\":[\"الصلاة\",\"الشهوة\",\"الجهاد\"],\"k\":\"73.3\"},{\"i\":70,\"f\":\"الأب أنوف\",\"p\":75,\"n\":2,\"t\":\"منذ أن حلّ عليّ اسم المسيح، لم يخرج من فمي كذب.\",\"g\":[\"اللسان\",\"الإيمان\"],\"k\":\"75.2\"},{\"i\":71,\"f\":\"الأب إبراهيم\",\"p\":76,\"n\":1,\"c\":\"قاله لشيخ قال: «لقد قتلت الزنى وحب الفضة والمجد الفارغ»\",\"t\":\"لم تقتله، فالهوى ما زال حياً فيك، إنما قد قيّد. الأهواء ما تزال حيّة، إلا أنها قد لجمت عند القديسين.\",\"g\":[\"الجهاد\",\"الشهوة\",\"الاتضاع\",\"المجد الباطل\"],\"k\":\"76.1\"},{\"i\":72,\"f\":\"الأب ألونيوس\",\"p\":78,\"n\":1,\"t\":\"إذا لم يقل الإنسان في قلبه: «أنا والله، فقط، في العالم»، لن يجد راحة البتة.\",\"g\":[\"الخلوة\",\"الصلاة\"],\"k\":\"78.1\"},{\"i\":73,\"f\":\"الأب ألونيوس\",\"p\":78,\"n\":2,\"t\":\"إذا لم أهدم كل شيء لا أستطيع أن أبني نفسي.\",\"g\":[\"التوبة\",\"الاتضاع\"],\"k\":\"78.2\"},{\"i\":74,\"f\":\"الأب ألونيوس\",\"p\":78,\"n\":3,\"t\":\"إذا أراد الإنسان يقدر أن يصل إلى القامة الإلهية من الصباح حتى المساء.\",\"g\":[\"الجهاد\",\"الرجاء\"],\"k\":\"78.3\"},{\"i\":75,\"f\":\"الأب أبو للوس\",\"p\":80,\"n\":1,\"c\":\"كان يقولها بفرح كلما قصده الناس في طلب خدمة\",\"t\":\"اليوم سأشتغل مع المسيح من أجل نفسي، لأن هذا هو أجرها.\",\"g\":[\"الخدمة\",\"الفرح\",\"المحبة\"],\"k\":\"80.1\"},{\"i\":76,\"f\":\"الأب أبو للوس\",\"p\":80,\"n\":2,\"c\":\"صلاة كان يرددها دائماً الليل والنهار\",\"t\":\"لقد خطئت كإنسان، ولكن أنت كإله ارحمني.\",\"g\":[\"الصلاة\",\"التوبة\",\"الرجاء\"],\"k\":\"80.2\"},{\"i\":77,\"f\":\"الأب أبو للوس\",\"p\":80,\"n\":3,\"c\":\"عن استقبال الإخوة\",\"t\":\"ينبغي أن ننحني للإخوة الذين يأتون إلينا، لأننا لا ننحني لهم إنما لله. لأنه يقول: إذا رأيت أخاك رأيت الرب إلهك.\",\"g\":[\"الضيافة\",\"الاتضاع\",\"المحبة\"],\"k\":\"80.3\"},{\"i\":78,\"f\":\"الأب أندراوس\",\"p\":81,\"n\":1,\"t\":\"الراهب تناسبه هذه الثلاثة: غربة، فقر وصمت مع صبر.\",\"g\":[\"الزهد\",\"الصمت\",\"الصبر\"],\"k\":\"81.1\"},{\"i\":79,\"f\":\"الأب بيساريوس\",\"p\":84,\"n\":1,\"c\":\"جواب لتلميذه حين رآه يملأ وعاءه ماء تحسباً للعطش بعد حين\",\"t\":\"الله هنا وفي كل مكان.\",\"g\":[\"الإيمان\",\"الرجاء\",\"الصلاة\"],\"k\":\"84.1\"},{\"i\":80,\"f\":\"الأب بيساريوس\",\"p\":86,\"n\":7,\"c\":\"لما فُرز أخ خاطئ وطرده الكاهن من الكنيسة، نهض بيساريوس وخرج معه\",\"t\":\"وأنا أيضاً خاطىء.\",\"g\":[\"الرحمة\",\"الإدانة\",\"الاتضاع\"],\"k\":\"86.7\"},{\"i\":81,\"f\":\"الأب بيساريوس\",\"p\":86,\"n\":9,\"t\":\"عندما تكون في سلام وغير محارَب، عندئذ اتّضع أكثر، إذ إننا ربما بسبب دخول فرح غريب، نفتخر فنسلَّم للمعارك، لأن الله لا يسمح مراراً كثيرة أن نسلَّم إلى المعارك، بسبب ضعفاتنا، لئلا نضيع.\",\"g\":[\"الاتضاع\",\"الكبرياء\",\"الجهاد\"],\"k\":\"86.9\"},{\"i\":82,\"f\":\"الأب بيساريوس\",\"p\":86,\"n\":10,\"c\":\"جوابًا لأخ يقيم مع إخوة سأله: ماذا أعمل؟\",\"t\":\"أصمت ولا تقارن نفسك بالآخرين.\",\"g\":[\"الصمت\",\"الاتضاع\",\"الإدانة\"],\"k\":\"86.10\"},{\"i\":83,\"f\":\"الأب بيساريوس\",\"p\":86,\"n\":11,\"c\":\"قاله وهو على فراش الموت\",\"t\":\"ينبغي أن يكون الراهب كالشاروبيم والسارافيم، كلّه عين.\",\"g\":[\"السهر\",\"الصلاة\"],\"k\":\"86.11\"},{\"i\":84,\"f\":\"الأب بنيامين\",\"p\":88,\"n\":4,\"c\":\"قاله لأبنائه وهو في النزاع الأخير\",\"t\":\"اعلموا هذا فتخلصوا: «دائماً افرحوا، صلّوا بلا انقطاع، واشكروا على كل شيء» (1 تس 5: 16).\",\"g\":[\"الفرح\",\"الصلاة\",\"الشكر\"],\"k\":\"88.4\"},{\"i\":85,\"f\":\"الأب بنيامين\",\"p\":88,\"n\":5,\"t\":\"اسلكوا الطريق الملوكي واحصوا الأميال ولا تكونوا غير مبالين.\",\"g\":[\"السهر\",\"الجهاد\",\"الصبر\"],\"k\":\"88.5\"},{\"i\":86,\"f\":\"الأب بياري\",\"p\":89,\"n\":1,\"c\":\"جوابًا لأخ سأله: ماذا أعمل لأخلص؟\",\"t\":\"اذهب واجعل بطنك صغيراً وقلّل عمل يديك ولا تضطرب في قلايتك فتخلص.\",\"g\":[\"الصوم\",\"الخلوة\",\"السلام\"],\"k\":\"89.1a\"},{\"i\":87,\"f\":\"القديس غريغوريوس اللاهوتي\",\"p\":89,\"n\":1,\"t\":\"ثلاثة أمور يطلبها الله من الإنسان الذي اقتبل سر المعمودية: الإيمان القويم من كل النفس، الحقيقة من الفم، والتعقل من الجسد.\",\"g\":[\"الإيمان\",\"اللسان\",\"الحكمة\"],\"k\":\"89.1b\"},{\"i\":88,\"f\":\"القديس غريغوريوس اللاهوتي\",\"p\":89,\"n\":2,\"t\":\"حياة الإنسان كلها يوم واحد بالنسبة للذين يتعبون بشوق.\",\"g\":[\"الجهاد\",\"الرجاء\",\"الصبر\"],\"k\":\"89.2\"},{\"i\":89,\"f\":\"الأب جيلاسيوس\",\"p\":90,\"n\":1,\"c\":\"قاله للأخ الذي سرق كتابه ثم عاد نادماً وقال: إن لم تأخذه لن أكون في راحة\",\"t\":\"إذا كنت لن ترتاح عندئذ سأقبله.\",\"g\":[\"الغفران\",\"الرحمة\",\"الاتضاع\"],\"k\":\"90.1\"},{\"i\":90,\"f\":\"الأب جيلاسيوس\",\"p\":93,\"n\":5,\"c\":\"جوابًا لشيخ فقير قال له: أخشى أن يرتبط تفكيرك بالحقول والأراضي\",\"t\":\"إن تفكيرك ارتبط بالمشغل الذي تشتغل به أكثر بكثير من ارتباط تفكير جيلاسيوس بالأملاك.\",\"g\":[\"الزهد\",\"الأفكار\",\"التمييز\"],\"k\":\"93.5\"},{\"i\":91,\"f\":\"الأب جيلاسيوس\",\"p\":94,\"n\":6,\"c\":\"قاله لنفسه وقد تعب من السير في البرية بلا نوم تحت سقف\",\"t\":\"إذا كنت لا تستطيع أن تعمل أعمال البرية اجلس في قلايتك بتجلد وصبر باكياً خطاياك، ولا تضل. لأن عين الله ترى في كل مكان أفعال الناس ولا يخفى عليه شيء البتة، ويعرف أولئك الذين يعملون الأعمال الصالحة.\",\"g\":[\"الخلوة\",\"الصبر\",\"التوبة\",\"الدموع\"],\"k\":\"94.6\"},{\"i\":92,\"f\":\"الأب يرونديوس\",\"p\":94,\"n\":1,\"t\":\"إن كثيرين من الذين يجرِّبون بلذات الجسد دون أن يقتربوا من الأجساد، قد زنوا بالفكر. إذ بينما تبقى الأجساد بكراً يزنون بالنفس. حسن إذن يا أحبائي أن نعمل ما هو مكتوب، وأن يحفظ كل واحد قلبه بكل يقظة وصحو.\",\"g\":[\"الأفكار\",\"السهر\",\"الشهوة\"],\"k\":\"94.1\"},{\"i\":93,\"f\":\"الأب دانيال\",\"p\":95,\"n\":1,\"c\":\"لما جاء البرابرة إلى الأسقيط هرب الآباء، فقال الأب دانيال هذا ثم اجتاز في وسطهم فلم يروه\",\"t\":\"إذا كان الله لا يهتم بي، لماذا أحيا؟\",\"g\":[\"الإيمان\",\"الرجاء\",\"الصلاة\"],\"k\":\"95.1\"},{\"i\":94,\"f\":\"الأب دانيال\",\"p\":96,\"n\":4,\"t\":\"بمقدار ما ينتعش الجسد تضعف النفس. وبمقدار ما يضعف الجسد تنتعش النفس.\",\"g\":[\"الصوم\",\"الجهاد\",\"الحكمة\"],\"k\":\"96.4\"},{\"i\":95,\"f\":\"الأب دانيال\",\"p\":96,\"n\":5,\"c\":\"جوابًا للأب أمويس لما سأله: متى سنجلس في القلاية يا أبت؟\",\"t\":\"ترى من ينزع الله منا؟ الله في القلاية وخارجها.\",\"g\":[\"الإيمان\",\"الخلوة\",\"الصلاة\"],\"k\":\"96.5\"},{\"i\":96,\"f\":\"الأب ديوسقورس\",\"p\":98,\"n\":2,\"c\":\"جواب تلميذه الذي وجده غارقاً في البكاء وسأله: لماذا تبكي يا أبت؟\",\"t\":\"أبكي خطاياي يا ولدي.\",\"g\":[\"الدموع\",\"التوبة\"],\"k\":\"98.2\"},{\"i\":97,\"f\":\"الأب دولاس\",\"p\":99,\"n\":1,\"t\":\"إذا أرغمنا العدو على هجر السكينة ينبغي أن لا نصغي إليه لأنه لا شيء يماثلها في الوجود. كذلك هو الحال مع الصوم. فالصوم يقترن بالسكينة في تحالف ضد العدو. وهذان يعطيان العين الداخلية وضوحاً في الرؤية وحدّة في النظر.\",\"g\":[\"الخلوة\",\"الصوم\",\"الجهاد\"],\"k\":\"99.1\"},{\"i\":98,\"f\":\"الأب دولاس\",\"p\":99,\"n\":2,\"t\":\"اقطع علاقتك مع الكثيرين حتى لا تكون حربك مع العقل الأعلى مزعجة، فتثير الاضطراب في طريقة هدوئك.\",\"g\":[\"الخلوة\",\"الصمت\",\"السلام\"],\"k\":\"99.2\"},{\"i\":99,\"f\":\"القديس إبيفانيوس أسقف قبرص\",\"p\":100,\"n\":3,\"c\":\"قاله لرئيس دير أهمل صلوات ساعات النهار الأخرى\",\"t\":\"الراهب الحقيقي ينبغي أن يحوي الصلاة في قلبه على الدوام.\",\"g\":[\"الصلاة\",\"السهر\"],\"k\":\"100.3\"},{\"i\":100,\"f\":\"القديس إبيفانيوس أسقف قبرص\",\"p\":101,\"n\":9,\"t\":\"إن قراءة الكتب المقدسة ضمانة كبيرة للهرب من الخطيئة.\",\"g\":[\"الكتاب المقدس\",\"الجهاد\"],\"k\":\"101.9\"},{\"i\":101,\"f\":\"القديس إبيفانيوس أسقف قبرص\",\"p\":101,\"n\":10,\"t\":\"إن جهل الكتب المقدسة هاوية عميقة ومنخفض سحيق.\",\"g\":[\"الكتاب المقدس\",\"الحكمة\"],\"k\":\"101.10\"},{\"i\":102,\"f\":\"القديس إبيفانيوس أسقف قبرص\",\"p\":102,\"n\":16,\"t\":\"بالرخص الشديد يبيع الله البرّ للذين يبادرون إلى شرائه: بقطعة خبز صغيرة وثياب وضيعة وكأس ماء بارد وبفلس واحد.\",\"g\":[\"الزهد\",\"الرحمة\",\"الجهاد\"],\"k\":\"102.16\"},{\"i\":103,\"f\":\"القديس أفرام\",\"p\":103,\"n\":3,\"c\":\"قاله لامرأة زانية جاءت تجربه بكلماتها، فاقتادها إلى مكان يعج بالناس\",\"t\":\"إذا كنا نستحي من الناس فكم بالحرى ينبغي لنا أن نخجل من الله الذي يفحص خفايا القلوب.\",\"g\":[\"خوف الله\",\"الشهوة\",\"الاتضاع\"],\"k\":\"103.3\"},{\"i\":104,\"f\":\"الأب أفربيوس\",\"p\":106,\"n\":3,\"t\":\"الجسديات مادة. فالذي يحب العالم يحب العشرة. لذلك إذا حدث وفقدنا شيئاً لنا، علينا أن نقبل هذا بفرح وحمد على أننا قد انعتقنا وتحرّرنا من بعض الاهتمامات.\",\"g\":[\"الزهد\",\"الشكر\",\"الفرح\"],\"k\":\"106.3\"},{\"i\":105,\"f\":\"الأب أفربيوس\",\"p\":106,\"n\":4,\"c\":\"جوابًا لأخ سأله عن الحياة\",\"t\":\"كل عشباً، البس عشباً، نم بين الأعشاب. فقط اجعل قلبك من حديد.\",\"g\":[\"الزهد\",\"الصبر\",\"الجهاد\"],\"k\":\"106.4\"},{\"i\":106,\"f\":\"الأب أفربيوس\",\"p\":107,\"n\":6,\"t\":\"فليلازمك خوف الله والتواضع والحرمان من الأطعمة وأيضاً النوح.\",\"g\":[\"خوف الله\",\"الاتضاع\",\"الصوم\",\"الدموع\"],\"k\":\"107.6\"},{\"i\":107,\"f\":\"الأب أفربيوس\",\"p\":107,\"n\":7,\"c\":\"جواب ناسك للأب أفربيوس في بداية حياته لما سأله: قل لي كلمة، كيف أخلص؟\",\"t\":\"إذا أردت أن تخلص لازم عدم الكلام ولا تسبق أحداً إليه. لا تتكلم قبل أن يسألوك.\",\"g\":[\"الصمت\",\"اللسان\",\"الاتضاع\"],\"k\":\"107.7\"},{\"i\":108,\"f\":\"الأب إفاغريوس\",\"p\":108,\"n\":1,\"t\":\"عندما تجلس في قلايتك اجمع فكرك. تذكر أيام الموت. تأمل عندئذ في موت الجسد وافهم المصيبة. التزم الألم وامقت أباطيل العالم لكي تتمكن من أن تثبت في السكينة، ولا تضعف.\",\"g\":[\"ذكر الموت\",\"الخلوة\",\"الصبر\"],\"k\":\"108.1\"},{\"i\":109,\"f\":\"الأب إفاغريوس\",\"p\":108,\"n\":2,\"t\":\"اقطع علاقتك مع كثيرين لئلا يصير عقلك كثير الاهتمامات فيضطرب هدوءك.\",\"g\":[\"الخلوة\",\"السلام\",\"الصمت\"],\"k\":\"108.2\"},{\"i\":110,\"f\":\"الأب إفاغريوس\",\"p\":109,\"n\":3,\"t\":\"عظيم أن يصلّي المرء بدون شرود لكن الأعظم هو أن يرتل بدون تشتت.\",\"g\":[\"الصلاة\",\"السهر\"],\"k\":\"109.3\"},{\"i\":111,\"f\":\"الأب إفاغريوس\",\"p\":109,\"n\":4,\"t\":\"تذكّر على الدوام ساعة خروجك ولا تنسَ الدينونة الأبدية، فلا توجد في نفسك خطيئة.\",\"g\":[\"ذكر الموت\",\"خوف الله\",\"السهر\"],\"k\":\"109.4\"},{\"i\":112,\"f\":\"الأب إفاغريوس\",\"p\":109,\"n\":5,\"t\":\"أبعِدْ التجارب، فلا يخلص أحد.\",\"g\":[\"الجهاد\",\"الصبر\",\"الضيقات\"],\"k\":\"109.5\"},{\"i\":113,\"f\":\"الأب إفاغريوس\",\"p\":109,\"n\":6,\"c\":\"ينقله عن أحد الآباء\",\"t\":\"أقسى أساليب الحياة هو الذي يقترن بالمحبة، إذ سرعان ما يدخل الراهب إلى ميناء اللاهوى.\",\"g\":[\"المحبة\",\"الجهاد\",\"السلام\"],\"k\":\"109.6\"},{\"i\":114,\"f\":\"الأب زينون\",\"p\":110,\"n\":1,\"c\":\"قاله لتلميذه سلوان\",\"t\":\"لا تقم في مكان معروف، ولا تجالس إنساناً ذائع الصيت، ولا تضع قاعدة تبني فوقها منسكاً خاصاً بك.\",\"g\":[\"الخلوة\",\"المجد الباطل\",\"الاتضاع\"],\"k\":\"110.1\"},{\"i\":115,\"f\":\"الأب زينون\",\"p\":110,\"n\":2,\"c\":\"قاله لما رأى أن كل من يأتون إليه يعودون محزونين\",\"t\":\"إذا قدّم لي أحد شيئاً آخذه، وإذا جاء أحد يطلب شيئاً أعطيه إياه.\",\"g\":[\"الرحمة\",\"المحبة\",\"السلام\"],\"k\":\"110.2\"},{\"i\":116,\"f\":\"الأب زينون\",\"p\":111,\"n\":7,\"t\":\"إن من يريد الله أن يستجيب صلاته، عليه قبل كل شيء عندما ينهض للصلاة ويمد يديه نحو الله، أن يصلّي أولاً من أجل أعدائه. وإذا ما فعل هذا فإن الله يستجيب لكل طلباته.\",\"g\":[\"الصلاة\",\"الغفران\",\"المحبة\"],\"k\":\"111.7\"},{\"i\":117,\"f\":\"الأب زخريا\",\"p\":113,\"n\":1,\"c\":\"جواب الأب زخريا للأب مكاريوس لما سأله: ما هو عمل الراهب؟\",\"t\":\"برأيي يا أبتِ، الراهب هو من غصب نفسه في كل شيء.\",\"g\":[\"الجهاد\",\"الطاعة\",\"الصبر\"],\"k\":\"113.1\"},{\"i\":118,\"f\":\"الأب زخريا\",\"p\":113,\"n\":3,\"c\":\"قاله وهو ينزع عمامته ويطرحها تحت قدميه ويدوسها، لما سأله الأب موسى: قل لي ماذا أعمل؟\",\"t\":\"إذا لم ينسحق الإنسان هكذا لا يقدر أن يصبح راهباً.\",\"g\":[\"الاتضاع\",\"التوبة\",\"الكبرياء\"],\"k\":\"113.3\"},{\"i\":119,\"f\":\"الأب زخريا\",\"p\":114,\"n\":5,\"c\":\"جواب الأب زخريا للأب موسى عند موته لما سأله: ماذا ترى؟\",\"t\":\"أليس من الأفضل أن نصمت يا أبتِ؟\",\"g\":[\"الصمت\",\"ذكر الموت\"],\"k\":\"114.5\"},{\"i\":120,\"f\":\"الأب أشعيا\",\"p\":115,\"n\":1,\"t\":\"لا شيء ينفع المبتدىء كالشتم والإهانة، لأنه، كما أن الشجرة ترتوي كل يوم، هكذا المبتدىء الذي يُشتم فيحتمل.\",\"g\":[\"الصبر\",\"الاتضاع\",\"الضيقات\"],\"k\":\"115.1\"},{\"i\":121,\"f\":\"الأب أشعيا\",\"p\":115,\"n\":2,\"t\":\"كما أن الغصن الغضّ ينحني بسهولة، هكذا يكون المبتدئون في الطاعة.\",\"g\":[\"الطاعة\",\"الاتضاع\"],\"k\":\"115.2\"},{\"i\":122,\"f\":\"الأب أشعيا\",\"p\":116,\"n\":7,\"t\":\"إذا أراد الله أن يرأف بنفس ويرحمها، تجمح ولا تحتمل وتفعل مشيئتها، فيسمح الله أن تذوق ما لا تريد حتى إنها بهذه الطريقة تفتش عنه.\",\"g\":[\"الرحمة\",\"الضيقات\",\"التوبة\"],\"k\":\"116.7\"},{\"i\":123,\"f\":\"الأب أشعيا\",\"p\":116,\"n\":8,\"t\":\"عندما يريد الإنسان أن يقابل الشر بالشر، فإنه يستطيع، بإيماءة فقط، أن يؤذي ضمير قريبه.\",\"g\":[\"الغضب\",\"المحبة\",\"الاتضاع\"],\"k\":\"116.8\"},{\"i\":124,\"f\":\"الأب أشعيا\",\"p\":116,\"n\":9,\"c\":\"جوابًا لمن سأله: ما هي محبة الفضة؟\",\"t\":\"هي عدم الإيمان بأن الله يهتم بك، واليأس من وعوده، ومحبة الافتخار والعظمة.\",\"g\":[\"الطمع\",\"الإيمان\",\"الرجاء\"],\"k\":\"116.9\"},{\"i\":125,\"f\":\"الأب أشعيا\",\"p\":116,\"n\":10,\"c\":\"جوابًا لمن سأله: وما هو الغضب؟\",\"t\":\"إنه الجهل والخصام والكذب.\",\"g\":[\"الغضب\",\"السلام\"],\"k\":\"116.10\"},{\"i\":126,\"f\":\"الأب أشعيا\",\"p\":116,\"n\":11,\"c\":\"جوابًا لمن سأله: وما هي المذمة؟\",\"t\":\"هي جهلنا مجّدَ الله وحسدنا القريبَ.\",\"g\":[\"الإدانة\",\"اللسان\",\"الاتضاع\"],\"k\":\"116.11\"},{\"i\":127,\"f\":\"الأب إيليا\",\"p\":117,\"n\":1,\"t\":\"أخاف ثلاثة: عندما توشك نفسي أن تفارق جسدي، وعندما انتصب أمام الله، وعندما يصدر الحكم بحقي.\",\"g\":[\"خوف الله\",\"ذكر الموت\",\"الاتضاع\"],\"k\":\"117.1\"},{\"i\":128,\"f\":\"الأب إيليا\",\"p\":117,\"n\":3,\"t\":\"ما قوة الخطيئة عندما توجد التوبة؟ كذلك، ما نفع المحبة عندما يظهر الكبرياء؟\",\"g\":[\"التوبة\",\"الكبرياء\",\"المحبة\"],\"k\":\"117.3\"},{\"i\":129,\"f\":\"الأب إيليا\",\"p\":117,\"n\":5,\"t\":\"يفكر الناس إما بالخطايا، أو بالمسيح، أو بالناس.\",\"g\":[\"الأفكار\",\"التمييز\",\"الإيمان\"],\"k\":\"117.5\"},{\"i\":130,\"f\":\"الأب إيليا\",\"p\":118,\"n\":8,\"c\":\"قاله الأب إيليا المدوئي لأخ زاره في دير القديس سابا وسأله كلمة\",\"t\":\"في أيام آبائنا كانت الفضائل الثلاث: اللاقنية، والامساك والوداعة، محبوبة جداً. والآن، يسود بين الرهبان الطمع والشراهة والوقاحة. وأمّا أنت، فاحتفظ بما تشاء.\",\"g\":[\"الزهد\",\"الوداعة\",\"الجهاد\"],\"k\":\"118.8\"},{\"i\":131,\"f\":\"الأب ثيوذورس الفرمي\",\"p\":120,\"n\":1,\"c\":\"جوابًا للأب مكاريوس لما سأله: هل أحتفظ بكتبي الجيدة لمنفعتي أم أبيعها لأعطي الفقراء؟\",\"t\":\"حسنة الأعمال، لكن عدم القنية أثمن من كل شيء.\",\"g\":[\"الزهد\",\"الرحمة\",\"الحكمة\"],\"k\":\"120.1\"},{\"i\":132,\"f\":\"الأب ثيوذورس الفرمي\",\"p\":121,\"n\":5,\"c\":\"قالوا عنه\",\"t\":\"أموراً ثلاثة كان يحترمها أكثر من سواها: اللاقنية، النسك، والهرب من الناس.\",\"g\":[\"الزهد\",\"الصوم\",\"الخلوة\"],\"k\":\"121.5\"},{\"i\":133,\"f\":\"الأب ثيوذورس الفرمي\",\"p\":121,\"n\":6,\"t\":\"لقد فقد الرهبان أدبهم عندما تخلوا عن كلمة «عفواً».\",\"g\":[\"الاتضاع\",\"الغفران\",\"الوداعة\"],\"k\":\"121.6\"},{\"i\":134,\"f\":\"الأب ثيوذورس الفرمي\",\"p\":121,\"n\":8,\"c\":\"لمن قال له: ها إن الأخ الفلاني قد عاد إلى العالم\",\"t\":\"ألهذا تتعجب؟ لا تتعجب لهذا؛ خير لك أن تتعجب عندما تسمع أن أحداً تمكّن من الهرب من فم العدو.\",\"g\":[\"الإدانة\",\"الرحمة\",\"الجهاد\"],\"k\":\"121.8\"},{\"i\":135,\"f\":\"الأب يوحنا الخصي\",\"p\":122,\"n\":10,\"c\":\"قاله للأب ثيوذورس الفرمي لما زاره\",\"t\":\"لما كنت في الاسقيط، كانت أمور النفس شغلنا الأول، وعمل اليد أمراً ثانياً. أما الآن فقد صارت أمور النفس ثانوية، وعمل اليد هو الأساس.\",\"g\":[\"الصلاة\",\"السهر\",\"الحكمة\"],\"k\":\"122.10\"},{\"i\":136,\"f\":\"الأب ثيوذورس الفرمي\",\"p\":122,\"n\":12,\"t\":\"إن من يقيم في التوبة لا يتقيّد بوصية.\",\"g\":[\"التوبة\",\"الرجاء\"],\"k\":\"122.12\"},{\"i\":137,\"f\":\"الأب ثيوذورس الفرمي\",\"p\":122,\"n\":13,\"t\":\"ليس ثمة فضيلة مثل عدم الازدراء.\",\"g\":[\"الاتضاع\",\"الإدانة\",\"الرحمة\"],\"k\":\"122.13\"},{\"i\":138,\"f\":\"الأب ثيوذورس الفرمي\",\"p\":123,\"n\":16,\"t\":\"كثيرون قد اختاروا الراحة هذه الأيام قبل أن يعطيهم إياها الله.\",\"g\":[\"الجهاد\",\"الصبر\",\"الضيقات\"],\"k\":\"123.16\"},{\"i\":139,\"f\":\"الأب ثيوذورس الفرمي\",\"p\":123,\"n\":20,\"c\":\"جوابًا لأخ قال له: قل لي كلمة لأني أكاد أن أهلك\",\"t\":\"أنا في خطر. ترى ماذا أقدر أن أقول لك؟\",\"g\":[\"الاتضاع\",\"خوف الله\"],\"k\":\"123.20\"},{\"i\":140,\"f\":\"الأب ثيوذورس الفرمي\",\"p\":124,\"n\":24,\"c\":\"جوابًا لمن سأله: إذا حصل بغتة انحراف في الأرض، ألا تخاف يا أبت؟\",\"t\":\"إذا التصقت السماء بالأرض ثيوذورس لا يخاف. لأنه تضرع إلى الله أن يفارقه الجبن والخوف.\",\"g\":[\"الإيمان\",\"الصلاة\",\"الرجاء\"],\"k\":\"124.24\"},{\"i\":141,\"f\":\"الأب ثيوذورس الأناتي\",\"p\":126,\"n\":3,\"t\":\"إذا حاسبنا الله على كسلنا في الصلاة وفتورنا في التراتيل، لا يمكننا أن نخلص البتة.\",\"g\":[\"الصلاة\",\"السهر\",\"التوبة\"],\"k\":\"126.3\"},{\"i\":142,\"f\":\"الأب ثيوذورس الذي من الاسقيط\",\"p\":127,\"n\":1,\"t\":\"يأتي الفكر فيزعجني ويشغلني ولا يساعدني على القيام بعملي، إنما كل شأنه أن يعيقني عن الفضيلة. أما الرجل الصاحي فينهض للصلاة عندما يهاجمه الفكر.\",\"g\":[\"الأفكار\",\"الصلاة\",\"السهر\"],\"k\":\"127.1a\"},{\"i\":143,\"f\":\"الأب ثيوذوتس\",\"p\":127,\"n\":1,\"t\":\"إن حاجة الخبز تذيب جسد الراهب. وقال أب آخر: لكن السهر يذيب الجسد أكثر.\",\"g\":[\"السهر\",\"الصوم\",\"الجهاد\"],\"k\":\"127.1b\"},{\"i\":144,\"f\":\"الأب ثيوناس\",\"p\":127,\"n\":1,\"t\":\"بسبب انشغال العقل الأعلى في غير رؤية الله، نسقط أسرى الأهواء الجسدية.\",\"g\":[\"الأفكار\",\"الشهوة\",\"السهر\"],\"k\":\"127.1c\"},{\"i\":145,\"f\":\"شيخ من جبل النطرون\",\"p\":128,\"n\":1,\"c\":\"جوابًا لرئيس الأساقفة ثيوفيلوس لما سأله: ماذا وجدت في درب هذه الحياة يا أبت؟ فقال له الأسقف: ليس ثمة طريق آخر يا أبت\",\"t\":\"أن ألوم نفسي وأن أنتقدها دائماً.\",\"g\":[\"الاتضاع\",\"التوبة\",\"الإدانة\"],\"k\":\"128.1\"},{\"i\":146,\"f\":\"البابا ثيوفيلوس\",\"p\":129,\"n\":5,\"c\":\"قاله عندما أوشك أن يغادر هذا العالم\",\"t\":\"هنيئاً لك يا أرسانيوس لأنك كنت تتذكر هذه الساعة دائماً.\",\"g\":[\"ذكر الموت\",\"السهر\",\"خوف الله\"],\"k\":\"129.5\"},{\"i\":147,\"f\":\"البابا ثيوفيلوس\",\"p\":130,\"n\":1,\"c\":\"جوابًا للأم ثيوذورا لما سألته عن معنى قول الرسول «مفتدين الوقت» (أف 5: 16)\",\"t\":\"افتدي وقت الإهانة بالتواضع وطول الأناة واكسبي لنفسك ربحاً. وفي وقت الهوان، افتدي الوقت بالصبر، فتربحي. وكل الأمور المضادة يمكن أن تصير لنا ربحاً، شرط إرادتنا.\",\"g\":[\"الصبر\",\"الاتضاع\",\"الضيقات\"],\"k\":\"130.1\"},{\"i\":148,\"f\":\"الأم ثيوذورا\",\"p\":130,\"n\":2,\"t\":\"جاهدوا لكي تدخلوا من الباب الضيق. لأنه كما أن الشجرة، إذا لم تتعرض للرياح والعواصف والأمطار، لا يمكنها أن تأتي بثمر، هكذا الحال بالنسبة إلينا أيضاً. هذا الدهر شتاء قاس. وبدون ضيقات وتجارب متنوعة يمكننا أن نرث ملكوت الله.\",\"g\":[\"الضيقات\",\"الجهاد\",\"الصبر\"],\"k\":\"130.2\"},{\"i\":149,\"f\":\"الأم ثيوذورا\",\"p\":131,\"n\":6,\"t\":\"لا النسك ولا السهر ولا أي وجع يخلّص الإنسان، سوى التواضع الأصيل.\",\"g\":[\"الاتضاع\",\"الجهاد\",\"الكبرياء\"],\"k\":\"131.6\"},{\"i\":150,\"f\":\"الأب يوحنا الكولوفي\",\"p\":132,\"n\":1,\"c\":\"قاله لما أتى بثمر العصا اليابسة التي غرسها له أبوه الروحي وأمره أن يسقيها، بعد ثلاث سنين\",\"t\":\"خذوا كلوا من ثمار الطاعة.\",\"g\":[\"الطاعة\",\"الصبر\"],\"k\":\"132.1\"},{\"i\":151,\"f\":\"الأب يوحنا الكولوفي\",\"p\":132,\"n\":3,\"t\":\"إذا أراد ملك الاستيلاء على مدينة، فإنه يمنع عنها الطعام والماء أولاً، فيستسلم له سكانها بسبب الجوع. هكذا هو حال أهواء الجسد. إذا عاش الإنسان بالصوم والجوع، فإن أعداء النفس تمرض.\",\"g\":[\"الصوم\",\"الجهاد\",\"الشهوة\"],\"k\":\"132.3\"},{\"i\":152,\"f\":\"الأب يوحنا الكولوفي\",\"p\":133,\"n\":8,\"c\":\"جوابًا لشيخ قال له: إبريقك يا يوحنا مملوء سمّاً\",\"t\":\"لقد قلت هذا لأنك رأيت ما في الخارج فقط. ماذا كنت ستقول لو رأيت ما في الداخل أيضاً؟\",\"g\":[\"الاتضاع\",\"الإدانة\",\"التوبة\"],\"k\":\"133.8\"},{\"i\":153,\"f\":\"الأب يوحنا الكولوفي\",\"p\":133,\"n\":10,\"c\":\"قاله لإخوة قالوا: نشكر الله الذي جعل السماء تمطر حتى ترتوي أشجار النخيل وتخرج براعم\",\"t\":\"هكذا هو الروح القدس. عندما ينزل في قلوب الناس، تتجدد وتخرج براعم بمخافة الله.\",\"g\":[\"خوف الله\",\"الشكر\",\"الفرح\"],\"k\":\"133.10\"},{\"i\":154,\"f\":\"الأب يوحنا الكولوفي\",\"p\":134,\"n\":12,\"t\":\"إنني أشبه إنساناً يجلس تحت شجرة كبيرة يراقب وحوشاً كثيرة وزحافات تقترب منه. فعندما لا يحتمل أن يثبت أمامها، يهرع إلى الشجرة فينجو، هذه هي حالتي: أقيم في قلايتي وأبصر فوقي الأفكار الشريرة. وعندما لا أستطيع أن أسيطر عليها، ألتجىء إلى الله بالصلاة، فأنجو من العدو.\",\"g\":[\"الأفكار\",\"الصلاة\",\"الخلوة\",\"الجهاد\"],\"k\":\"134.12\"},{\"i\":155,\"f\":\"الأب يوحنا الكولوفي\",\"p\":134,\"n\":13,\"c\":\"كان يصليها حين جاءته الحرب ولم يصل لكي تفارقه\",\"t\":\"يا رب أعطني الصبر في الحروب.\",\"g\":[\"الصبر\",\"الصلاة\",\"الجهاد\"],\"k\":\"134.13\"},{\"i\":156,\"f\":\"الأب يوحنا الكولوفي\",\"p\":136,\"n\":18,\"c\":\"قاله لأخ نسي كلامه وكان يخشى أن يزعجه، وقد أشعل مصابيح كثيرة من مصباح واحد دون أن يتضرر\",\"t\":\"هكذا هي الحال مع يوحنا أيضاً. فلو جاءني كل سكان الاسقيط، لا يمكنهم أن يعيقوني عن نعمة المسيح. إذن يمكنك أن تأتي إليّ متى تشاء دون أن تتردد البتة.\",\"g\":[\"الخلوة\",\"الخدمة\",\"المحبة\"],\"k\":\"136.18\"},{\"i\":157,\"f\":\"الأب يوحنا الكولوفي\",\"p\":137,\"n\":20,\"c\":\"جوابًا لمن قال إن إخوة يوسف هم الذين باعوه\",\"t\":\"لقد باعه تواضعه. لأنه كان يقدر أن يقول «إني أخوهم» وإن يعترض. إنما صمت، فباع نفسه بالتواضع، فجعله تواضعه قائداً في مصر.\",\"g\":[\"الاتضاع\",\"الصمت\",\"الصبر\"],\"k\":\"137.20\"},{\"i\":158,\"f\":\"الأب يوحنا الكولوفي\",\"p\":137,\"n\":21,\"t\":\"لقد تركنا النير الخفيف وأعني لوم النفس، وحملنا الثقيل الذي هو تبرير الذات.\",\"g\":[\"الاتضاع\",\"التوبة\",\"الكبرياء\"],\"k\":\"137.21\"},{\"i\":159,\"f\":\"الأب يوحنا الكولوفي\",\"p\":137,\"n\":22,\"t\":\"التواضع ومخافة الله أسمى من كل الفضائل.\",\"g\":[\"الاتضاع\",\"خوف الله\"],\"k\":\"137.22\"},{\"i\":160,\"f\":\"الأب يوحنا الكولوفي\",\"p\":137,\"n\":24,\"c\":\"كان يقوله لتلميذه\",\"t\":\"لنحترم الواحد فيحترمنا الجميع، لأننا إذا احتقرنا الواحد، وأعني الله، فإن الجميع يحتقروننا، فنذهب إلى الهلاك.\",\"g\":[\"خوف الله\",\"الحكمة\",\"الاتضاع\"],\"k\":\"137.24\"},{\"i\":161,\"f\":\"الأب يوحنا الكولوفي\",\"p\":138,\"n\":27,\"t\":\"السجن هو أن تقيم في قلايتك وتذكر الله على الدوام. وهذا هو معنى الآية «كنت محبوساً فأتيتم إليّ» (متى 25: 36).\",\"g\":[\"الخلوة\",\"الصلاة\",\"السهر\"],\"k\":\"138.27\"},{\"i\":162,\"f\":\"الأب يوحنا الكولوفي\",\"p\":138,\"n\":28,\"t\":\"من كان قوياً كالأسد، هل يُعقل أن يقع في الشرك وتضعف قوته، من أجل بطنه؟\",\"g\":[\"الصوم\",\"الجهاد\",\"الحكمة\"],\"k\":\"138.28\"},{\"i\":163,\"f\":\"الأب يوحنا الكولوفي\",\"p\":139,\"n\":34,\"t\":\"أريد الإنسان أن يأخذ قليلاً من جميع الفضائل. وبالتالي، فإنك عندما تستيقظ كل صباح، ابدأ من جديد في كل فضيلة ووصية وذلك بصبر عظيم وخوف وطول أناة ومحبة لله من كل الجسد والنفس.\",\"g\":[\"الجهاد\",\"الصبر\",\"الحكمة\",\"السهر\"],\"k\":\"139.34\"},{\"i\":164,\"f\":\"الأب يوحنا الكولوفي\",\"p\":140,\"n\":37,\"c\":\"جوابًا لمن سأله: من هو الراهب؟\",\"t\":\"الكادح، لأن الراهب يتعب في كل أمر. هكذا يكون الراهب.\",\"g\":[\"الجهاد\",\"الصبر\",\"العمل\"],\"k\":\"140.37\"},{\"i\":165,\"f\":\"الأب يوحنا الكولوفي\",\"p\":140,\"n\":39,\"t\":\"لا يمكنك أن تبني بيتك من أعلى إلى أسفل، إنما من الأساس إلى فوق. الأساس هو القريب الذي ينبغي أن تربح، وينبغي أن يكون اهتمامك الأول، لأن به تتعلق كل وصايا المسيح.\",\"g\":[\"المحبة\",\"الخدمة\",\"الحكمة\"],\"k\":\"140.39\"},{\"i\":166,\"f\":\"الأب يوحنا الذي يعيش في دير ذي شركة\",\"p\":142,\"n\":1,\"c\":\"جواب أخ في دير ذي شركة لإخوة الاسقيط لما سألوه: من جعلك راهباً ولم يعلمك أن تأخذ من الإخوة وتقول لهم: باركوا أو استريحوا؟\",\"t\":\"إن يوحنا الخاطىء لا ينشغل بمثل هذه الأمور.\",\"g\":[\"الاتضاع\",\"الصمت\",\"المجد الباطل\"],\"k\":\"142.1a\"},{\"i\":167,\"f\":\"الأب إيسيذورس كاهن الاسقيط\",\"p\":142,\"n\":1,\"c\":\"كان يقولها حين يريد الإخوة طرد أخ مريض أو لا مبال أو شتّام، فكان يأخذه وبطول أناة يخلّصه\",\"t\":\"أحضره إليّ إلى ههنا.\",\"g\":[\"الصبر\",\"الرحمة\",\"المحبة\"],\"k\":\"142.1b\"},{\"i\":168,\"f\":\"الأب إيسيذورس كاهن الاسقيط\",\"p\":142,\"n\":2,\"c\":\"جوابًا لأخ سأله: لماذا تخشاك الشياطين جداً؟\",\"t\":\"لأنني منذ أصبحت راهباً، وأنا أحاول إلاّ أسمح للغضب أن يرتفع إلى حلقي.\",\"g\":[\"الغضب\",\"الوداعة\",\"الجهاد\"],\"k\":\"142.2\"},{\"i\":169,\"f\":\"الأب إيسيذورس كاهن الاسقيط\",\"p\":142,\"n\":4,\"t\":\"لما كنت أصغر سناً وأكثر حداثة، وكنت أقيم في قلايتي، لم يكن عندي مقياس للصلاة، لأن الصلاة كانت بالنسبة إليّ في الليل والنهار.\",\"g\":[\"الصلاة\",\"الخلوة\",\"السهر\"],\"k\":\"142.4\"},{\"i\":170,\"f\":\"الأب إيسيذورس كاهن الاسقيط\",\"p\":143,\"n\":5,\"c\":\"جواب للإخوة الذين رجوه أن يستريح قليلاً لأنه شاخ، وكان يمضي ليله وهو يحيك الخوص\",\"t\":\"إذا أحرقوا إيسيذورس ونثروا رماده في الهواء، فليس له أية نعمة أكبر، لأن ابن الله قد جاء إلى هنا من أجلنا.\",\"g\":[\"الجهاد\",\"المحبة\",\"الشكر\"],\"k\":\"143.5\"},{\"i\":171,\"f\":\"الأب إيسيذورس كاهن الاسقيط\",\"p\":143,\"n\":9,\"t\":\"الأردأ بين كل الأرواح أن يتبع الإنسان قلبه (أي أفكاره)، لا شريعة الله. والآن وقت العمل للرب، لأن الخلاص يُقتنى في وقت الضيقات، وقد كتب «بصبركم تقتنون نفوسكم» (لوقا 21: 19).\",\"g\":[\"الأفكار\",\"الصبر\",\"الضيقات\",\"الكتاب المقدس\"],\"k\":\"143.9\"},{\"i\":172,\"f\":\"الأب إيسيذورس البيلوسيوتي\",\"p\":144,\"n\":1,\"t\":\"حياة بدون كلام خير من كلام بدون حياة. فالأولى بالصمت تنفع، أما الثانية فبالصياح تزعج. لكن، إذا اقترنت الحياة بالكلمة، يولد مثال كل الفلسفة.\",\"g\":[\"الصمت\",\"اللسان\",\"الحكمة\"],\"k\":\"144.1\"},{\"i\":173,\"f\":\"الأب إيسيذورس البيلوسيوتي\",\"p\":144,\"n\":2,\"t\":\"أكرم الفضائل ولا تهتم باللذات، لأن الفضائل خالدة، أما الملذات فتزول بسهولة.\",\"g\":[\"الزهد\",\"الحكمة\",\"الجهاد\"],\"k\":\"144.2\"},{\"i\":174,\"f\":\"الأب إيسيذورس البيلوسيوتي\",\"p\":144,\"n\":5,\"t\":\"بما أن علو التواضع عظيم، كذلك هو السقوط في الكبرياء.\",\"g\":[\"الاتضاع\",\"الكبرياء\"],\"k\":\"144.5\"},{\"i\":175,\"f\":\"الأب إيسيذورس البيلوسيوتي\",\"p\":144,\"n\":6,\"t\":\"إن حب المال المخيف، الذي لا يعرف الشبع، يقود النفس المستعبدة له إلى أسوأ الشرور. لذلك فلنبتعد عنه من البدء لأنه، إذا ساد، يصبح سيداً لا يقهر.\",\"g\":[\"الطمع\",\"الزهد\",\"الحكمة\"],\"k\":\"144.6\"},{\"i\":176,\"f\":\"الأب إسحق كاهن القلالي\",\"p\":145,\"n\":1,\"c\":\"قاله لما جاءوا ليشرطنوه كاهناً فهرب ثم وجدوه\",\"t\":\"لن أهرب بعد الآن، لأن هذه هي إرادة الله. إذ حيثما ذهبت، أصل إلى ذلك بعينه.\",\"g\":[\"الطاعة\",\"الاتضاع\",\"الإيمان\"],\"k\":\"145.1\"},{\"i\":177,\"f\":\"الأب إسحق كاهن القلالي\",\"p\":145,\"n\":2,\"c\":\"عن الأب كرونيو الذي كان يلازم الصمت ولا يطلب منه خدمة\",\"t\":\"ومنذ ذلك الحين بدأت أسرع في القيام بالأعمال التي هو ينوي القيام بها. وهذا علمني أن أقوم بعملي صامتاً.\",\"g\":[\"الصمت\",\"الطاعة\",\"الخدمة\"],\"k\":\"145.2\"},{\"i\":178,\"f\":\"الأب إسحق كاهن القلالي\",\"p\":146,\"n\":3,\"c\":\"جوابًا للأب إبراهيم لما وجده يبكي وسأله: لماذا تبكي يا أبت؟\",\"t\":\"آباؤنا ماتوا وعمل أيدينا لم يكن يكفي لأجرة المراكب عندما كنا نذهب لزيارتهم. أما الآن فنحن يتامى، من أجل هذا أبكي يا ولدي.\",\"g\":[\"الدموع\",\"الشركة\",\"الرجاء\"],\"k\":\"146.3\"},{\"i\":179,\"f\":\"الأب إسحق كاهن القلالي\",\"p\":146,\"n\":9,\"t\":\"لم أدخل إلى قلايتي فكراً ضد أخ أزعجني. وكان همي إلا أترك أحداً وفي قلبه عليّ شيء.\",\"g\":[\"الغفران\",\"السلام\",\"الأفكار\"],\"k\":\"146.9\"},{\"i\":180,\"f\":\"الأب إسحق كاهن القلالي\",\"p\":147,\"n\":10,\"c\":\"جوابًا لأخ رجاه أن يأكل قليلاً من الخبز اليابس لأجل مرضه\",\"t\":\"في الحقيقة يا ولدي، كنت أريد لو أبقى في مرضي ثلاثين سنة.\",\"g\":[\"الصبر\",\"الزهد\",\"الضيقات\"],\"k\":\"147.10\"},{\"i\":181,\"f\":\"الأب إسحق كاهن القلالي\",\"p\":147,\"n\":11,\"c\":\"قاله لآبائه عند رحيله لما سألوه: ماذا نعمل بعدك يا أبانا؟\",\"t\":\"أنظروا كيف كان سلوكي بينكم. فإذا أردتم أن تتبعوني، احفظوا وصايا الله، وهو يرسل نعمته ويحفظ هذا المكان. ولكن إذا لم تحفظوها، لن تقيموا ههنا.\",\"g\":[\"الطاعة\",\"الكتاب المقدس\",\"الجهاد\"],\"k\":\"147.11\"},{\"i\":182,\"f\":\"الأب يوسف الذي في بنفو\",\"p\":148,\"n\":2,\"c\":\"جوابًا للأب بيمن لما سأله: كيف يمكنني أن أصير راهباً؟\",\"t\":\"إذا أردت أن تجد راحة هنا وهناك، قل في كل شيء: «من أنا؟»، ولا تدنْ أحداً.\",\"g\":[\"الاتضاع\",\"الإدانة\",\"السلام\"],\"k\":\"148.2\"},{\"i\":183,\"f\":\"الأب يوسف الذي في بنفو\",\"p\":149,\"n\":4,\"c\":\"جوابًا لأخ قال: لا أقدر أن أحتمل المشقات أو أن أعمل وأن أمارس الإحسان\",\"t\":\"إذا كنت لا تقدر أن تعمل واحدة من هذه، يكفيك أن تحفظ ضميرك تجاه القريب نقياً، فتخلص.\",\"g\":[\"المحبة\",\"الإدانة\",\"الحكمة\"],\"k\":\"149.4\"},{\"i\":184,\"f\":\"الأب يوسف الذي في بنفو\",\"p\":150,\"n\":6,\"c\":\"قاله للأب لوط\",\"t\":\"لا تستطيع أن تصير راهباً، إذا لم تصبح ناراً ملتهبة بالكلية.\",\"g\":[\"الجهاد\",\"الصلاة\",\"المحبة\"],\"k\":\"150.6\"},{\"i\":185,\"f\":\"الأب يوسف الذي في بنفو\",\"p\":150,\"n\":7,\"c\":\"جواب الأب يوسف للأب لوط حين قال: على قدر طاقتي أقوم بصلاتي وصومي ودرسي وتأملي، فماذا بقي عليّ أن أعمل؟ وقد بسط يديه نحو السماء فصارت أصابعه كعشر شموع من نار\",\"t\":\"إذا كنت تريد، فما عليك إلا أن تكون ناراً بالكلية.\",\"g\":[\"الجهاد\",\"الصلاة\",\"المحبة\"],\"k\":\"150.7\"},{\"i\":186,\"f\":\"الأب يوسف الذي في بنفو\",\"p\":150,\"n\":10,\"c\":\"قاله وهو يطير من الفرح لما سأله الإخوة\",\"t\":\"اليوم أنا ملك، لأنني ملكت على أهوائي.\",\"g\":[\"الفرح\",\"الجهاد\",\"الشهوة\"],\"k\":\"150.10\"},{\"i\":187,\"f\":\"الأب يعقوب\",\"p\":151,\"n\":1,\"t\":\"خير للإنسان أن يتغرب من أن يستضيف.\",\"g\":[\"الزهد\",\"الاتضاع\"],\"k\":\"151.1a\"},{\"i\":188,\"f\":\"الأب يعقوب\",\"p\":151,\"n\":2,\"t\":\"عندما يُمتدح إنسان، ينبغي أن يتأمل في خطاياه ويفكر في أنه لا يستحق ما يُقال فيه.\",\"g\":[\"الاتضاع\",\"المجد الباطل\",\"التوبة\"],\"k\":\"151.2\"},{\"i\":189,\"f\":\"الأب يعقوب\",\"p\":151,\"n\":3,\"t\":\"كما أن المصباح يضيء غرفة النوم المظلمة، هكذا خوف الله عندما يدخل القلب، ينيره ويعلّمه كل الفضائل ووصايا الله.\",\"g\":[\"خوف الله\",\"الحكمة\"],\"k\":\"151.3\"},{\"i\":190,\"f\":\"الأب يعقوب\",\"p\":151,\"n\":4,\"t\":\"ليست حاجتنا إلى الكلام فقط، لأن الكلام في هذا الزمان كثير، إنما حاجتنا إلى العمل. فهذا هو المطلوب، لا الكلام الذي لا يأتي بثمر.\",\"g\":[\"الجهاد\",\"اللسان\",\"الحكمة\"],\"k\":\"151.4\"},{\"i\":191,\"f\":\"الأب إيراكا\",\"p\":151,\"n\":1,\"c\":\"جوابًا لأخ سأله: قل لي كلمة، كيف أخلص؟\",\"t\":\"اجلس في قلايتك. وإذا عطشت اشرب. وإذا جعت كل. لا تتكلم على أحد بسوء. هكذا تخلص.\",\"g\":[\"الخلوة\",\"اللسان\",\"الإدانة\"],\"k\":\"151.1b\"},{\"i\":192,\"f\":\"الأب يوحنا الخصي\",\"p\":152,\"n\":1,\"c\":\"جوابًا لمن سأله: كيف استطعتم أن تعملوا إرادة الله براحة، بينما نحن بالجهد نفعل ذلك؟\",\"t\":\"لقد تمكنا من ذلك، إذ أن اهتمامنا الأساسي هو عمل الله. أما للحاجة الجسدية فنعير انتباهاً قليلاً. بينما أنتم تعطون الحاجة الجسدية الاهتمام الأول، وعمل الله ليس الأهم عندكم. لأجل هذا تتعبون.\",\"g\":[\"الجهاد\",\"الحكمة\",\"الكتاب المقدس\"],\"k\":\"152.1a\"},{\"i\":193,\"f\":\"الأب يوحنا الخصي\",\"p\":152,\"n\":2,\"c\":\"ينقله عن القديس أنطونيوس\",\"t\":\"لم أؤثر مرة مصلحتي على مصلحة أخي.\",\"g\":[\"المحبة\",\"الخدمة\",\"الاتضاع\"],\"k\":\"152.2a\"},{\"i\":194,\"f\":\"الأب يوحنا الكيليكس\",\"p\":152,\"n\":1,\"c\":\"قاله لإخوة دير رايثو\",\"t\":\"يا أولادي، كما أننا هجرنا العالم فلنهجر رغبات الجسد أيضاً.\",\"g\":[\"الزهد\",\"الجهاد\",\"الشهوة\"],\"k\":\"152.1b\"},{\"i\":195,\"f\":\"الأب يوحنا الكيليكس\",\"p\":152,\"n\":2,\"t\":\"لنتشبه بآبائنا. كم من الشدة والسكينة أقاموا هنا.\",\"g\":[\"الخلوة\",\"الجهاد\",\"الشركة\"],\"k\":\"152.2b\"},{\"i\":196,\"f\":\"الأب يوحنا رجل القلالي\",\"p\":153,\"n\":2,\"c\":\"قاله الأب يوحنا الطيبي\",\"t\":\"يجب على الراهب، قبل كل شيء، أن يكون متواضعاً، لأن هذه هي وصية السيد الأولى: «هنيئاً للمساكين بالروح، لأن لهم ملكوت السموات» (متى 5: 3).\",\"g\":[\"الاتضاع\",\"الكتاب المقدس\"],\"k\":\"153.2\"},{\"i\":197,\"f\":\"الأب إيسيذورس الكاهن\",\"p\":154,\"n\":1,\"c\":\"جوابًا لأخ جاءه يدعوه إلى الطعام فأبى، ولما قال له: وأنت أيضاً تخاف الخروج من قلايتك يا أبت؟\",\"t\":\"آدم خُدع بالأكلة. أخاف لأن «الشيطان يزأر كالأسد طالباً من يبتلعه» (1 بطرس 5: 8).\",\"g\":[\"السهر\",\"خوف الله\",\"الصوم\"],\"k\":\"154.1\"},{\"i\":198,\"f\":\"الأب إيسيذورس الكاهن\",\"p\":154,\"n\":2,\"t\":\"إذا اشتهيت أن تنال ملكوت السموات، فاحتقر الأموال واسع نحو المكافأة الإلهية.\",\"g\":[\"الزهد\",\"الرجاء\",\"الطمع\"],\"k\":\"154.2\"},{\"i\":199,\"f\":\"الأب إيسيذورس الكاهن\",\"p\":154,\"n\":3,\"t\":\"يستحيل عليك أن تعيش وفقاً لإرادة الله إذا كنت محباً للمال واللذة.\",\"g\":[\"الطمع\",\"الزهد\",\"الشهوة\"],\"k\":\"154.3\"},{\"i\":200,\"f\":\"الأب إيسيذورس الكاهن\",\"p\":154,\"n\":4,\"t\":\"إذا حفظتم الصوم وفق الأصول لا تتكبروا، لأنه خير لكم أن تأكلوا لحماً من أن تقعوا في الكبرياء. فخير للإنسان أن يأكل لحماً من أن يتباهى ويفتخر.\",\"g\":[\"الصوم\",\"الكبرياء\",\"الاتضاع\"],\"k\":\"154.4\"},{\"i\":201,\"f\":\"الأب إيسيذورس الكاهن\",\"p\":154,\"n\":5,\"t\":\"يجب على التلاميذ أن يحبوا المعلمين الحقيقيين كآباء، وأن يخافوهم كرؤساء. فلا يسقطون الخوف بداعي المحبة، ولا يزيلون المحبة بداعي الخوف.\",\"g\":[\"الطاعة\",\"المحبة\",\"خوف الله\"],\"k\":\"154.5\"},{\"i\":202,\"f\":\"الأب إيسيذورس الكاهن\",\"p\":155,\"n\":6,\"t\":\"إذا كنت تشتاق إلى الخلاص، اعمل كل ما من شأنه أن يقودك إليه.\",\"g\":[\"الجهاد\",\"الرجاء\",\"الحكمة\"],\"k\":\"155.6\"},{\"i\":203,\"f\":\"الأب يوحنا الفارسي\",\"p\":156,\"n\":1,\"c\":\"لما رأى أحد الإخوة يقترف الخطيئة مع الصبي ولم يوبخه\",\"t\":\"إذا كان الله الذي أبدعهما يراهما، فمن أنا حتى أوبِّخهما؟\",\"g\":[\"الإدانة\",\"الرحمة\",\"الاتضاع\"],\"k\":\"156.1\"},{\"i\":204,\"f\":\"الأب يوحنا الفارسي\",\"p\":157,\"n\":4,\"c\":\"جوابًا لأخ قال له: لقد تعبنا تعباً هذا مقداره من أجل ملكوت السموات، ترى هل نرثه؟\",\"t\":\"أنا أؤمن أنني سأرث أورشليم العلوية التي في السموات، لأن من وعدنا به أمين، فلماذا الشك إذن؟\",\"g\":[\"الإيمان\",\"الرجاء\",\"الصبر\"],\"k\":\"157.4\"},{\"i\":205,\"f\":\"الأب يوسف الطيبي\",\"p\":159,\"n\":1,\"t\":\"ثلاثة أمور مكرمة في عيني الرب: الأول عندما يمرض الإنسان فتأتيه التجارب ويقبلها بشكر. والثاني، عندما يتمّ الإنسان أعماله كلها أمام الرب بدون أي أمر بشريّ. والثالث عندما يعيش المرء في طاعة أبيه الروحي، ويرفض كل مشيئة ذاتية. هذا له إكليل خاص ينتظره. أمّا أنا، فقد اخترت المرض.\",\"g\":[\"الصبر\",\"الشكر\",\"الطاعة\",\"الضيقات\"],\"k\":\"159.1\"},{\"i\":206,\"f\":\"الأب إسحق الطيبي\",\"p\":160,\"n\":1,\"c\":\"قاله ملاك الرب للأب اسحق بعد أن وبّخ أخاً أخطأ\",\"t\":\"انتبه لنفسك ألاّ تدين أحداً قبل أن يدينه الله.\",\"g\":[\"الإدانة\",\"التوبة\",\"الاتضاع\"],\"k\":\"160.1\"},{\"i\":207,\"f\":\"الأب إسحق الطيبي\",\"p\":160,\"n\":2,\"c\":\"جوابًا لإخوة سألوه: لماذا تهرب من الإخوة بعد الصلاة؟\",\"t\":\"أنا لا أهرب من الإخوة بل من حنكة الشياطين وحيلهم وحبائلهم، لأنه لو أمسك أحد شمعة مضاءة وأطال وقوفه في الريح، تنطفئ. هكذا هي حالنا تماماً عندما نستنير من التقدمة المقدسة (الجسد والدم الطاهرين)، فإن عقلنا يظلم إذا مشينا خارج قلالينا.\",\"g\":[\"الخلوة\",\"الأفكار\",\"الكنيسة\",\"السهر\"],\"k\":\"160.2\"},{\"i\":208,\"f\":\"الأب كسيانوس\",\"p\":162,\"n\":1,\"c\":\"ينقله عن أحد آباء مصر، جوابًا عن سؤال: لأي سبب لا تحفظون قانون صومكم عندما تستقبلون إخوة غرباء؟\",\"t\":\"الصوم معي دائماً. أمّا أنتم فلستم معي على الدوام. لا شك أن الصوم أمر نافع جداً وضروري، إلاّ أنه اختياري. أمّا إتمام المحبة، فتطلبه منّا شريعة الله بالضرورة. وإذا قبلت المسيح فيكم، يجب عليّ أن أخدمكم بكل غيرة وحماس.\",\"g\":[\"المحبة\",\"الضيافة\",\"الصوم\",\"الخدمة\"],\"k\":\"162.1\"},{\"i\":209,\"f\":\"الأب كسيانوس\",\"p\":162,\"n\":2,\"c\":\"ينقله عن شيخ اتُّهم ظلمًا، قاله للآباء قبل رحيله\",\"t\":\"عندما أنتقل اغرسوا عصاي في القبر، فإذا أينعت وأثمرت تفهمون أني كنت بريئاً من تهمة الناس، وإذا لم تثمر تفهمون أني قد خطئت معها.\",\"g\":[\"الصبر\",\"الإدانة\",\"الرجاء\"],\"k\":\"162.2\"},{\"i\":210,\"f\":\"الأب كسيانوس\",\"p\":162,\"n\":3,\"c\":\"ينقله عن شيخ زاره، جوابًا لمن قال له: لم نعد قادرين على الأكل\",\"t\":\"أنا بسبب الإخوة الزوار مددت المائدة ست مرات متوسلاً إلى كل واحد أن يأكل، وكنت بنفسي آكل معه، ولا أزال إلى الآن جائعاً. أمّا أنتم فقد شبعتم من أكلة واحدة ولم تعودوا قادرين أن تأكلوا.\",\"g\":[\"الضيافة\",\"المحبة\",\"الصوم\"],\"k\":\"162.3\"},{\"i\":211,\"f\":\"الأب بيسيوس\",\"p\":163,\"n\":4,\"c\":\"ينقله كسيانوس، جوابًا للأب يوحنا الذي سأله: ماذا جنيت من أربعين سنة في صحراء بعيدة؟\",\"t\":\"منذ أن أصبحت راهباً، لم ترني الشمس آكل.\",\"g\":[\"الصوم\",\"الجهاد\",\"الخلوة\"],\"k\":\"163.4a\"},{\"i\":212,\"f\":\"الأب يوحنا رئيس الدير\",\"p\":163,\"n\":4,\"c\":\"ينقله كسيانوس، ردًّا على قول الأب بيسيوس: لم ترني الشمس آكل\",\"t\":\"وأنا لم ترني أغضب.\",\"g\":[\"الغضب\",\"الوداعة\"],\"k\":\"163.4b\"},{\"i\":213,\"f\":\"الأب يوحنا رئيس الدير\",\"p\":163,\"n\":5,\"c\":\"كلمة وداع لإخوته لما أوشك أن يغادر العالم\",\"t\":\"لم أفعل، مرة، مشيئتي. كما أنني لم أعلّم أحداً ما لم أفعله أنا أولاً.\",\"g\":[\"الطاعة\",\"الخدمة\",\"الحكمة\"],\"k\":\"163.5\"},{\"i\":214,\"f\":\"الأب كسيانوس\",\"p\":163,\"n\":6,\"c\":\"ينقله عن شيخ كان يقيم في البرية\",\"t\":\"الشيطان غيور على الكلام الباطل، وعدو لكل تعليم روحي.\",\"g\":[\"اللسان\",\"السهر\",\"الأفكار\"],\"k\":\"163.6\"},{\"i\":215,\"f\":\"القديس باسيليوس\",\"p\":164,\"n\":7,\"c\":\"ينقله كسيانوس، قاله لإنسان رفيع الشأن وزّع أمواله واحتفظ لنفسه بالقليل غير مريد الخضوع لحياة الشركة\",\"t\":\"لقد فقدت الغنى، لكنك لم تصبح راهباً.\",\"g\":[\"الزهد\",\"الطاعة\",\"الشركة\"],\"k\":\"164.7\"},{\"i\":216,\"f\":\"الأب كسيانوس\",\"p\":164,\"n\":8,\"c\":\"ينقله عن راهب في كهف، جوابًا لأنسبائه الذين دعوه ليرث أباه المشرف على الموت\",\"t\":\"لقد مت عن العالم قبله فالميت لا يرث الحي.\",\"g\":[\"الزهد\",\"ذكر الموت\"],\"k\":\"164.8\"},{\"i\":217,\"f\":\"الأب كرونيوس\",\"p\":165,\"n\":1,\"c\":\"جوابًا لأخ قال له: قل لي كلمة\",\"t\":\"النفس إذا سهرت وجمعت ذاتها من التشتت وهجرت إرادتها، يستقر عليها روح الله، فتلد، ولو كانت عاقراً.\",\"g\":[\"السهر\",\"الصلاة\",\"الخلوة\"],\"k\":\"165.1\"},{\"i\":218,\"f\":\"الأب كرونيوس\",\"p\":165,\"n\":2,\"c\":\"جوابًا لأخ سأله عن النسيان الذي يأسر عقله\",\"t\":\"إذا التفت الذهن وطلب الله ذاكراً الدينونة الأخيرة، للحال يسقط الهوى ويتلاشى، لأنه كتب: «إذا استدرت وتنهدت، تخلص، وتعلم أين كنت» (أشعيا ٣٠: ١٥).\",\"g\":[\"الأفكار\",\"التوبة\",\"ذكر الموت\",\"الكتاب المقدس\"],\"k\":\"165.2\"},{\"i\":219,\"f\":\"الأب كرونيوس\",\"p\":165,\"n\":3,\"c\":\"جوابًا لأخ سأله: كيف يبلغ الإنسان إلى التواضع؟ فقال: بمخافة الله. وكيف يصل إلى مخافة الله؟\",\"t\":\"أظن أنه يتم له ذلك عندما يجمع ذاته ويسلم نفسه للتعب الجسدي متذكراً، من كل قلبه، ساعة خروجه من هذا العالم، ودينونة الله.\",\"g\":[\"الاتضاع\",\"خوف الله\",\"ذكر الموت\",\"الجهاد\"],\"k\":\"165.3\"},{\"i\":220,\"f\":\"الأب كاريون\",\"p\":167,\"n\":1,\"t\":\"لقد بذلت جهوداً كثيرة تفوق ما بذله ابني زخريا، ولم أبلغ بعد إلى قامته في التواضع والصمت.\",\"g\":[\"الاتضاع\",\"الصمت\",\"الجهاد\"],\"k\":\"167.1\"},{\"i\":221,\"f\":\"الأب إيسيذورس الكاهن\",\"p\":168,\"n\":2,\"c\":\"عن زخريا ابن الأب كاريون بعد أن جاهد في التواضع\",\"t\":\"زخريا الصبي، لما تقدم في الأحد الماضي لتناول الجسد والدم الطاهرين، كان إنساناً، أما الآن فقد أضحى ملاكاً.\",\"g\":[\"الاتضاع\",\"الجهاد\",\"الكنيسة\"],\"k\":\"168.2a\"},{\"i\":222,\"f\":\"الأب كوبريس\",\"p\":168,\"n\":2,\"t\":\"هنيئاً لمن يحتمل التعب بشكر.\",\"g\":[\"الشكر\",\"الصبر\"],\"k\":\"168.2b\"},{\"i\":223,\"f\":\"الأب كوبريس\",\"p\":168,\"n\":3,\"c\":\"قاله لنفسه ضاربًا على فمه ثلاث مرات، لما اجتمع سكان الأسقيط في مسألة جدلية ونسوا أن يدعوه\",\"t\":\"الويل لك يا كوبريس لأنك قد أهملت كل ما طلبه الله منك وشرعت تفتش عمّا لم يطلبه.\",\"g\":[\"الصمت\",\"اللسان\",\"الاتضاع\"],\"k\":\"168.3\"},{\"i\":224,\"f\":\"الأب كيرس\",\"p\":169,\"n\":1,\"c\":\"عندما سُئل عن فكر الزنى\",\"t\":\"إن لم يكن عندك فكر، لا يكُنْ عندك رجاء. وإن لم يكن عندك أفكار، فعندك عمل.\",\"g\":[\"الأفكار\",\"الجهاد\",\"الرجاء\"],\"k\":\"169.1a\"},{\"i\":225,\"f\":\"الأب كيرس\",\"p\":169,\"n\":1,\"c\":\"جوابًا لأخ تزعجه ذكريات الأفكار القديمة\",\"t\":\"لا تكن من الأموات خائفاً، إنما تحاشَ الأحياء، وأطِل صلاتك.\",\"g\":[\"الأفكار\",\"الصلاة\",\"الشهوة\"],\"k\":\"169.1b\"},{\"i\":226,\"f\":\"الأب لوكيوس\",\"p\":169,\"n\":1,\"c\":\"جوابًا لرهبان «المصلّين» الذين يهملون العمل بحجة الصلاة بلا انقطاع\",\"t\":\"أمّا أنا فأثبت لكم أني بعملي أصلّي بدون انقطاع. اجلس للعمل بمعونة الله وأحوك الخوص وأنا أردد: «ارحمني يا الله كعظيم رحمتك وكمثل كثرة رأفتك امح مآثمي».\",\"g\":[\"الصلاة\",\"العمل\",\"التوبة\"],\"k\":\"169.1c\"},{\"i\":227,\"f\":\"الأب لوكيوس\",\"p\":169,\"n\":1,\"c\":\"تتمة جوابه للرهبان «المصلّين»\",\"t\":\"إذن عندما أعمل وأصلّي أربح فوق عملي وصلاتي ست عشرة قطعة نقدية، أتصدّق بإثنتين منها وأعيش بالباقي. والذي أتصدق عليه يصلّي من أجلي. وعندما آكل وأنام تتم صلاتي بنعمة الله بدون انقطاع.\",\"g\":[\"الصلاة\",\"العمل\",\"الرحمة\",\"الشكر\"],\"k\":\"169.1d\"},{\"i\":228,\"f\":\"الأب أرسانيوس\",\"p\":170,\"n\":1,\"c\":\"قاله للأب لوط حين شكا من ضيف مريض يُقلق الإخوة بأقواله\",\"t\":\"لا تطرده، لكن قل له: خذ من خيرات الله ما طاب لك، كل واشرب، لكن لا تتكلم. فإذا أراد أن يصطلح، قبل كلامك، وإذا أبى، فإنه سرعان ما يطلب الرحيل فلا تكون أنت السبب.\",\"g\":[\"الضيافة\",\"الحكمة\",\"التمييز\"],\"k\":\"170.1\"},{\"i\":229,\"f\":\"الأب لوط\",\"p\":170,\"n\":2,\"c\":\"قاله لأخ سقط في زلة عظيمة\",\"t\":\"تشجع يا أخي، فالتوبة أمامك. اذهب واجلس في الكهف عاكفاً على الصيام يومين يومين، وأنا أحتمل معك نصف الخطية.\",\"g\":[\"التوبة\",\"الرحمة\",\"المحبة\",\"الصوم\"],\"k\":\"170.2\"},{\"i\":230,\"f\":\"الأب لوكيوس\",\"p\":171,\"n\":1,\"c\":\"جوابًا للأب لونجينس الذي قال له: أريد أن أعيش في غربة\",\"t\":\"إذا لم تحفظ لسانك، لن تكون غريباً أينما حللت. احفظ لسانك هنا، فتصير غريباً.\",\"g\":[\"اللسان\",\"الصمت\",\"الخلوة\"],\"k\":\"171.1a\"},{\"i\":231,\"f\":\"الأب لوكيوس\",\"p\":171,\"n\":1,\"c\":\"جوابًا للأب لونجينس الذي قال له: أريد أن أصوم\",\"t\":\"قال النبي أشعياء: «إذا أحنيت عنقك كلها إلى طوق حديدي، لن يسمّى هذا صوماً مقبولاً» (أشعياء ٥٨: ٥)، لكن بالحري أضبط الأفكار الشريرة.\",\"g\":[\"الصوم\",\"الأفكار\",\"الكتاب المقدس\"],\"k\":\"171.1b\"},{\"i\":232,\"f\":\"الأب لوكيوس\",\"p\":171,\"n\":1,\"c\":\"جوابًا للأب لونجينس الذي قال له: أريد أن أهرب من الناس\",\"t\":\"إذا لم تحقق الفضيلة مع الناس أولاً، لا تستطيع بمفردك، وأنت في البرية، أن تحققها.\",\"g\":[\"الخلوة\",\"الشركة\",\"الجهاد\"],\"k\":\"171.1c\"},{\"i\":233,\"f\":\"الأب لونجينس\",\"p\":172,\"n\":5,\"c\":\"قاله للأب اكاكيوس\",\"t\":\"المرأة تعرف أنها قد حبلت، عندما يتوقف دمها. هكذا النفس، فإنها تحبل بالروح القدس عندما تتوقف الأهواء التي تجري من تحتها. فإذا كانت تساكن الأهواء، كيف تقدر أن تتظاهر بعدم الهوى؟ أعط دماً وخذ روحاً.\",\"g\":[\"الجهاد\",\"الشهوة\",\"الأفكار\"],\"k\":\"172.5\"},{\"i\":234,\"f\":\"الأب مكاريوس المصري\",\"p\":176,\"n\":3,\"c\":\"نصيحته لأخ جاءه وهو تحاربه الأفكار\",\"t\":\"ليكن صومك حتى المساء. وروّض نفسك على الجهادات الروحية، واحفظ الإنجيل والأسفار المقدسة عن ظهر قلب. وإذا ما أتاك فكر شرير، لا تنتظر إلى أسفل، إنما وجّه أبصارك إلى العلاء والرب يعينك ويقويك.\",\"g\":[\"الصوم\",\"الأفكار\",\"الكتاب المقدس\",\"الجهاد\"],\"k\":\"176.3\"},{\"i\":235,\"f\":\"الأب أنطونيوس\",\"p\":176,\"n\":4,\"c\":\"قاله للأب مكاريوس لما رأى ما أنتجه من الخوص في ليلة واحدة\",\"t\":\"إن قوة عظيمة تخرج من هاتين اليدين.\",\"g\":[\"العمل\",\"الحكمة\"],\"k\":\"176.4\"},{\"i\":236,\"f\":\"الأب مكاريوس المصري\",\"p\":178,\"n\":9,\"c\":\"جوابًا لمن لأمه على تصرفه ببراءة مع الإخوة، يرويه الأب بطرس\",\"t\":\"لقد أمضيت اثنتي عشرة سنة في خدمة ربي كي يمنحني هذه الموهبة. وها أنتم الآن تنصحونني بالتخلي عنها.\",\"g\":[\"الوداعة\",\"الجهاد\"],\"k\":\"178.9\"},{\"i\":237,\"f\":\"الأب مكاريوس المصري\",\"p\":178,\"n\":12,\"c\":\"جوابًا لمن سأله: كيف أنك إذا أكلت ولم تأكل، يظل جسمك قوياً؟\",\"t\":\"إن الخشب الذي يتوسط المواد المشتعلة، تلتهمه النار بسرعة. هكذا هو الحال مع الإنسان، فإنه إذا نقّى ذهنه بمخافة الله، فإن المخافة هذه، تلتهم جسده.\",\"g\":[\"خوف الله\",\"الصوم\",\"الأفكار\"],\"k\":\"178.12\"},{\"i\":238,\"f\":\"الأب مكاريوس المصري\",\"p\":180,\"n\":17,\"t\":\"إذا عاقبت إنساناً وأنت تغضب، فأنت تُرضي هواك. ولكي تخلّص الآخرين ينبغي ألاّ تُرضي نفسك.\",\"g\":[\"الغضب\",\"الحكمة\",\"الخدمة\"],\"k\":\"180.17\"},{\"i\":239,\"f\":\"الأب مكاريوس المصري\",\"p\":180,\"n\":19,\"c\":\"جوابًا لمن سأله: كيف ينبغي أن نصلّي؟\",\"t\":\"لا حاجة لنا إلى كثرة الكلام، بل إلى أن نمد أيدينا إلى العلاء ونقول: يا رب ارحمنا كما تريد وكما تعلم. وإذا حلّت بنا حرب، نقول: اعنّا. فهو يعرف ما نحتاج إليه ويعاملنا برحمة.\",\"g\":[\"الصلاة\",\"الرحمة\",\"الإيمان\"],\"k\":\"180.19\"},{\"i\":240,\"f\":\"الأب مكاريوس المصري\",\"p\":180,\"n\":20,\"t\":\"لن تموت إذا صار عندك الهزء كالمديح والفقر كالغنى والحرمان كالقنية، لأنه يستحيل على من يؤمن جيداً ويسلك بتقوى أن يسقط في نتانة الأهواء وخديعة الشياطين.\",\"g\":[\"الزهد\",\"الإيمان\",\"المجد الباطل\"],\"k\":\"180.20\"},{\"i\":241,\"f\":\"الأب مكاريوس المصري\",\"p\":181,\"n\":22,\"c\":\"جوابًا للأب موسى الذي قال له: أريد أن أعيش بهدوء لكن الإخوة لا يتركونني\",\"t\":\"أرى أن طبيعتك ناعمة ولا تستطيع أن تبعد أخاً عنك. ولكن إذا أردت أن تعيش في الهدوء، اذهب إلى البرية الداخلية، إلى البتراء، وهناك تجد هدوءك المطلوب.\",\"g\":[\"الخلوة\",\"التمييز\"],\"k\":\"181.22\"},{\"i\":242,\"f\":\"الأب مكاريوس المصري\",\"p\":181,\"n\":23,\"c\":\"بعد أن أرسل أخًا ليشتم الموتى في القبور ثم يمتدحهم، جوابًا لمن قال له: قل لي كلمة، كيف أخلص؟\",\"t\":\"إذا أردت أن تخلص، عليك أن تكون كالأموات فلا تكترث لمديح الناس أو ذمهم، تماماً كما فعل الأموات. وأنت، إن فعلت هذا، تخلص.\",\"g\":[\"الاتضاع\",\"المجد الباطل\",\"الكبرياء\"],\"k\":\"181.23\"},{\"i\":243,\"f\":\"الأب مكاريوس المصري\",\"p\":181,\"n\":24,\"c\":\"تعليقًا على صبي سمعه يقول لأمه: ثمة غني يحبني لكني أمقته، وفقير يمقتني إلا أني أحبه\",\"t\":\"في الحقيقة يا إخوتي، ربنا هو الغني ويحبنا ولكننا لا نريد أن نسمع له. أمّا عدوّنا فهو فقير ويكرهنا، إلاّ أننا نحبه ونحب نتانته.\",\"g\":[\"التوبة\",\"المحبة\",\"الطاعة\"],\"k\":\"181.24\"},{\"i\":244,\"f\":\"الأب مكاريوس المصري\",\"p\":182,\"n\":27,\"c\":\"جوابًا للأب أشعيا الذي سأله: ما معنى «اهرب من الناس»؟\",\"t\":\"معناه أن تجلس في قلايتك وتبكي خطاياك.\",\"g\":[\"الخلوة\",\"الدموع\",\"التوبة\"],\"k\":\"182.27\"},{\"i\":245,\"f\":\"الأب مكاريوس المصري\",\"p\":182,\"n\":28,\"c\":\"كلمته لتلميذه بفنوتيوس لما طلب منه كلمة\",\"t\":\"لا تَدِنْ أحداً ولا تُسِئْ إلى أحد. احفظ هذه، تخلص.\",\"g\":[\"الإدانة\",\"المحبة\",\"الرحمة\"],\"k\":\"182.28\"},{\"i\":246,\"f\":\"الأب مكاريوس المصري\",\"p\":182,\"n\":29,\"t\":\"لا تنم في قلاية راهب له سمعة سيئة.\",\"g\":[\"التمييز\",\"السهر\"],\"k\":\"182.29\"},{\"i\":247,\"f\":\"الأب مكاريوس المصري\",\"p\":185,\"n\":34,\"c\":\"كلمته لجماهير الرهبان الذين التفّوا حوله في الجبل\",\"t\":\"لنبك يا إخوتي، ولتنهمر الدموع من مآقينا قبل أن نذهب إلى هناك حيث ستلهب الدموع أجسادنا.\",\"g\":[\"الدموع\",\"التوبة\",\"ذكر الموت\"],\"k\":\"185.34\"},{\"i\":248,\"f\":\"الأب مكاريوس المصري\",\"p\":185,\"n\":36,\"t\":\"إذا تذكرنا الشرور الآتية علينا من الناس، فإننا نقطع بذلك قوة ذكر الله. ولكن، إذا تذكرنا شرور الشياطين، نصير بلا جراح.\",\"g\":[\"الغفران\",\"الأفكار\",\"الصلاة\"],\"k\":\"185.36\"},{\"i\":249,\"f\":\"الأب مكاريوس المصري\",\"p\":185,\"n\":37,\"c\":\"يرويه تلميذه الأب بفنوتيوس عن شيخه\",\"t\":\"لما كنت طفلاً كنت أرعى القطيع مع سائر الأولاد الصغار. فذهبوا ليسرقوا تيناً. ولما كانوا يركضون، سقطت واحدة، فأخذتها وأكلتها. وعندما أتذكر ما فعلت، أجلس وأبكي.\",\"g\":[\"الدموع\",\"التوبة\",\"الاتضاع\"],\"k\":\"185.37\"},{\"i\":250,\"f\":\"الأب مكاريوس المصري\",\"p\":187,\"n\":39,\"t\":\"الكلمة الشريرة تجعل الصالحين أشراراً. أمّا الكلمة الطيبة فمن شأنها أن تجعل الأشرار صالحين.\",\"g\":[\"اللسان\",\"الحكمة\",\"المحبة\"],\"k\":\"187.39\"},{\"i\":251,\"f\":\"الأب مكاريوس المصري\",\"p\":187,\"n\":41,\"c\":\"جوابًا لأخ سأله: قلْ لي كلمة\",\"t\":\"أهرب من الناس. اجلس في قلايتك وابك خطاياك. لا تحب ثرثرة الناس تخلص.\",\"g\":[\"الخلوة\",\"الدموع\",\"الصمت\"],\"k\":\"187.41\"},{\"i\":252,\"f\":\"الأب إيسيذورس الكاهن\",\"p\":188,\"n\":1,\"c\":\"قاله للأب موسى وقد أراه جموع الشياطين في المغارب وجموع الملائكة في المشارق\",\"t\":\"أنظر، هؤلاء هم الذين يرسلهم الله لمساعدة القديسين. أمّا الذين في الغرب فهم الذين يحاربونهم. فالذين معنا هم أكثر عدداً.\",\"g\":[\"الجهاد\",\"الرجاء\",\"الإيمان\"],\"k\":\"188.1\"},{\"i\":253,\"f\":\"الأب موسى\",\"p\":188,\"n\":2,\"c\":\"جوابًا للإخوة الذين خرجوا للقائه، وهو يحمل كيساً مثقوباً فيه رمل، لما دُعي إلى مجمع لمحاكمة أخ سقط\",\"t\":\"إنها خطاياي التي تتساقط وراءي ولا أراها. وها قد أتيت الآن لأنظر في خطايا الآخرين.\",\"g\":[\"الإدانة\",\"الاتضاع\",\"الغفران\"],\"k\":\"188.2\"},{\"i\":254,\"f\":\"الأب موسى\",\"p\":188,\"n\":3,\"c\":\"جوابًا لمن سأله: ألم تضطرب لما ازدروا بك في المجمع؟\",\"t\":\"لقد اضطربت لكني لم أتكلم.\",\"g\":[\"الصمت\",\"الصبر\",\"الاتضاع\"],\"k\":\"188.3\"},{\"i\":255,\"f\":\"الأب موسى\",\"p\":189,\"n\":6,\"c\":\"جوابًا لأخ زاره في الأسقيط وطلب منه كلمة\",\"t\":\"إذهب واجلس في قلايتك وهي تعلّمك كل شيء.\",\"g\":[\"الخلوة\",\"الصمت\",\"الحكمة\"],\"k\":\"189.6\"},{\"i\":256,\"f\":\"الأب موسى\",\"p\":189,\"n\":7,\"t\":\"إن من يهرب من الناس يشبه كرمة حان قطافها. أمّا الذي يقيم بين الناس فيشبه الحصرم.\",\"g\":[\"الخلوة\",\"الشركة\"],\"k\":\"189.7\"},{\"i\":257,\"f\":\"الأب موسى\",\"p\":190,\"n\":9,\"c\":\"قاله في الأسقيط\",\"t\":\"إذا حفظنا وصايا آبائنا فإني أضمن لكم أن البرابرة لا يأتون إلى هنا. ولكن إذا لم نحفظها، فإن المنطقة هذه ستقفر.\",\"g\":[\"الطاعة\",\"الجهاد\"],\"k\":\"190.9\"},{\"i\":258,\"f\":\"الأب موسى\",\"p\":190,\"n\":10,\"c\":\"قاله للإخوة لما أنذرهم بقدوم البربر وهم يحثونه على الهرب\",\"t\":\"إن لي سنين طوالاً وأنا أنتظر هذا اليوم، لكي يتم قول المسيح: «من أخذ بالسيف بالسيف يؤخذ» (متى ٢٦: ٥٢).\",\"g\":[\"ذكر الموت\",\"الإيمان\",\"الرجاء\"],\"k\":\"190.10\"},{\"i\":259,\"f\":\"الأب موسى\",\"p\":190,\"n\":12,\"c\":\"جوابًا لأخ سأله: بأية طريقة يميت الإنسان نفسه عن قريبه؟\",\"t\":\"إذا لم يضع الإنسان نفسه عقلياً في القبر ثلاثة أيام، لا يمكنه أن يبلغ إلى قامة هذا الكلام.\",\"g\":[\"ذكر الموت\",\"الاتضاع\",\"الإدانة\"],\"k\":\"190.12\"},{\"i\":260,\"f\":\"الأب موسى الحبشي\",\"p\":191,\"n\":14,\"t\":\"ينبغي للمرء أن يموت عن قريبه حتى لا يدينه في شيء.\",\"g\":[\"الإدانة\",\"الاتضاع\"],\"k\":\"191.14\"},{\"i\":261,\"f\":\"الأب موسى الحبشي\",\"p\":191,\"n\":15,\"t\":\"ينبغي للإنسان أن يميت نفسه عن كل أمر شرير قبل خروجه من الجسد لكي لا يسيء إلى أحد.\",\"g\":[\"ذكر الموت\",\"الرحمة\",\"الجهاد\"],\"k\":\"191.15\"},{\"i\":262,\"f\":\"الأب موسى الحبشي\",\"p\":191,\"n\":16,\"t\":\"إذا لم يشعر الإنسان في أعماقه أنه خاطىء، لا يصغي إليه الله.\",\"g\":[\"التوبة\",\"الاتضاع\",\"الصلاة\"],\"k\":\"191.16a\"},{\"i\":263,\"f\":\"الأب موسى الحبشي\",\"p\":191,\"n\":16,\"c\":\"جوابًا لأخ سأله: ما معنى أن يشعر الإنسان في أعماقه أنه خاطىء؟\",\"t\":\"إن من يحمل خطاياه لن يرى خطايا قريبه.\",\"g\":[\"الإدانة\",\"الاتضاع\",\"التوبة\"],\"k\":\"191.16b\"},{\"i\":264,\"f\":\"الأب موسى الحبشي\",\"p\":191,\"n\":17,\"t\":\"إذا لم تتفق الصلاة مع السيرة، عبثاً يكون التعب. أقصد أن لا نعمل ما نصلّي من أجله، إذ أن الإنسان عندما يتخلى عن مشيئته، يتصالح مع الله، والله يقبل صلاته.\",\"g\":[\"الصلاة\",\"الجهاد\",\"الطاعة\"],\"k\":\"191.17\"},{\"i\":265,\"f\":\"الأب موسى الحبشي\",\"p\":192,\"n\":18,\"c\":\"جوابًا لأخ سأله: ما نفع الأصوام والأسهار؟\",\"t\":\"هذه من شأنها أن تجعل النفس وديعة متواضعة، لأنه مكتوب: «أنظر إلى تعبي وتواضعي وأمح كل سيئاتي» (مزمور ٢٤: ١٨). فإذا ما جنت النفس كل هذا النهار، فإن الله لأجل هذه يتحنن عليها.\",\"g\":[\"الصوم\",\"السهر\",\"الاتضاع\",\"الكتاب المقدس\"],\"k\":\"192.18a\"},{\"i\":266,\"f\":\"الأب موسى الحبشي\",\"p\":192,\"n\":18,\"t\":\"أن تموت عن قريبك يعني أن تحمل خطاياك وأن لا تكترث لأي إنسان، صالحاً كان أم شريراً. وأن لا تسيء إلى أحد، وأن لا تفكر بإساءة أحد في قلبك، وأن لا تحتقر من خطىء، وأن لا تطيع من يسيء إلى قريبه ولا تفرح له.\",\"g\":[\"الإدانة\",\"المحبة\",\"الغفران\"],\"k\":\"192.18b\"},{\"i\":267,\"f\":\"الأب موسى الحبشي\",\"p\":192,\"n\":18,\"t\":\"لا تثلب أحداً، إنما قل إن الله يعرف كل واحد. لا توافق المتكلم بالسوء على قريبه. هذا هو معنى الدينونة. لا يكن لك عداوة مع أحد. لا تحقد في قلبك على أحد. لا تمقت من يعادي قريبه. هذا هو السلام. بهذه عزّ نفسك. ولمدة قصيرة يدوم الضيق، ولكن إلى الأبد تبقى الراحة بنعمة الله، آمين.\",\"g\":[\"السلام\",\"الغفران\",\"الإدانة\",\"اللسان\"],\"k\":\"192.18c\"},{\"i\":268,\"f\":\"الأب ماتوى\",\"p\":193,\"n\":1,\"t\":\"أريد عملاً خفيفاً ودائماً لا عملاً متعباً في البدء ولكن لا يدوم.\",\"g\":[\"العمل\",\"الصبر\",\"الحكمة\"],\"k\":\"193.1\"},{\"i\":269,\"f\":\"الأب ماتوى\",\"p\":193,\"n\":2,\"t\":\"كلما دنا الإنسان من الله يرى كم هو خاطىء. وأشعيا النبي، عندما رأى الله، قال عن نفسه إنه بائس ودنس (٦: ٥).\",\"g\":[\"الاتضاع\",\"التوبة\",\"الكتاب المقدس\"],\"k\":\"193.2\"},{\"i\":270,\"f\":\"الأب ماتوى\",\"p\":193,\"n\":4,\"t\":\"الشيطان لا يعرف بأي هوى تستسلم النفس. لكنه يبذر دون أن يعرف إن كان سيجني أفكار الزنى، الثلب، وسائر الأهواء الأخرى. وحيثما يَرَ ميل النفس يقدم لها بذار الشر.\",\"g\":[\"الأفكار\",\"السهر\",\"التمييز\"],\"k\":\"193.4\"},{\"i\":271,\"f\":\"الأب ماتوى\",\"p\":193,\"n\":5,\"c\":\"جوابًا لأخ سأله: كيف يكون الاسقيطيون قد حققوا أكثر مما يذكره الكتاب إذ أحبوا أعداءهم أكثر من أنفسهم؟\",\"t\":\"حتى الآن أنا أحب من يحبني، كنفسي.\",\"g\":[\"المحبة\",\"الاتضاع\"],\"k\":\"193.5\"},{\"i\":272,\"f\":\"الأب ماتوى\",\"p\":193,\"n\":6,\"c\":\"جوابًا لأخ سأله: ماذا أعمل إذا جاءني أخ في صوم أو عند الصباح لأنني أتضايق؟\",\"t\":\"إذا كنت لا تتضايق وتأكل مع الأخ، حسناً تفعل. وإذا كنت ترجو أن تأكل دون أن تنتظر أحداً، فهذا مرهون بإرادتك.\",\"g\":[\"الضيافة\",\"المحبة\",\"الصوم\"],\"k\":\"193.6\"},{\"i\":273,\"f\":\"الأب يوحنا رجل القلالي\",\"p\":194,\"n\":7,\"c\":\"جوابًا ليعقوب الذي نقل إليه تحية الأب ماتوى\",\"t\":\"في جميع الأحوال، عندما تسمع شيخاً يمتدح قريبه أكثر من نفسه، اعلم أنه قد بلغ درجة من الكمال رفيعة، لأن هذا هو الكمال، أن تمجد قريبك أكثر من نفسك.\",\"g\":[\"الاتضاع\",\"المحبة\"],\"k\":\"194.7\"},{\"i\":274,\"f\":\"الأب ماتوى\",\"p\":194,\"n\":8,\"c\":\"جوابًا لأخ قال له: إن الثلب أسوأ من الزنى\",\"t\":\"الثلب شرّ، لكنّ شفاءه سريع، لأن من يثلب يندم مرات عديدة قائلاً: لقد نطقت شراً. أمّا الزنى، فهو موت طبيعي.\",\"g\":[\"اللسان\",\"الإدانة\",\"التوبة\"],\"k\":\"194.8\"},{\"i\":275,\"f\":\"الأب بفنوتيوس كفالاس\",\"p\":195,\"n\":10,\"c\":\"جوابًا لثلاثة آباء جاؤوا يسألونه كلمة روحية\",\"t\":\"إذهبوا وأحبوا الضيق أكثر من الراحة، والاحتقار أكثر من المجد، والعطاء أكثر من الأخذ.\",\"g\":[\"الضيقات\",\"الاتضاع\",\"الرحمة\",\"المجد الباطل\"],\"k\":\"195.10\"},{\"i\":276,\"f\":\"الأب ماتوى\",\"p\":195,\"n\":11,\"c\":\"جوابًا لأخ سأله: قل لي كلمة\",\"t\":\"إذهب وتضرع إلى الرب أن يجعل في قلبك الحزن والتواضع، وانتبه لخطاياك دائماً، ولا تدن أحداً. كن دون الجميع.\",\"g\":[\"الاتضاع\",\"الإدانة\",\"التوبة\",\"الدموع\"],\"k\":\"195.11a\"},{\"i\":277,\"f\":\"الأب ماتوى\",\"p\":195,\"n\":11,\"c\":\"تتمة جوابه للأخ الذي سأله كلمة\",\"t\":\"اقطع التكلم علانية وأمسك لسانك وبطنك. تجنب الخمرة. وإذا تحدث أحد في أمر ما، لا تجادله. فإذا قال ما هو حسن، فقل: نعم. وإذا نطق بالسوء، قل له: أنت تعرف ما تقول. لا تحاججه في ما يقوله. هذا هو التواضع.\",\"g\":[\"اللسان\",\"الاتضاع\",\"الصمت\"],\"k\":\"195.11b\"},{\"i\":278,\"f\":\"الأب ماتوى\",\"p\":195,\"n\":12,\"c\":\"جوابًا لأخ سأله: قل لي كلمة\",\"t\":\"اقطع من نفسك كل جدل. أبك ونح، لأن الوقت قد اقترب.\",\"g\":[\"الدموع\",\"ذكر الموت\",\"التوبة\"],\"k\":\"195.12\"},{\"i\":279,\"f\":\"الأب ماتوى\",\"p\":195,\"n\":13,\"c\":\"جوابًا لأخ سأله: ماذا أعمل ولساني يزعجني؟\",\"t\":\"إذا كنت لا تقدر أن تمسك نفسك، إذهب واعتزل، لأن في ذلك ضعفاً. فإن من يقيم بين الإخوة لا يجوز أن يكون رباعياً بل دائرياً، كما يدور باتجاه الجميع. وقال الشيخ: وأنا لست لوحدي بسبب الفضيلة، إنما بداعي الضعف، لأن الذين يأتون إلى وسط الناس هم أقوياء.\",\"g\":[\"اللسان\",\"الخلوة\",\"الشركة\",\"الاتضاع\"],\"k\":\"195.13\"},{\"i\":280,\"f\":\"الأب موتيوس\",\"p\":200,\"n\":1,\"c\":\"جوابًا لأخ سأله: إذا تركت العالم لأسكن في مكان، كيف تريدني أن أعيش هناك؟\",\"t\":\"إذا سكنت في مكان، لا تفكر أن يكون لك فيه اسم في أي شيء. أي «لا أخرج إلى الاجتماع»، أو «ولا آكل في وليمة المحبة»، لأن هذه تولد اسماً كاذباً ومن ثم ينوبك الغم والإنزعاج. فالناس يتهافتون حيث يجدون مثل هذا.\",\"g\":[\"المجد الباطل\",\"الاتضاع\",\"الشركة\"],\"k\":\"200.1a\"},{\"i\":281,\"f\":\"الأب موتيوس\",\"p\":200,\"n\":1,\"c\":\"تتمة جوابه للأخ نفسه\",\"t\":\"حيث تقيم، ليكن سلوكك كسلوك الجميع. ومهما يفعل الأتقياء الذين تثق بهم، افعله أنت أيضاً، فترتاح، لأن التواضع هو أن تكون مساوياً لهم. فالناس إذ يرونك تعمل بالقانون ولا تحيد عنه، سيجعلونك في رتبة الجميع، وهكذا لا يزعجونك.\",\"g\":[\"الاتضاع\",\"الشركة\",\"الحكمة\"],\"k\":\"200.1b\"},{\"i\":282,\"f\":\"الأب مياثيوس\",\"p\":201,\"n\":3,\"c\":\"جوابًا لسؤال: إذا فضل طعام لليوم التالي، هل تريد أن يأكله الإخوة؟\",\"t\":\"إذا فسد، لا يحسن أن نلزم الإخوة به، لئلا يمرضوا، لذا نرميه. ولكن إذا كان شهياً صالحاً للأكل ورمي بسبب الترف، وطبخ سواه، فهذا أمر ردىء.\",\"g\":[\"الزهد\",\"الحكمة\",\"التمييز\"],\"k\":\"201.3\"},{\"i\":283,\"f\":\"الأب مياثيوس\",\"p\":201,\"n\":4,\"t\":\"في البدء، لما كنا نجتمع معاً ونتباحث في أمور نافعة، بانين بعضنا بعضاً، كنا نصير أجواقاً أجواقاً ونرتفع إلى السموات. ولكن الآن عندما نجتمع ليدين أحدنا أخاه، فإننا نهبط إلى أسفل.\",\"g\":[\"الإدانة\",\"الشركة\"],\"k\":\"201.4\"},{\"i\":284,\"f\":\"الأب ميّوس\",\"p\":202,\"n\":1,\"c\":\"الأب ميّوس الذي من فيليوس\",\"t\":\"الطاعة تكون من أجل الطاعة. فالإنسان إذا أطاع الله فإن الله يطيعه.\",\"g\":[\"الطاعة\",\"الإيمان\"],\"k\":\"202.1\"},{\"i\":285,\"f\":\"الأب ميّوس\",\"p\":202,\"n\":3,\"c\":\"جوابًا لجندي سأله: هل يقبل الله التوبة؟ فسأله: إذا تمزق ثوبك هل ترميه خارجاً أم ترتقه؟ فقال: بل أرتقه\",\"t\":\"إذاً، إذا كنت أنت تبقى على ثوبك، ألا يبقى الله على خليقته؟\",\"g\":[\"التوبة\",\"الرحمة\",\"الرجاء\"],\"k\":\"202.3\"},{\"i\":286,\"f\":\"الأب مرقس المصري\",\"p\":203,\"n\":1,\"c\":\"قاله لأخ جاءه يشكو كاهنًا تفوح منه رائحة الخطية\",\"t\":\"يا ولدي، الكل يطرحون الفساد خارجاً، أمّا أنت فقد أحضرته إليّ. ولكنه مكتوب: «لا تدينوا لئلا تدانوا» (متى ٧: ١). فالكاهن وإن كان خاطئاً إلاّ أنّ الرب يخلصه. لأنه قد كتب أيضاً: «صلّوا من أجل بعضكم لتشفوا» (يعقوب ٥: ١٦).\",\"g\":[\"الإدانة\",\"الكنيسة\",\"الصلاة\",\"الكتاب المقدس\"],\"k\":\"203.1\"},{\"i\":287,\"f\":\"الأب مكاريوس السكندري\",\"p\":204,\"n\":2,\"c\":\"جوابًا للأب باخوميوس: عندما يكون عندنا إخوة بطّالون، هل يحسن أن نعاقبهم؟\",\"t\":\"عاقب واحكم بعدل من هم تحت امرتك، لكن لا تدن أحداً من خارج، لأنه قد كتب «أنتم ألا تدينون الذين هم من داخل، أمّا الذين من خارج، فالرب يدينهم؟» (١ كورنثوس ٥: ١٢).\",\"g\":[\"الإدانة\",\"الحكمة\",\"الكتاب المقدس\"],\"k\":\"204.2\"},{\"i\":288,\"f\":\"الأب نيلوس\",\"p\":205,\"n\":1,\"t\":\"مهما فعلت وأنت تقاوم أخاً قد ظلمك، سيدخل إلى قلبك ساعة الصلاة.\",\"g\":[\"الغفران\",\"الصلاة\"],\"k\":\"205.1\"},{\"i\":289,\"f\":\"الأب نيلوس\",\"p\":205,\"n\":2,\"t\":\"الصلاة برعم الوداعة وعدم الغضب.\",\"g\":[\"الصلاة\",\"الوداعة\",\"الغضب\"],\"k\":\"205.2\"},{\"i\":290,\"f\":\"الأب نيلوس\",\"p\":205,\"n\":3,\"t\":\"الصلاة دواء للفتور والأحزان.\",\"g\":[\"الصلاة\",\"الضيقات\",\"الفرح\"],\"k\":\"205.3\"},{\"i\":291,\"f\":\"الأب نيلوس\",\"p\":205,\"n\":4,\"t\":\"لكي تتمكن من الصلاة دون ارتباك، إذهب وبع كل ما لك وأعطه للمساكين ثم احمل صليبك وأنكرْ نفسك.\",\"g\":[\"الصلاة\",\"الزهد\",\"الرحمة\"],\"k\":\"205.4\"},{\"i\":292,\"f\":\"الأب نيلوس\",\"p\":205,\"n\":5,\"t\":\"إن كل ما تتأمل فيه وأنت صابر، ستجني ثمرَه ساعة الصلاة.\",\"g\":[\"الصلاة\",\"الصبر\",\"الأفكار\"],\"k\":\"205.5\"},{\"i\":293,\"f\":\"الأب نيلوس\",\"p\":205,\"n\":6,\"t\":\"إذا أردت أن تصلّي كما يجب، لا تُحزن أحداً، وإلاّ فأنت تسعى عبثاً.\",\"g\":[\"الصلاة\",\"المحبة\",\"السلام\"],\"k\":\"205.6\"},{\"i\":294,\"f\":\"الأب نيلوس\",\"p\":205,\"n\":7,\"t\":\"لا ترغب في أن تأتي الأمور وفقاً لما تتمنى، إنما وفقاً لمشيئة الله، وهكذا تكون بدون اضطراب ولاهمّ ومسروراً في صلاتك.\",\"g\":[\"الصلاة\",\"الطاعة\",\"السلام\",\"الفرح\"],\"k\":\"205.7\"},{\"i\":295,\"f\":\"الأب نيلوس\",\"p\":205,\"n\":8,\"t\":\"هنيئاً للراهب الذي يعتبر نفسه نفاية الكل.\",\"g\":[\"الاتضاع\"],\"k\":\"205.8\"},{\"i\":296,\"f\":\"الأب نيلوس\",\"p\":205,\"n\":9,\"t\":\"إن الراهب الذي يحب السكينة، لا يمكن لسهام العدو أن تجرحه. أمّا من يتدخل في كل شيء، فإنه سيحتمل جراحات مستمرة.\",\"g\":[\"الخلوة\",\"الصمت\",\"السهر\"],\"k\":\"205.9\"},{\"i\":297,\"f\":\"الأب نيسثروس\",\"p\":206,\"n\":1,\"c\":\"لما هرب من تنين رآه في البرية فقال له أخ: وأنت أيضاً تخاف يا أبت؟\",\"t\":\"أنا لا أخاف يا ولدي، لكن خير لي أن أهرب، وإلاّ فلن يمكنني أن أهرب من روح المجد الفارغ.\",\"g\":[\"المجد الباطل\",\"الاتضاع\"],\"k\":\"206.1\"},{\"i\":298,\"f\":\"الأب أنطونيوس\",\"p\":206,\"n\":2,\"c\":\"جوابًا للأب نيسثروس الذي سأله: ما هو العمل الصالح حتى أعمله؟\",\"t\":\"أليست كل الأعمال متساوية؟ يقول الكتاب إن إبراهيم كان مضيفاً وكان الرب معه. وإيليا أحب السكينة، وكان الرب معه. وداود كان متواضعاً، وكان الرب معه. إذاً، ما تظن أن نفسك تريده، وفقاً لمشيئة الله، هذا اعمله واحفظه في قلبك.\",\"g\":[\"الحكمة\",\"التمييز\",\"الضيافة\",\"الاتضاع\"],\"k\":\"206.2\"},{\"i\":299,\"f\":\"الأب نيسثروس\",\"p\":206,\"n\":3,\"c\":\"جوابًا للأب يوسف الذي سأله: ماذا أعمل بلساني الذي لا أقدر أن ألجمه؟\",\"t\":\"إذا لم تشعر بالراحة، لماذا تتكلم؟ أليس الأفضل أن تصمت؟ وإذا كنت في مناقشة، فليكن إصغاؤك أكثر من كلامك.\",\"g\":[\"اللسان\",\"الصمت\",\"الحكمة\"],\"k\":\"206.3\"},{\"i\":300,\"f\":\"الأب نيسثروس\",\"p\":207,\"n\":5,\"t\":\"على الراهب أن يحاسب نفسه كل مساء وكل صباح: ماذا فعلت مما يريده الله؟ وماذا فعلت مما لا يريده؟ وهذا نحققه طوال حياتنا.\",\"g\":[\"التوبة\",\"السهر\",\"الجهاد\"],\"k\":\"207.5a\"},{\"i\":301,\"f\":\"الأب نيسثروس\",\"p\":207,\"n\":5,\"t\":\"لا تجعل نفسك مشرِّعاً ولا تدن أحداً. فمن الغريب بالنسبة للراهب أن يقسم أو أن يحنث، أو أن يكذب، أو أن يلعن، أو أن يشتم، أو أن يضحك، لأن من يكرّم نفسه ويرفعها فوق استحقاقها يهلك.\",\"g\":[\"الإدانة\",\"اللسان\",\"الكبرياء\"],\"k\":\"207.5b\"},{\"i\":302,\"f\":\"الأب نيسثروس الذي في شركة\",\"p\":207,\"n\":2,\"c\":\"جوابًا للأب بيمن إذ سأله: من أين اقتنيت هذه الفضيلة؟\",\"t\":\"منذ دخلت الدير وأنا أقول لنفسي: «أنت والحمار واحد». فكما أن الحمار يُربط فلا يتكلم، يُشتم فلا يجيب، هكذا أنت كما يقول المرنم: «صرت كالبهيمة لديك، ومع هذا فأنا معك في كل حين» (مزمور ٧٢: ٢٢).\",\"g\":[\"الاتضاع\",\"الصبر\",\"الكتاب المقدس\"],\"k\":\"207.2\"},{\"i\":303,\"f\":\"الأب نيكون\",\"p\":208,\"n\":1,\"c\":\"قاله للشعب الذين جاؤوا يعتذرون إليه بعد أن ظهرت براءته\",\"t\":\"أمّا من جهة المسامحة، فها قد سامحتكم، أمّا من جهة بقائي، فلن أبقى معكم لأنه لم يوجد واحد منكم يتمتع بالتمييز لكي يتعاطف معي.\",\"g\":[\"التمييز\",\"الغفران\"],\"k\":\"208.1\"},{\"i\":304,\"f\":\"الأب نترا\",\"p\":209,\"n\":1,\"c\":\"جوابًا لتلميذه لما سأله لماذا يروّض نفسه بنسك قاسٍ بعد أن صار أسقفاً\",\"t\":\"هنا كانت البرية والسكينة والفقر، فأردت أن أسود على الجسد لئلا أمرض فأطلب ما لم يكن عندي. ولكن هنا عندنا العالم وكل الفرص. وإذا أصابني المرض هنا، سأجد من يساعدني لئلا أفقد صفتي الرهبانية.\",\"g\":[\"الزهد\",\"الجهاد\",\"الحكمة\"],\"k\":\"209.1\"},{\"i\":305,\"f\":\"الأب كسويس\",\"p\":210,\"n\":1,\"c\":\"جوابًا لأخ سأله: إذا شربت ثلاثة كؤوس من الخمر فهل هذا العدد كبير؟\",\"t\":\"إذا لم يكن هناك شيطان، ليس العدد بكبير، ولكن إذا كان هناك شيطان، عندئذ فإن العدد كبير جداً. فالخمر غريب عن الرهبان الذين يعيشون وفقاً لمشيئة الله.\",\"g\":[\"الجهاد\",\"الصوم\",\"التمييز\"],\"k\":\"210.1\"},{\"i\":306,\"f\":\"الأب كسويس\",\"p\":210,\"n\":2,\"c\":\"قاله لأخ شكا أن المطر لا ينزل رغم صلواتهم الطويلة\",\"t\":\"أرى أنكم لا تصلّون بحرارة.\",\"g\":[\"الصلاة\",\"الإيمان\"],\"k\":\"210.2\"},{\"i\":307,\"f\":\"الأب كسنثيا\",\"p\":211,\"n\":1,\"t\":\"اللص الذي كان على الصليب تبرّر بكلمة واحدة. ويهوذا الذي كان في مصاف الرسل خسر، في ليلةٍ واحدة، كل ما كان له وانحدر من السماء إلى الجحيم. لأجل هذا لا يفتخر أحد ممن يحيون حياة مترَفة، لأن الذين يعتمدون على أنفسهم يسقطون.\",\"g\":[\"الاتضاع\",\"الكبرياء\",\"التوبة\"],\"k\":\"211.1\"},{\"i\":308,\"f\":\"الأب كسنثيا\",\"p\":211,\"n\":3,\"t\":\"الكلب أفضل مني، لأن عنده محبة، ولا يأتي إلى دينونة أحد.\",\"g\":[\"الاتضاع\",\"الإدانة\",\"المحبة\"],\"k\":\"211.3\"},{\"i\":309,\"f\":\"الأب أوليمبيوس\",\"p\":212,\"n\":2,\"c\":\"قاله لفكره بعد أن جبل من الطين امرأة وابنة فأرهقه العمل في إعالتهما\",\"t\":\"إذا كنت لا تقدر أن تحتمل التعب، لا تطلب الزواج من امرأة.\",\"g\":[\"الأفكار\",\"الجهاد\"],\"k\":\"212.2\"},{\"i\":310,\"f\":\"الأب أورسيسيوس\",\"p\":213,\"n\":1,\"t\":\"الطوب غير المطبوخ عندما يوضع في أساس قرب النهر، لا يصمد يوماً واحداً، أمّا المطبوخ فيصمد كالحجر. هكذا الإنسان الذي فيه فكر جسدي لم ينصهر بمخافة الله، كما حصل ليوسف، فإنه سرعان ما يتداعى ويسقط عندما يتسلم مسؤولية.\",\"g\":[\"خوف الله\",\"الاتضاع\",\"التمييز\"],\"k\":\"213.1\"},{\"i\":311,\"f\":\"الأب أورسيسيوس\",\"p\":213,\"n\":2,\"t\":\"أعتقد أن الإنسان إذا لم يحفظ قلبه جيداً، فإنه سرعان ما ينسى ويهمل ما قد سمع. هكذا إذا وجد العدو فيه مكاناً، يقتحمه، لأنه كما أن السراج الذي أعدّ ليضيء، إذا أهملنا وضع الزيت فيه، فإنه ينطفىء تدريجياً، ومن ثم تقوى عليه الظلمة.\",\"g\":[\"السهر\",\"الأفكار\",\"الصلاة\"],\"k\":\"213.2\"},{\"i\":312,\"f\":\"الأب أورسيسيوس\",\"p\":214,\"n\":2,\"t\":\"ولكن إذا كان الإنسان جيداً في استعداده إلى الله، ولكن يستولي عليه الكسل قليلاً، فإن الله كرحيم، يسكب فيه مخافته، وذكر العقاب، فيقوّيه ليسهر ويصحو، ويحفظ نفسه بكل أمان حتى حضور الله وافتقاده.\",\"g\":[\"الرحمة\",\"السهر\",\"خوف الله\"],\"k\":\"214.2\"},{\"i\":313,\"f\":\"الأب عمون\",\"p\":215,\"n\":2,\"c\":\"قاله للأب بيمن لما جاءه يشكو أن لأخيه صلة بإنسان من خارج القلاية\",\"t\":\"يا بيمن، أما تزال حياً؟ إذهب ولازم قلايتك وضع في قلبك أن لك سنة كاملة في القبر.\",\"g\":[\"ذكر الموت\",\"الخلوة\"],\"k\":\"215.2\"},{\"i\":314,\"f\":\"الأب بيمن\",\"p\":215,\"n\":3,\"c\":\"جوابًا للذين سألوه لماذا لم يعطِ الأب أنوف جواباً\",\"t\":\"لا يهمني شيء لأني ميت، والميت لا يقدر أن يتكلم.\",\"g\":[\"الاتضاع\",\"الصمت\",\"ذكر الموت\"],\"k\":\"215.3\"},{\"i\":315,\"f\":\"الأب بيمن\",\"p\":218,\"n\":8,\"c\":\"جوابًا لأخ سأله لماذا رفض أن يكلّم ناسكًا زاره\",\"t\":\"هذا ينتمي إلى ما هو فوق ويتكلم في السماويات، أمّا أنا، فأنتمي إلى ما هو أسفل، إلى الأرضيات. لو أنه حدّثني عن أهواء النفس، لكنت أجبته في الحال. ولكن عندما كلّمني على الروحانيات، لم أجبه بكلمة، لأني لا أعرفها.\",\"g\":[\"الاتضاع\",\"الأفكار\",\"الحكمة\"],\"k\":\"218.8\"},{\"i\":316,\"f\":\"الأب بيمن\",\"p\":220,\"n\":12,\"c\":\"جوابًا لأخ اعترف له وأراد أن يتوب ثلاث سنوات، فقال له الحاضرون: وهل يكتفي بأربعين يوماً؟\",\"t\":\"أقول لكم، إنه إذا تاب الإنسان من كل قلبه وتوقف عن الخطيئة، فإن الله يقبله حتى في ثلاثة أيام.\",\"g\":[\"التوبة\",\"الرجاء\",\"الرحمة\"],\"k\":\"220.12\"},{\"i\":317,\"f\":\"الأب بيمن\",\"p\":220,\"n\":13,\"t\":\"إن علامة الراهب تظهر في التجارب.\",\"g\":[\"الضيقات\",\"الصبر\"],\"k\":\"220.13\"},{\"i\":318,\"f\":\"الأب بيمن\",\"p\":220,\"n\":14,\"t\":\"كما أن سيّاف الملك يقف إلى جانبه متأهباً على الدوام، هكذا على النفس أن تكون متأهبة ومستعدة أمام شيطان الزنى.\",\"g\":[\"السهر\",\"الشهوة\",\"الجهاد\"],\"k\":\"220.14\"},{\"i\":319,\"f\":\"الأب بيمن\",\"p\":220,\"n\":15,\"c\":\"جوابًا للأب أنوف الذي سأله عن الأفكار الدنسة التي يلدها قلب الإنسان\",\"t\":\"«وهل تفتخر الفأس بدون من يقطع بها» (أشعياء ١٠: ١٥). أنت أيضاً، لا تعطها مجالاً، لئلا تبقى.\",\"g\":[\"الأفكار\",\"السهر\",\"الكتاب المقدس\"],\"k\":\"220.15\"},{\"i\":320,\"f\":\"الأب بيمن\",\"p\":220,\"n\":16,\"t\":\"لو لم يأت رئيس الطهاة نبوزراداان، لما احترق معبد الرب. وهذا يعني أنه بدون التوقف عن محبة البطن، يسقط العقل الأعلى في حربه مع العدو.\",\"g\":[\"الصوم\",\"الجهاد\"],\"k\":\"220.16\"},{\"i\":321,\"f\":\"الأب بيمن\",\"p\":221,\"n\":18,\"t\":\"لا تسكن في مكان ترى فيه أناساً ممتلئين حسداً ضدك، وإلاّ توقف تقدمك.\",\"g\":[\"التمييز\",\"الحكمة\"],\"k\":\"221.18\"},{\"i\":322,\"f\":\"الأب بيمن\",\"p\":221,\"n\":20,\"c\":\"جوابًا للأب أشعيا الذي سأله عن الأفكار النجسة\",\"t\":\"كما أن الثياب الكثيرة الموضوعة في خزانة، لمدة طويلة، تهترىء، هكذا الأفكار، إذا لم ننفذها جسدياً فإنها مع الوقت تتلاشى، أي تهترىء.\",\"g\":[\"الأفكار\",\"الصبر\"],\"k\":\"221.20\"},{\"i\":323,\"f\":\"الأب بيمن\",\"p\":221,\"n\":21,\"c\":\"جوابًا للأب يوسف الذي سأله عن الشيء نفسه\",\"t\":\"كما أنه إذا وضع المرء ثعباناً أو عقرباً في وعاء، يموتان مع الوقت، هكذا الأفكار الشريرة التي تخرج من الشياطين، فإنها بالصبر تتلاشى وتزول.\",\"g\":[\"الأفكار\",\"الصبر\"],\"k\":\"221.21\"},{\"i\":324,\"f\":\"الأب بيمن\",\"p\":222,\"n\":23,\"t\":\"إذا خطىء الإنسان ورفض الاعتراف بخطيئته قائلاً: «ما خطئت»، لا تبكته وإلاّ فأنت تثبّط من عزيمته. ولكن إذا قلت له: لا تحزن يا أخي، إنما انتبه للمستقبل، فإنك تنهض نفسه إلى التوبة.\",\"g\":[\"التوبة\",\"الرحمة\",\"الحكمة\"],\"k\":\"222.23\"},{\"i\":325,\"f\":\"الأب بيمن\",\"p\":222,\"n\":24,\"t\":\"الخبرة جميلة، لأنها تجعل الإنسان ممتحناً أكثر.\",\"g\":[\"الحكمة\"],\"k\":\"222.24\"},{\"i\":326,\"f\":\"الأب بيمن\",\"p\":222,\"n\":26,\"c\":\"قاله لما صادف امرأة تبكي بمرارة عند قبر\",\"t\":\"إذا انسكبت كل مباهج هذه الدنيا، لا تقدر أن ترفع النوح عن نفس هذه المسكينة. هكذا الراهب، يجب عليه أن يقتني النوح في قلبه على الدوام.\",\"g\":[\"الدموع\",\"التوبة\"],\"k\":\"222.26\"},{\"i\":327,\"f\":\"الأب بيمن\",\"p\":222,\"n\":27,\"t\":\"هناك إنسان يبدو صامتاً، لكن قلبه يدين كثيرين. مثل هذا الإنسان يتكلم باستمرار. وثمة آخر يتكلم من الصباح حتى المساء، لكنه يلتزم الصمت. هذا يعني أنه لا يتكلم البتة بدون نفع.\",\"g\":[\"الصمت\",\"الإدانة\",\"اللسان\"],\"k\":\"222.27\"},{\"i\":328,\"f\":\"الأب بيمن\",\"p\":222,\"n\":28,\"c\":\"جوابًا لأخ قال: عندي أفكار كثيرة تعرّضني للخطر، فقاده إلى الهواء الطلق وقال له: أمدد صدرك وأمسك الرياح\",\"t\":\"إذا كنت عاجزاً عن هذا، أنت لا تقدر أن تمنع الأفكار عنك. ولكن بمقدورك أن تقاومها.\",\"g\":[\"الأفكار\",\"الجهاد\"],\"k\":\"222.28\"},{\"i\":329,\"f\":\"الأب بيمن\",\"p\":222,\"n\":29,\"t\":\"إذا كان ثلاثة معاً، الواحد يحيا السكينة جيداً، والثاني يمرض ويشكر، والثالث يخدم بفكر طاهر، فإن الثلاثة يقومون بالعمل نفسه.\",\"g\":[\"الشركة\",\"الشكر\",\"الخدمة\",\"الصبر\"],\"k\":\"222.29\"},{\"i\":330,\"f\":\"الأب بيمن\",\"p\":223,\"n\":30,\"c\":\"تفسيره للمزمور: «كما تتوق الإيل إلى ينابيع المياه كذلك تتوق نفسي إليك يا الله»\",\"t\":\"هكذا الرهبان، عندما يقيمون في البرية يلتهبون بسمّ الشياطين الأشرار، فيطلبون السبت والأحد لكي يأتوا إلى ينابيع الماء، أعني إلى جسد المسيح ودمه، وذلك لكي يتطهروا ويتنقوا من مرارة الشرير.\",\"g\":[\"الكنيسة\",\"الجهاد\",\"الصلاة\"],\"k\":\"223.30\"},{\"i\":331,\"f\":\"الأب بيمن\",\"p\":223,\"n\":31,\"c\":\"جوابًا للأب يوسف الذي سأله: كيف ينبغي أن نصوم؟\",\"t\":\"كل هذه اختبرها الآباء، لأنهم كانوا أقوياء. فوجدوا أن الأفضل هو أن يأكل الإنسان قليلاً كل يوم، ثم سلّمونا الطريق الملوكي الخفيف.\",\"g\":[\"الصوم\",\"الحكمة\",\"التمييز\"],\"k\":\"223.31\"},{\"i\":332,\"f\":\"الأب بيمن\",\"p\":223,\"n\":34,\"c\":\"جوابًا لأخ سأله: ما معنى «لا تقابل شراً بشر»؟\",\"t\":\"هذا الهوى له أربعة وجوه. الأول من القلب. والثاني من النظر. والثالث من اللسان. والرابع هو لا تقابل شراً بشر. فإذا استطعت أن تنقّي قلبك، لا يصل الهوى إلى النظر. وإذا بلغ إلى النظر، انتبه أن لا تتكلم. وإذا تكلمت، اقطعه على عجل وذلك لئلا تقابل شراً بشر.\",\"g\":[\"الغضب\",\"الأفكار\",\"اللسان\",\"الغفران\"],\"k\":\"223.34\"},{\"i\":333,\"f\":\"الأب بيمن\",\"p\":224,\"n\":35,\"t\":\"إن الإنتباه والصحو والتمييز هي الفضائلُ الثلاثُ التي ترفع النفس وتقودها.\",\"g\":[\"السهر\",\"التمييز\"],\"k\":\"224.35\"},{\"i\":334,\"f\":\"الأب بيمن\",\"p\":224,\"n\":36,\"t\":\"إن أدوات النفس هي أن يرمي الإنسان نفسه أمام الله ولا يعتبر نفسه البتة وأن يهمل مشيئته.\",\"g\":[\"الاتضاع\",\"الطاعة\"],\"k\":\"224.36\"},{\"i\":335,\"f\":\"الأب بيمن\",\"p\":224,\"n\":37,\"t\":\"أمام كل ألم يعتريك، النصر هو الصمت.\",\"g\":[\"الصمت\",\"الصبر\",\"الضيقات\"],\"k\":\"224.37\"},{\"i\":336,\"f\":\"الأب بيمن\",\"p\":224,\"n\":38,\"t\":\"الشبع الجسدي ممقوت أمام الرب.\",\"g\":[\"الصوم\"],\"k\":\"224.38\"},{\"i\":337,\"f\":\"الأب بيمن\",\"p\":224,\"n\":39,\"t\":\"النوح مزدوج. إنه يعمل ويحفظ.\",\"g\":[\"الدموع\",\"التوبة\"],\"k\":\"224.39\"},{\"i\":338,\"f\":\"الأب بيمن\",\"p\":224,\"n\":40,\"t\":\"إذا جاءك فكر يطلب حاجات الجسد الضرورية، فأذعنت له في المرة الأولى، ثم جاءك ثانية، فأذعنت له أيضاً، ثم ثالثة، فلا تكترث له، لأنه عديم النفع.\",\"g\":[\"الأفكار\",\"الجهاد\",\"التمييز\"],\"k\":\"224.40\"},{\"i\":339,\"f\":\"الأب بيمن\",\"p\":224,\"n\":41,\"c\":\"جوابًا لأخ سأله: ما هو الازدراء؟\",\"t\":\"هو أن تكون دون الحيوانات، وأن تعلم أنها تخلو من العيب.\",\"g\":[\"الاتضاع\"],\"k\":\"224.41\"},{\"i\":340,\"f\":\"الأب بيمن\",\"p\":224,\"n\":42,\"t\":\"إذا تذكّر المرء القول المكتوب «بكلامك تتبرر وبكلامك تدان» (متى ١٢: ٣٧) فإنه سرعان ما يؤثر الصمت.\",\"g\":[\"الصمت\",\"اللسان\",\"الكتاب المقدس\"],\"k\":\"224.42\"},{\"i\":341,\"f\":\"الأب بيمن\",\"p\":224,\"n\":43,\"t\":\"التشتت هو بدء الشرور.\",\"g\":[\"الأفكار\",\"الخلوة\"],\"k\":\"224.43\"},{\"i\":342,\"f\":\"الأب إيسيذورس الكاهن\",\"p\":224,\"n\":44,\"c\":\"خطاب ألقاه في الاسقيط، يرويه الأب بيمن\",\"t\":\"إخوتي، ألم نأت للتعب في هذا المكان؟ لكن الآن لم يعد هناك من تعب. وأنا إذا أعددت معطفي أقدر أن أذهب إلى حيث التعب فأجد راحة.\",\"g\":[\"الجهاد\",\"الزهد\"],\"k\":\"224.44\"},{\"i\":343,\"f\":\"الأب بيمن\",\"p\":222,\"n\":25,\"t\":\"من يعلّم ولا يعمل بما يقول، يشبه عين ماء تسقي وتروي وتغسل كل شيء لكن لا تقدر أن تنظف نفسها.\",\"g\":[\"الخدمة\",\"الحكمة\",\"الاتضاع\"],\"k\":\"222.25\"},{\"i\":344,\"f\":\"الأب بيمن\",\"p\":225,\"n\":45,\"c\":\"جوابًا لأخ سأل: إذا رأيت شيئاً هل تنصحني أن أبوح به؟\",\"t\":\"من يجب بكلمة قبل أن يسمع، يعمل بجهل. فإذا سئلت أجب، وإلا فاصمت.\",\"g\":[\"الصمت\",\"الحكمة\",\"اللسان\"],\"k\":\"225.45\"},{\"i\":345,\"f\":\"الأب بيمن\",\"p\":225,\"n\":47,\"c\":\"جوابًا لأخ سأل: هل حسن أن نمدح القريب؟\",\"t\":\"بالأحرى خير لك أن تصمت.\",\"g\":[\"الصمت\",\"اللسان\",\"الاتضاع\"],\"k\":\"225.47\"},{\"i\":346,\"f\":\"الأب بيمن\",\"p\":225,\"n\":48,\"t\":\"إذا استطاع الإنسان أن يبني سماء جديدة وأرضاً جديدة، لا يمكنه أن يكون بدون همّ.\",\"g\":[\"الجهاد\",\"السهر\"],\"k\":\"225.48\"},{\"i\":347,\"f\":\"الأب بيمن\",\"p\":225,\"n\":49,\"t\":\"يحتاج الإنسان إلى التواضع ومخافة الله، تماماً كالنفَس الذي يخرج من أنفه.\",\"g\":[\"الاتضاع\",\"خوف الله\"],\"k\":\"225.49\"},{\"i\":348,\"f\":\"الأب بيمن\",\"p\":225,\"n\":50,\"c\":\"جوابًا لأخ سأل: وما هو القبر يا أبت؟ (بعد أن اشترى إبراهيم قبراً لنفسه عند دخوله أرض الميعاد)\",\"t\":\"إنه مكان البكاء والنحيب.\",\"g\":[\"الدموع\",\"ذكر الموت\"],\"k\":\"225.50\"},{\"i\":349,\"f\":\"الأب بيمن\",\"p\":225,\"n\":51,\"c\":\"جوابًا لأخ خشي أن يفسد الشيطان عطاءه للأخ بدافع إرضاء الناس\",\"t\":\"حتى ولو صار هذا بداعي إرضاء الناس، فإننا سنعطي القريب ما هو بحاجة إليه.\",\"g\":[\"الرحمة\",\"الخدمة\"],\"k\":\"225.51\"},{\"i\":350,\"f\":\"الأب عمون\",\"p\":226,\"n\":52,\"c\":\"رواها الأب بيمن عن الأب عمون: إنسان يقضي السنة كلها وهو يمسك بفأس ولا يجد طريقة ليوقع الشجرة، وآخر خبير بقطع الشجر يوقعها بضربات معدودات\",\"t\":\"إن الفأس هي التمييز.\",\"g\":[\"التمييز\",\"الحكمة\"],\"k\":\"226.52\"},{\"i\":351,\"f\":\"الأب بيمن\",\"p\":226,\"n\":53,\"c\":\"جوابًا لأخ سأل: كيف ينبغي على الإنسان أن يسلك؟\",\"t\":\"نرى دانيال أنه لم تكن عليه تهمة إلا في خدمة الرب إلهه.\",\"g\":[\"الخدمة\",\"الجهاد\"],\"k\":\"226.53\"},{\"i\":352,\"f\":\"الأب بيمن\",\"p\":226,\"n\":54,\"t\":\"إن إرادة الإنسان سور نحاسي بينه وبين الله وحجر يصد الهجمات. فإذا هجرها الإنسان يقول هو نفسه «بعون إلهي أسوّر الأسوار» (مزمور ١٧: ٣). فإذا تماشى البرّ مع المشيئة، يهلك الإنسان.\",\"g\":[\"الطاعة\",\"الاتضاع\"],\"k\":\"226.54\"},{\"i\":353,\"f\":\"الأب ألونيوس\",\"p\":226,\"n\":55,\"c\":\"روى الأب بيمن عن الأب ألونيوس وقد امتدحه بعض الآباء الجالسين للطعام فلم يجب بكلمة\",\"t\":\"إذا أجبتهم أكون قد قبلت المديح.\",\"g\":[\"الاتضاع\",\"المجد الباطل\"],\"k\":\"226.55\"},{\"i\":354,\"f\":\"الأب بيمن\",\"p\":226,\"n\":56,\"t\":\"الناس في أغلب الأحوال يتكلمون، وفي القليل يعملون.\",\"g\":[\"اللسان\",\"العمل\"],\"k\":\"226.56\"},{\"i\":355,\"f\":\"الأب بيمن\",\"p\":226,\"n\":57,\"t\":\"كما أن الدخان يطرد النحل، عندئذ يقطف الشهد والعسل معاً، هكذا تطرد الراحة الجسدية مخافة الله من النفس وتصرفها عن العمل.\",\"g\":[\"خوف الله\",\"الجهاد\"],\"k\":\"226.57\"},{\"i\":356,\"f\":\"الأب بيمن\",\"p\":226,\"n\":58,\"c\":\"جوابًا لأخ قال إنه خشي ألا يُفتح له الباب بسبب الصوم الأربعيني المقدس\",\"t\":\"نحن لا نعرف أن نغلق الباب الخشبي لكن باب اللسان.\",\"g\":[\"اللسان\",\"الصمت\"],\"k\":\"226.58\"},{\"i\":357,\"f\":\"الأب بيمن\",\"p\":227,\"n\":59,\"t\":\"يجب أن نهرب من الجسديات، لأن الإنسان عندما يكون أمام حرب جسدية يشبه إنساناً يقف أمام جبّ عميق متى شاء العدو يرميه فيه. ولكن عندما يكون بعيداً عن الجسديات، يشبه رجلاً يقف بعيداً عن الجبّ، فالعدو وإن حاول أن يجرّه لكي يرميه فيه، فإن الله يرسل له العون والمساعدة.\",\"g\":[\"الشهوة\",\"الجهاد\",\"الرجاء\"],\"k\":\"227.59\"},{\"i\":358,\"f\":\"الأب بيمن\",\"p\":227,\"n\":60,\"t\":\"الفقر والشدة والضيق والصوم هي أدوات السيرة الرهبانية، لأنه مكتوب «ولو كان فيها هؤلاء الرجال الثلاثة نوح ودانيال وأيوب، فحيّ أنا يقول الرب» (حزقيال ١٤: ١٤-٢١). نوح هو صورة اللاقنية. وأيوب هو صورة الألم. ودانيال هو مثال التمييز. فإذا وجد الثلاثة معاً في الإنسان، فإن الله يقيم فيه.\",\"g\":[\"الزهد\",\"الضيقات\",\"الصوم\",\"التمييز\"],\"k\":\"227.60\"},{\"i\":359,\"f\":\"الأب بيمن\",\"p\":227,\"n\":61,\"c\":\"قال الأب يوسف: كان يدعو أغاثون أباً مع أنه ما يزال شاباً\",\"t\":\"إنّ أبوّته هذه هي بسبب فمه.\",\"g\":[\"اللسان\",\"الحكمة\"],\"k\":\"227.61\"},{\"i\":360,\"f\":\"الأب بيمن\",\"p\":227,\"n\":63,\"t\":\"علّم فمك أن ينطق بمكنونات قلبك.\",\"g\":[\"اللسان\",\"الصمت\"],\"k\":\"227.63\"},{\"i\":361,\"f\":\"الأب بيمن\",\"p\":227,\"n\":64,\"c\":\"جوابًا لأخ سأل: إذا رأيت سقطة أخي، هل يليق أن أكتمها؟\",\"t\":\"في اللحظة التي نكتم فيها سقطة أخينا، يكتم الله سقطاتنا. ولكن عندما نكشفها، فإن الله يكشف سقطاتنا.\",\"g\":[\"الإدانة\",\"الرحمة\",\"الغفران\"],\"k\":\"227.64\"},{\"i\":362,\"f\":\"الأب بيمن\",\"p\":227,\"n\":65,\"c\":\"جوابًا لأخ سأل الأب بابيسيوس: ماذا أعمل ونفسي عديمة الإحساس ولا تخاف الله؟\",\"t\":\"اذهب والتصق بإنسان يخاف الله، وبملازمتك إياه يعلّمك كيف تخاف الله.\",\"g\":[\"خوف الله\",\"الشركة\",\"الحكمة\"],\"k\":\"227.65\"},{\"i\":363,\"f\":\"الأب بيمن\",\"p\":228,\"n\":66,\"t\":\"إذا استطاع الراهب أن يغلب أمرين، يمكنه أن يتحرر من العالم: الراحة الجسدية والمجد الفارغ.\",\"g\":[\"الجهاد\",\"المجد الباطل\",\"الزهد\"],\"k\":\"228.66\"},{\"i\":364,\"f\":\"الأب بيمن\",\"p\":228,\"n\":68,\"t\":\"هذه السيرة أعطاها الله لإسرائيل، أعني أن يبتعدوا عمّا هو بخلاف الطبيعة أي الغضب والسخط والحسد والكراهية والثرثرة والوقيعة ضد الأخ وكل ما ينتمي إلى العالم القديم.\",\"g\":[\"الغضب\",\"اللسان\",\"الإدانة\"],\"k\":\"228.68\"},{\"i\":365,\"f\":\"الأب بيمن\",\"p\":228,\"n\":69,\"t\":\"إن استطعت أن تتصدق من عمل اليد، فلا تتوانَ، لأنه كُتب أن الإحسان والإيمان يمحوان الخطايا. الإيمان: أن يسلك الإنسان بتواضع وأن يفعل الصدقة.\",\"g\":[\"الرحمة\",\"الاتضاع\",\"الإيمان\"],\"k\":\"228.69\"},{\"i\":366,\"f\":\"الأب بيمن\",\"p\":228,\"n\":70,\"c\":\"جوابًا لأخ قال: إذا رأيت إنساناً سمعت أنه قد سقط لا أريد أن آتي به إلى قلايتي\",\"t\":\"إذا صنعت قليلاً من الخير مع أخيك الصالح، اجعل ضعف هذا مع الآخر، لأن ذاك هو المريض.\",\"g\":[\"الرحمة\",\"الخدمة\",\"المحبة\"],\"k\":\"228.70\"},{\"i\":367,\"f\":\"الأب بيمن\",\"p\":229,\"n\":73,\"t\":\"لا تعتدّ بنفسك إنما التصق بمن يسلك حسناً.\",\"g\":[\"الاتضاع\",\"الشركة\"],\"k\":\"229.73\"},{\"i\":368,\"f\":\"الأب بيمن\",\"p\":230,\"n\":77,\"c\":\"جوابًا لأخ سأل: ما هي السامِيات؟\",\"t\":\"إنها عمل الصالحات.\",\"g\":[\"العمل\",\"الجهاد\"],\"k\":\"230.77\"},{\"i\":369,\"f\":\"الأب بيساريوس\",\"p\":230,\"n\":79,\"c\":\"كما رواه الأب بيمن: أخ سأل الأب بيساريوس: ماذا أعمل؟\",\"t\":\"أصمت ولا تعتدّ بنفسك.\",\"g\":[\"الصمت\",\"الاتضاع\"],\"k\":\"230.79\"},{\"i\":370,\"f\":\"الأب بيمن\",\"p\":230,\"n\":80,\"t\":\"إن من لا يثق به قلبك، لا تدعه يتمسك به.\",\"g\":[\"التمييز\",\"الحكمة\"],\"k\":\"230.80\"},{\"i\":371,\"f\":\"الأب بيمن\",\"p\":230,\"n\":81,\"t\":\"إذا ازدريت نفسك فإنك ستجد راحة حيثما سكنت.\",\"g\":[\"الاتضاع\",\"السلام\"],\"k\":\"230.81\"},{\"i\":372,\"f\":\"الأب سيسوى\",\"p\":230,\"n\":82,\"c\":\"من أقوال بيمن، نقلاً عن الأب سيسوى\",\"t\":\"إن هناك خزياً فيه خطيئة عدم الخوف.\",\"g\":[\"خوف الله\"],\"k\":\"230.82\"},{\"i\":373,\"f\":\"الأب بيمن\",\"p\":231,\"n\":83,\"t\":\"إن المشيئة والراحة والاعتياد عليهما من شأنها أن تحطّم الإنسان.\",\"g\":[\"الجهاد\",\"الطاعة\"],\"k\":\"231.83\"},{\"i\":374,\"f\":\"الأب بيمن\",\"p\":231,\"n\":84,\"t\":\"إذا كنت محباً للصمت ستجد راحة أينما حللت.\",\"g\":[\"الصمت\",\"السلام\"],\"k\":\"231.84\"},{\"i\":375,\"f\":\"الأب بيمن\",\"p\":231,\"n\":86,\"c\":\"جوابًا لأخ سأل: إذا سقط أخ في زلة وتاب، هل يسامحه الله؟\",\"t\":\"إذا كان الله قد طلب من الإنسان أن يغفر لأخيه، ترى ألا يفعل هو بالأحرى الشيء نفسه؟ لأنه قال لبطرس: «سبعين مرة سبع مرات» (متى ١٨: ٢٢).\",\"g\":[\"الغفران\",\"الرحمة\",\"التوبة\"],\"k\":\"231.86\"},{\"i\":376,\"f\":\"الأب بيمن\",\"p\":231,\"n\":88,\"c\":\"جوابًا لأخ سأل: هل يقدر الإنسان أن يضبط جميع أفكاره دون أن يسلم واحداً منها إلى العدو؟\",\"t\":\"ثمة إنسان يأخذ عشرة ويعطي واحداً.\",\"g\":[\"الأفكار\",\"الجهاد\"],\"k\":\"231.88\"},{\"i\":377,\"f\":\"الأب سيسوى\",\"p\":231,\"n\":89,\"c\":\"جوابًا للأخ نفسه حين توجّه بالسؤال إلى الأب سيسوى\",\"t\":\"بالطبع، هناك من لا يقدّم للعدو شيئاً البتة.\",\"g\":[\"الأفكار\",\"الجهاد\"],\"k\":\"231.89\"},{\"i\":378,\"f\":\"الأب بيمن\",\"p\":232,\"n\":91,\"t\":\"لا يمكن أن يكون هناك راهب كثير التشكّي. لا يمكن أن يكون هناك راهب يقابل شراً بشر. لا يمكن أن يكون هناك راهب غضوب.\",\"g\":[\"الصبر\",\"الغضب\",\"الوداعة\"],\"k\":\"232.91\"},{\"i\":379,\"f\":\"الأب بيمن\",\"p\":232,\"n\":92,\"c\":\"جوابًا لشيوخ سألوه: هل يحسن أن ننبّه الإخوة النعسانين في الكنيسة ونحثّهم على السهر في صلاة السهرانية؟\",\"t\":\"في كل حال، إذا حدث أن رأيت أخاً ينعس، للحال أتكيء رأسه على ركبتي لأريحه.\",\"g\":[\"المحبة\",\"الرحمة\",\"السهر\"],\"k\":\"232.92\"},{\"i\":380,\"f\":\"الأب بيمن\",\"p\":232,\"n\":93,\"c\":\"جوابًا لأخ جرّبه الشيطان بالتجديف على الله وخجل أن يبوح بذلك\",\"t\":\"عندما يأتيك هذا الفكر، قل: «أنا لست مسؤولاً عن ذلك، فليرتدّ التجديف عليك يا شيطان، لأن نفسي لا تريد هذا». إذ إن كل ما لا ترغب فيه النفس هو آنيّ.\",\"g\":[\"الأفكار\",\"الرجاء\",\"الجهاد\"],\"k\":\"232.93\"},{\"i\":381,\"f\":\"الأب بيمن\",\"p\":233,\"n\":94,\"c\":\"جوابًا لأخ قال: إنني حيثما حللت أجد عوناً\",\"t\":\"والذين يحملون السيوف في أيديهم، يجدون الله رحيماً في الوقت الحاضر. فإذا كنا شجعاناً فإنه يرحمنا أيضاً.\",\"g\":[\"الجهاد\",\"الرجاء\",\"الرحمة\"],\"k\":\"233.94\"},{\"i\":382,\"f\":\"الأب بيمن\",\"p\":233,\"n\":95,\"t\":\"إذا لام الإنسان نفسه، فإنه يصبر على الشدائد أينما كان.\",\"g\":[\"الاتضاع\",\"الصبر\",\"الضيقات\"],\"k\":\"233.95\"},{\"i\":383,\"f\":\"الأب أنوف\",\"p\":233,\"n\":98,\"c\":\"جوابًا لأخ سأل: وما هو برّه؟ (إذا بلغ الإنسان قامة آية «كل شيء طاهر للأطهار» ورأى ضعفات أخيه فإنه يمارس برّه ويسترها له)\",\"t\":\"أن يلوم نفسه على الدوام.\",\"g\":[\"الاتضاع\",\"الإدانة\"],\"k\":\"233.98\"},{\"i\":384,\"f\":\"الأب بيمن\",\"p\":233,\"n\":99,\"c\":\"جوابًا لأخ سأل: إذا سقطت سقطة يرثى لها فإن فكري ينهشني ويدينني، لماذا سقطت؟\",\"t\":\"عندما يخطئ الإنسان ويقول «خطئت» لا يعود مذنباً.\",\"g\":[\"التوبة\",\"الرجاء\",\"الغفران\"],\"k\":\"233.99\"},{\"i\":385,\"f\":\"الأب بيمن\",\"p\":233,\"n\":100,\"c\":\"جوابًا لأخ سأل: لماذا تقنعني الشياطين لكي أكون مع من هو أرفع مني، بينما تحرّضني على احتقار من هو أدنى مني؟\",\"t\":\"لا تكون في بيت كبير آنية من ذهب وفضة فحسب، بل تكون فيه أيضاً آنية من خشب وخزف، فبعضها لاستعمال شريف وبعضها لاستعمال خسيس. فإذا طهّر أحد نفسه من تلك الآثام، يصير إناء شريفاً مقدساً أهلاً لاستعمال السيد ومستعداً لكل عمل صالح (٢ تيموثاوس ٢: ٢٠).\",\"g\":[\"الاتضاع\",\"الأفكار\",\"التمييز\"],\"k\":\"233.100\"},{\"i\":386,\"f\":\"الأب يوحنا الكولوفي\",\"p\":234,\"n\":101,\"c\":\"قال الأب كولوفوس، جوابًا لأخ سأل: كيف لا أكون حراً في أن أكون مع الشيوخ في أفكاري؟\",\"t\":\"إن العدو لا يفرح كثيراً إلا من الذين لا يظهرون أفكارهم.\",\"g\":[\"الأفكار\",\"الاتضاع\",\"الجهاد\"],\"k\":\"234.101\"},{\"i\":387,\"f\":\"الأب بيمن\",\"p\":234,\"n\":102,\"c\":\"جوابًا لأخ قال: إن قلبي يتوانى إذا استولى عليه تعب قليل\",\"t\":\"ألا نتعجب من يوسف المراهق الذي كان ابن سبع عشرة سنة، كيف قاوم التجربة حتى النهاية؟ فمجّده الله. ألا نرى أيوب كيف أنه لم يتراجع بل تمسك بالصبر حتى النهاية؟ فلم تتمكن التجارب أن تزعزع إيمانه ورجاءه بالله.\",\"g\":[\"الصبر\",\"الضيقات\",\"الإيمان\",\"الرجاء\"],\"k\":\"234.102\"},{\"i\":388,\"f\":\"الأب بيمن\",\"p\":234,\"n\":103,\"t\":\"إن الحياة المشتركة تحتاج إلى أمور ثلاثة: عمل التواضع، وعمل الطاعة والعمل الذي منطلقه ومركزه الحياة المشتركة.\",\"g\":[\"الشركة\",\"الاتضاع\",\"الطاعة\"],\"k\":\"234.103\"},{\"i\":389,\"f\":\"الأب بيمن\",\"p\":234,\"n\":106,\"t\":\"كثيرون من آبائنا صاروا رجالاً في النسك، لكن في دقة الأفكار واحد أو اثنان.\",\"g\":[\"الأفكار\",\"التمييز\",\"الجهاد\"],\"k\":\"234.106\"},{\"i\":390,\"f\":\"الأب بيمن\",\"p\":235,\"n\":107,\"c\":\"جوابًا للأب إسحق حين سمع صوت طائر وسأله: هل يوجد مثل هذه الأصوات هنا؟\",\"t\":\"إسحق، لماذا ترغمني على الكلام؟ أمثالك يصغون إلى هذه الأصوات. لكن من يسهر لا يكترث لها.\",\"g\":[\"السهر\",\"اللسان\",\"الصمت\"],\"k\":\"235.107\"},{\"i\":391,\"f\":\"الأب بيمن\",\"p\":236,\"n\":111,\"c\":\"جوابًا لأخ قال: قل لي كلمة\",\"t\":\"عندما تشتعل النار تحت المرجل، لا تقدر الذبابة أو سواها من الحيوانات الزاحفة أن تدنو منه. لكن عندما يبرد، فإنها تتمكن حتى من الجلوس فوقه. هكذا هو الراهب، كلما ثابر على أعماله الروحية، فإن العدو لا يجد مكاناً يقتحمه منه.\",\"g\":[\"الجهاد\",\"السهر\",\"الصلاة\"],\"k\":\"236.111\"},{\"i\":392,\"f\":\"الأب بيمن\",\"p\":236,\"n\":113,\"c\":\"جوابًا لبعض الآباء سألوه: إذا رأينا أخاً يخطئ، هل نوبّخه؟\",\"t\":\"في كل حال، إذا اضطررت أن أجتاز من هناك، ورأيته يخطئ، أتجاوزه ولا أوبّخه.\",\"g\":[\"الإدانة\",\"الرحمة\",\"الصبر\"],\"k\":\"236.113\"},{\"i\":393,\"f\":\"الأب بيمن\",\"p\":236,\"n\":115,\"c\":\"جوابًا لأخ سأل: ماذا أعمل إذ أحارب بالزنى والغضب؟\",\"t\":\"سحقت الأسد وخنقت الدب (١ملوك ١٧: ٣٥)، أي أنني استأصلت الغضب وضيّقت على الزنى بالأتعاب.\",\"g\":[\"الغضب\",\"الشهوة\",\"الجهاد\"],\"k\":\"236.115\"},{\"i\":394,\"f\":\"الأب بيمن\",\"p\":236,\"n\":116,\"t\":\"لا يستطيع الإنسان أن يجد محبة أعظم من بذل النفس عن القريب (يوحنا ١٥: ١٣)، لأن الإنسان، إذا ما سمع أمراً شريراً، أي محزناً ـ مع العلم أنه هو نفسه قد يقول أمراً مماثلاً ـ وجاهد لئلا ينطق به، أو إذا صار ضحية الطمع، فاحتمل، فإن مثل هذا قادر أن يبذل حياته عن قريبه.\",\"g\":[\"المحبة\",\"الصبر\",\"اللسان\"],\"k\":\"236.116\"},{\"i\":395,\"f\":\"الأب بيمن\",\"p\":237,\"n\":117,\"c\":\"جوابًا لأخ سأل: من هو المرائي؟\",\"t\":\"هو من يعلّم قريبه أمراً لم يبلغ هو إليه، لأنه مكتوب: «ولماذا تنظر إلى القذى في عين أخيك، وها هي الخشبة في عينك أنت» (متى ٧: ٣)، وهكذا دواليك.\",\"g\":[\"الإدانة\",\"الاتضاع\",\"الكبرياء\"],\"k\":\"237.117\"},{\"i\":396,\"f\":\"الأب بيمن\",\"p\":237,\"n\":118,\"c\":\"جوابًا لأخ سأل: وما معنى أن يغضب الإنسان على أخيه دون سبب؟ (متى ٥: ٢٢)\",\"t\":\"إذا غضبت لكل جشع يمارسه أخوك ضدك، فإنك تغضب دون سبب. فإذا قلع عينك اليمنى وقطع يدك اليمنى أيضاً وغضبت عليه، فإنك تغضب دون سبب. ولكن إذا فصلك عن الله، حينئذ إغضب.\",\"g\":[\"الغضب\",\"الصبر\",\"الغفران\"],\"k\":\"237.118\"},{\"i\":397,\"f\":\"الأب بيمن\",\"p\":237,\"n\":119,\"c\":\"جوابًا لأخ سأل: ماذا أفعل بخطاياي؟\",\"t\":\"من أراد التحرر من خطاياه، يتخلص منها بالبكاء. ومن أراد أن يجني الفضائل، يقتنيها بالبكاء، لأن البكاء هو الطريق الذي سلّمه إلينا الكتاب المقدس والآباء قائلاً: ابكوا ونوحوا. في الحقيقة ليس هناك من طريق سواه يا ولدي.\",\"g\":[\"الدموع\",\"التوبة\",\"الكتاب المقدس\"],\"k\":\"237.119\"},{\"i\":398,\"f\":\"الأب بيمن\",\"p\":237,\"n\":120,\"c\":\"جوابًا لأخ سأل: وما هي التوبة عن الخطيئة؟\",\"t\":\"إنها أن لا نرتكب الخطيئة فيما بعد. لأجل هذا دعي الأبرار بلا عيب، وذلك لأنهم هجروا الخطيئة فصاروا أبراراً.\",\"g\":[\"التوبة\",\"الجهاد\"],\"k\":\"237.120\"},{\"i\":399,\"f\":\"الأب بيمن\",\"p\":237,\"n\":121,\"t\":\"إن شر الناس يختبيء وراءهم.\",\"g\":[\"الحكمة\",\"الإدانة\"],\"k\":\"237.121\"},{\"i\":400,\"f\":\"الأب بيمن\",\"p\":238,\"n\":122,\"c\":\"جوابًا لأخ سأل: ماذا أفعل بالاضطرابات التي تزعجني؟\",\"t\":\"فلنبك أمام الله في كل أتعابنا، إلى أن يعلن لنا رحمته.\",\"g\":[\"الدموع\",\"الضيقات\",\"الرجاء\"],\"k\":\"238.122\"},{\"i\":401,\"f\":\"الأب بيمن\",\"p\":238,\"n\":123,\"c\":\"جوابًا لأخ سأل: وماذا أفعل بصداقاتي غير المجدية يا أبت؟\",\"t\":\"هناك من يحشرج حتى الموت، إلا أنه ينتبه لصداقات هذا العالم. فلا تقترب منها ولا تلمسها، وبعد ذلك فإنها بمفردها تبتعد عنك.\",\"g\":[\"الزهد\",\"الجهاد\"],\"k\":\"238.123\"},{\"i\":402,\"f\":\"الأب بيمن\",\"p\":238,\"n\":124,\"c\":\"جوابًا لأخ سأل: هل يستطيع المرء أن يكون كالميت؟\",\"t\":\"إذا وصل إلى الخطيئة يموت، وإذا وصل إلى الصلاح، فإنه يحيا ويعمل الصلاح.\",\"g\":[\"التوبة\",\"الجهاد\",\"ذكر الموت\"],\"k\":\"238.124\"},{\"i\":403,\"f\":\"الأب أنطونيوس\",\"p\":238,\"n\":125,\"c\":\"حدّثنا الأب بيمن أن الأب أنطونيوس قال\",\"t\":\"إن قوة الإنسان الكبرى تكمن في أن يضع خطيئته دوماً نصب عينيه أمام الله وأن ينتظر التجربة حتى النسمة الأخيرة.\",\"g\":[\"التوبة\",\"الاتضاع\",\"الصبر\"],\"k\":\"238.125\"},{\"i\":404,\"f\":\"الأب بيمن\",\"p\":238,\"n\":126,\"c\":\"جوابًا عن سؤال: ولمن يتوجه القول المكتوب «لا تهتموا للغد» (متى ٦: ٣٤)؟\",\"t\":\"لقد قيل هذا للإنسان الذي تأتيه التجارب فلا يكترث كثيراً، وذلك لئلا يهتم قائلاً: وكم سيطول بقاء هذه التجربة معي؟ فبالأحرى به أن يفكر يومياً ويقول: «اليوم».\",\"g\":[\"الصبر\",\"الضيقات\",\"الرجاء\"],\"k\":\"238.126\"},{\"i\":405,\"f\":\"الأب بيمن\",\"p\":238,\"n\":127,\"t\":\"أن يعلّم الإنسان قريبه، فهذا من شأن الصُّم والعديمي الأهواء، لأنه ما قيمة الإنسان إذا بنى بيت قريبه وهدم بيته.\",\"g\":[\"الاتضاع\",\"الحكمة\",\"الكبرياء\"],\"k\":\"238.127\"},{\"i\":406,\"f\":\"الأب بيمن\",\"p\":238,\"n\":129,\"t\":\"كل ما يتجاوز القياس هو من الشياطين.\",\"g\":[\"التمييز\",\"الحكمة\"],\"k\":\"238.129\"},{\"i\":407,\"f\":\"الأب بيمن\",\"p\":238,\"n\":130,\"t\":\"عندما يزمع الإنسان أن يبني بيتاً، فإنه يجمع طاقات كثيرة لكي يرفعه وينهض به. هكذا نحن، علينا أن نأخذ قليلاً من كل الفضائل.\",\"g\":[\"الجهاد\",\"الحكمة\"],\"k\":\"238.130\"},{\"i\":408,\"f\":\"الأب بيمن\",\"p\":238,\"n\":131,\"c\":\"جوابًا لبعض الآباء سألوه: وكيف احتمل الأب نيسثروس تلميذه هكذا؟\",\"t\":\"لو كنت مكانه لجعلت وسادة تحت رأسه.\",\"g\":[\"الصبر\",\"المحبة\",\"الرحمة\"],\"k\":\"238.131\"},{\"i\":409,\"f\":\"الأب بيمن\",\"p\":239,\"n\":132,\"t\":\"إن الجوع والنعاس ما تركانا نرى هذه التفاهات.\",\"g\":[\"السهر\",\"الصوم\",\"الجهاد\"],\"k\":\"239.132\"},{\"i\":410,\"f\":\"الأب بيمن\",\"p\":239,\"n\":133,\"t\":\"كثيرون صاروا أقوياء، لكن القليلين يحثّون على المحبة (عبرانيين ١٠: ٢٤).\",\"g\":[\"المحبة\",\"الشركة\"],\"k\":\"239.133\"},{\"i\":411,\"f\":\"الأب بتنهد\",\"p\":239,\"n\":134,\"c\":\"وأجاب لما سألوه: وما هي؟ قال: أن يلوم الإنسان نفسه\",\"t\":\"كل الفضائل دخلت إلى هذا البيت ما عدا واحدة هي التي، بدونها، بالجهد يصمد الإنسان.\",\"g\":[\"الاتضاع\",\"الجهاد\"],\"k\":\"239.134\"},{\"i\":412,\"f\":\"الأب بيمن\",\"p\":239,\"n\":135,\"t\":\"لا نحتاج إلى أحد، إلا إذا كان عنده ذهن صاحٍ ويقظ.\",\"g\":[\"السهر\",\"الحكمة\"],\"k\":\"239.135\"},{\"i\":413,\"f\":\"الأب بيمن\",\"p\":239,\"n\":136,\"c\":\"جوابًا لأحد الآباء: من هو القائل «رفيق أنا لكل الذين يتقونك ويحفظون وصاياك» (مزمور ١١٨: ٦٣)؟\",\"t\":\"هو الروح القدس.\",\"g\":[\"الكتاب المقدس\",\"خوف الله\"],\"k\":\"239.136\"},{\"i\":414,\"f\":\"الأب بيمن\",\"p\":239,\"n\":137,\"c\":\"جوابًا لأخ قال: إذا غادرت قلايتي ووجدت أخي مشغولاً فانشغلت معه، وإذا وجدته يضحك فضحكت معه، لا أشعر لدى عودتي إلى القلاية أن في قلبي راحة\",\"t\":\"صن نفسك في القلاية وخارجها.\",\"g\":[\"الخلوة\",\"السهر\",\"الأفكار\"],\"k\":\"239.137\"},{\"i\":415,\"f\":\"الأب بيمن\",\"p\":240,\"n\":139,\"t\":\"إذا رأيت مشاهد وسمعت أنباء مهما كانت، لا تنقلها لقريبك، لأن هذا من شأنه أن يثقل الحرب عليه.\",\"g\":[\"اللسان\",\"الصمت\",\"الأفكار\"],\"k\":\"240.139\"},{\"i\":416,\"f\":\"الأب بيمن\",\"p\":240,\"n\":140,\"t\":\"للمرة الأولى اهرب. وللمرة الثانية اهرب. لكن في الثالثة كن كالسيف.\",\"g\":[\"الجهاد\",\"الشهوة\"],\"k\":\"240.140\"},{\"i\":417,\"f\":\"الأب بيمن\",\"p\":240,\"n\":141,\"c\":\"قاله الأب بيمن للأب إسحق\",\"t\":\"خفّف قليلاً من برّك فترتاح في أيامك القليلة.\",\"g\":[\"التمييز\",\"الحكمة\"],\"k\":\"240.141\"},{\"i\":418,\"f\":\"الأب بيمن\",\"p\":240,\"n\":142,\"c\":\"جوابًا لأخ سأل: ما معنى مقت الشرير؟ (بعد أن امتدحوا أخًا لأنه يمقت الشرير)\",\"t\":\"إن مقت الشرير هو أن يمقت الإنسان خطاياه ويبرّر خطايا قريبه.\",\"g\":[\"الإدانة\",\"الاتضاع\",\"الرحمة\"],\"k\":\"240.142\"},{\"i\":419,\"f\":\"الأب بيمن\",\"p\":240,\"n\":143,\"c\":\"جوابًا لأخ قال له: ماذا أعمل؟\",\"t\":\"اذهب وادنُ ممن يقول: «ماذا أريد»؟ فتجد راحة.\",\"g\":[\"الاتضاع\",\"الطاعة\",\"السلام\"],\"k\":\"240.143\"},{\"i\":420,\"f\":\"الأب بيمن\",\"p\":240,\"n\":144,\"c\":\"حدّثنا الأب يوسف عن الأب إسحق أنه رأى الأب بيمن في حالة من الوجد الروحي فسأله: أين كنت؟\",\"t\":\"كان فكري عند مريم والدة الإله التي كانت واقفة عند الصليب تبكي. وكم أردت لو أبكي مثلها باستمرار.\",\"g\":[\"الدموع\",\"التوبة\"],\"k\":\"240.144\"},{\"i\":421,\"f\":\"الأب بيمن\",\"p\":241,\"n\":146,\"c\":\"جوابًا لأخ سأل عن تأثير الأفكار\",\"t\":\"إن هذا يشبه رجلاً يمسك ناراً بيسراه، ووعاء ماء بيمناه. فإذا أشعل النار، يأخذ من الماء الذي في الوعاء ويخمدها. فالنار هي زرع العدو. أما الماء فهي أن تطرح نفسك أمام الله.\",\"g\":[\"الأفكار\",\"الصلاة\",\"الاتضاع\"],\"k\":\"241.146\"},{\"i\":422,\"f\":\"الأب بيمن\",\"p\":241,\"n\":147,\"c\":\"جوابًا لأخ سأل: ما الأفضل، الكلام أم الصمت؟\",\"t\":\"إن من يتحدث عن الله فحسناً يفعل، ومن يصمت حباً بالله يماثله.\",\"g\":[\"الصمت\",\"اللسان\",\"المحبة\"],\"k\":\"241.147\"},{\"i\":423,\"f\":\"الأب بيمن\",\"p\":241,\"n\":148,\"c\":\"جوابًا لأخ سأل: كيف يستطيع المرء أن يهرب من الكلام السيء ضد قريبه؟\",\"t\":\"نحن وإخوتنا صورتان، ففي اللحظة التي ينتبه فيها الإنسان لذاته، ويلوم نفسه، يجد أخاه مكرّماً في عينيه، ولكن عندما يرى نفسه صالحاً، فإنه يجد أخاه شريراً في عينيه.\",\"g\":[\"الإدانة\",\"الاتضاع\",\"اللسان\"],\"k\":\"241.148\"},{\"i\":424,\"f\":\"الأب بيمن\",\"p\":241,\"n\":149,\"c\":\"جوابًا لأخ سأل عن التثاقل والفتور\",\"t\":\"التثاقل موجود في كل بداءة، وليس ثمة هوى أردأ منه. ولكن إذا عرف الإنسان ماهيته يرتاح.\",\"g\":[\"الجهاد\",\"الصبر\"],\"k\":\"241.149\"},{\"i\":425,\"f\":\"الأب بيمن\",\"p\":241,\"n\":150,\"t\":\"رأينا للأب بمفو ثلاثة أعمال جسدية: الصوم حتى المساء كل يوم، والصمت وعمل اليد الكثير.\",\"g\":[\"الصوم\",\"الصمت\",\"العمل\"],\"k\":\"241.150\"},{\"i\":426,\"f\":\"الأب بيمن\",\"p\":242,\"n\":152,\"c\":\"جوابًا لأخ قال: أريد أن أدخل وأعيش في دير فيه حياة شركة\",\"t\":\"إذا أردت أن تدخل إلى ديرٍ ذي حياة مشتركة، ولم تكن عديم الهمّ في كل لقاء وفي كل شيء، يستحيل عليك أن تعمل فيه، لأنه ليس لك من سلطان على دورق الماء.\",\"g\":[\"الشركة\",\"الطاعة\",\"الاتضاع\"],\"k\":\"242.152\"},{\"i\":427,\"f\":\"الأب بيمن\",\"p\":242,\"n\":154,\"t\":\"لا يجوز للإنسان أن يتذكر الزنى والوقعية وحتى أن يفكر بهما في قلبه، لأنه إذا أراد أن يميّز بينهما في داخله، لن ينتفع. لكن إذا تغرّب عنهما يرتاح.\",\"g\":[\"الشهوة\",\"الأفكار\",\"الجهاد\"],\"k\":\"242.154\"},{\"i\":428,\"f\":\"الأب بيمن\",\"p\":242,\"n\":155,\"c\":\"جوابًا للإخوة الذين قالوا: لنرحل من هذا المكان لأن أديرته تزعجنا\",\"t\":\"وهل تغادرون المكان بسبب أصوات الملائكة؟\",\"g\":[\"الصبر\",\"الحكمة\"],\"k\":\"242.155\"},{\"i\":429,\"f\":\"الأب بيمن\",\"p\":242,\"n\":156,\"c\":\"جوابًا لبيتيميوس: إذا حزن أحد بسببي فأظهرت له توبتي لكنه لم يقتنع، ماذا أعمل؟\",\"t\":\"خذ معك اثنين وأظهر توبتك أمامه، وإذا لم يقتنع خذ خمسة. وإذا لم يقتنع، خذ معك كاهناً. وإذا لم يقتنع عندئذ صلّ إلى الله بدون انزعاج لكي يرضيه، أمّا أنت فكن عديم الهمّ.\",\"g\":[\"الغفران\",\"الصلاة\",\"التوبة\"],\"k\":\"242.156\"},{\"i\":430,\"f\":\"الأب بيمن\",\"p\":242,\"n\":157,\"t\":\"إن تعليم القريب شبيه بتوبيخه.\",\"g\":[\"الإدانة\",\"اللسان\",\"الاتضاع\"],\"k\":\"242.157\"},{\"i\":431,\"f\":\"الأب بيمن\",\"p\":242,\"n\":158,\"t\":\"لا تشبع مشيئتك، لكن بالأحرى ذلِّل نفسك لأخيك.\",\"g\":[\"الطاعة\",\"الاتضاع\",\"المحبة\"],\"k\":\"242.158\"},{\"i\":432,\"f\":\"الأب بيمن\",\"p\":242,\"n\":159,\"c\":\"جوابًا لأخ قال: لقد رأيت مكاناً فيه كل راحة للإخوة، هل تنصحني أن أقيم هناك؟\",\"t\":\"اسكن حيث لا تؤذي أخاك.\",\"g\":[\"المحبة\",\"الشركة\"],\"k\":\"242.159\"},{\"i\":433,\"f\":\"الأب بيمن\",\"p\":242,\"n\":160,\"t\":\"إن الثلاثة هذه نافعة: مخافة الرب، والصلاة، والإحسان إلى القريب.\",\"g\":[\"خوف الله\",\"الصلاة\",\"الرحمة\"],\"k\":\"242.160\"},{\"i\":434,\"f\":\"الأب بيمن\",\"p\":243,\"n\":161,\"c\":\"جوابًا لأخ قال: إن جسدي قد أضناه المرض، أمّا أهوائي فلم تمرض\",\"t\":\"الأهواء هي القيح الكثير.\",\"g\":[\"الأفكار\",\"الشهوة\",\"الجهاد\"],\"k\":\"243.161\"},{\"i\":435,\"f\":\"الأب بيمن\",\"p\":243,\"n\":162,\"c\":\"جوابًا لأخ سأل: ماذا أعمل عندما يفتقدنا الله بماذا يكون اهتمامنا؟\",\"t\":\"فلندخل إلى مخادعنا ونتذكر خطايانا، والرب يعيننا في كل شيء.\",\"g\":[\"التوبة\",\"الخلوة\",\"الرجاء\"],\"k\":\"243.162\"},{\"i\":436,\"f\":\"الأب بيمن\",\"p\":243,\"n\":163,\"c\":\"جوابًا لأخ ذاهب إلى السوق سأله: ماذا تريدني أن أعمل؟\",\"t\":\"كن صديقاً لمن يقسو على نفسه، فتبيع سلالك بسهولة.\",\"g\":[\"الزهد\",\"الحكمة\"],\"k\":\"243.163\"},{\"i\":437,\"f\":\"الأب بيمن\",\"p\":243,\"n\":165,\"c\":\"جوابًا عن سؤال عن الدنس\",\"t\":\"إذا تجاوزنا ما هو عمليّ وثابرنا على الصحو بنشاط لن يكون في داخلنا دنس أو نجاسة.\",\"g\":[\"السهر\",\"الجهاد\"],\"k\":\"243.165\"},{\"i\":438,\"f\":\"الأب بيمن\",\"p\":243,\"n\":167,\"t\":\"إذا قام الإنسان بواجباته لا يضطرب.\",\"g\":[\"السلام\",\"العمل\"],\"k\":\"243.167\"},{\"i\":439,\"f\":\"الأب بيمن\",\"p\":243,\"n\":168,\"c\":\"جوابًا لأخ سأل: كيف أقيم في قلايتي؟\",\"t\":\"للجلوس في القلاية يبدو أنه عليك بعمل اليد والأكل بمفردك والصمت مع الدرس. أمّا النمو الخفي فهو أن تحتمل صغر النفس حيثما كنت، وألّا تهمل ساعات الاجتماع وساعات الاختلاء. وإذا حدث أن تأخرت بسبب عمل اليد، ما أن تدخل الاجتماع عجّل إلى اتمام عملك بدون اضطراب. أمّا ذروة هذه فهي أن تقتني لك رفقة صالحة وتبتعد عن المعاشرة الرديئة.\",\"g\":[\"الخلوة\",\"الصمت\",\"الاتضاع\",\"الشركة\"],\"k\":\"243.168\"},{\"i\":440,\"f\":\"الأب بيمن\",\"p\":244,\"n\":169,\"c\":\"جوابًا لأخ سأل عن مالٍ له على أحد: وماذا أعمل؟ إني لا أقدر أن أسيطر على أفكاري\",\"t\":\"اترك فكرك يجري. ألا يكفي ألّا تحزن أخاك.\",\"g\":[\"الأفكار\",\"المحبة\",\"الرحمة\"],\"k\":\"244.169\"},{\"i\":441,\"f\":\"الأب بيمن\",\"p\":244,\"n\":171,\"t\":\"أقول بأني سوف أطرح حيث يرمي الشيطان.\",\"g\":[\"الاتضاع\",\"الجهاد\"],\"k\":\"244.171\"},{\"i\":442,\"f\":\"الأب بيمن\",\"p\":244,\"n\":172,\"c\":\"قاله الأب بيمن للأب أنوف\",\"t\":\"«أبعد نظرك عني لئلا ترى الباطل» (مزمور ١١٨: ٣٧) لأن الحرية تقتل نفوس الكثيرين.\",\"g\":[\"الجهاد\",\"السهر\",\"الشهوة\"],\"k\":\"244.172\"},{\"i\":443,\"f\":\"الأب بيمن\",\"p\":245,\"n\":174,\"c\":\"جوابًا لأخ سأل: ثمة إخوة يقيمون معي، هل تنصحني أن أعطيهم أوامر؟\",\"t\":\"بل كن قدوة في كل شيء وليس مشرّعاً.\",\"g\":[\"الخدمة\",\"الاتضاع\",\"الحكمة\"],\"k\":\"245.174\"},{\"i\":444,\"f\":\"الأب بيمن\",\"p\":245,\"n\":175,\"t\":\"إذا زارك أخ، ورأيت أنك لم تنتفع بدخوله، فتش في فكرك واعلم ماذا الفكر الذي كان عندك قبل دخوله، عندئذ تدرك سبب عدم انتفاعك. وإذا فعلت هذا بتواضع وتعقل، ستكون وإياه بسلام، كونك تحتمل عيوبه. لأن الإنسان إذا وشّح سيرته الرهبانية بالورع والتقوى لا يسقط، فالله أمامه. وأرى أن الإنسان سوف يجني من هذه السيرة مخافة الله.\",\"g\":[\"الاتضاع\",\"الصبر\",\"خوف الله\"],\"k\":\"245.175\"},{\"i\":445,\"f\":\"الأب بيمن\",\"p\":245,\"n\":176,\"t\":\"من يساكن ولداً ويسلك نحوه بهوى من أهواء الإنسان القديم، ويستمرّ على تمسكه به، يشبه إنساناً عنده حقل تلتهمه الديدان والحشرات.\",\"g\":[\"الأفكار\",\"الشهوة\",\"الحكمة\"],\"k\":\"245.176\"},{\"i\":446,\"f\":\"الأب بيمن\",\"p\":245,\"n\":177,\"t\":\"الشر لا يبطل الشر أبداً. إنما إذا أساء إليك أحد، أحسن إليه، لأنك بذلك تضحد الشر.\",\"g\":[\"الغفران\",\"الرحمة\",\"المحبة\"],\"k\":\"245.177\"},{\"i\":447,\"f\":\"الأب بيمن\",\"p\":245,\"n\":178,\"t\":\"إن داود لما عارك الأسد، أمسك به من رقبته وللحال قتله. ونحن أيضاً، إذا أمسكنا بحلقنا وبطننا نغلب، بالله، الأسد غير المنظور.\",\"g\":[\"الجهاد\",\"الصوم\",\"الشهوة\"],\"k\":\"245.178\"},{\"i\":448,\"f\":\"الأب بيمن\",\"p\":245,\"n\":179,\"c\":\"جوابًا لأخ سأل: ماذا أعمل عندما يأتيني الضيق فأضطرب؟\",\"t\":\"العنف من شأنه أن يجعل الصغار والكبار يضطربون.\",\"g\":[\"الغضب\",\"الوداعة\",\"الصبر\"],\"k\":\"245.179\"},{\"i\":449,\"f\":\"الأب بيمن\",\"p\":246,\"n\":181,\"c\":\"جوابًا لرئيس دير سأله: كيف أقدر أن أقتني مخافة الله؟\",\"t\":\"كيف نقتني مخافة الله وفي ديرنا براميل من الجبن وصناديق ملآنة بالأطعمة المملّحة؟\",\"g\":[\"خوف الله\",\"الزهد\",\"الطمع\"],\"k\":\"246.181\"},{\"i\":450,\"f\":\"الأب بيمن\",\"p\":246,\"n\":182,\"c\":\"جوابًا لأخ سأل عن اثنين ماتا في ليلة واحدة، فكّر أحدهما أن يصبح راهباً وفكّر الآخر أن يترك رهبنته في الصباح\",\"t\":\"الراهب مات وهو راهب، والثاني مات وهو من أهل العالم. إذاً الإثنان ماتا بالصفة التي كانا عليها.\",\"g\":[\"ذكر الموت\",\"السهر\"],\"k\":\"246.182\"},{\"i\":451,\"f\":\"الأب بيمن\",\"p\":246,\"n\":183,\"c\":\"جوابًا لزائرين من سوريا سألوه عن قساوة القلب (رواه الأب يوحنا)\",\"t\":\"إن طبيعة الماء ناعمة أمّا طبيعة الحجر فقاسية. فالماء إذا نزل على الصخرة قطرة قطرة يثقبها. هكذا فكلمة الله ناعمة، وقلبنا قاس. والإنسان إذا سمع كلمة الله باستمرار، ينفتح قلبه على مخافة الله.\",\"g\":[\"الكتاب المقدس\",\"خوف الله\",\"الصبر\"],\"k\":\"246.183\"},{\"i\":452,\"f\":\"الأب بيمن\",\"p\":246,\"n\":184,\"c\":\"جوابًا للأب إسحق الذي سأله: كيف أن البعض مارسوا قساوة كبيرة وقد قسوا على أجسادهم؟\",\"t\":\"نحن لم نتعلم أن نكون قاتلي أجساد، بل قاتلي أهواء.\",\"g\":[\"الجهاد\",\"الأفكار\",\"الصوم\"],\"k\":\"246.184\"},{\"i\":453,\"f\":\"الأب بيمن\",\"p\":247,\"n\":185,\"t\":\"ثلاثة لا أقدر أن أقلع عنها: الطعام، واللباس، والنوم. ولكن نقدر أن نتخلى عنها أحياناً.\",\"g\":[\"الزهد\",\"الجهاد\",\"التمييز\"],\"k\":\"247.185\"},{\"i\":454,\"f\":\"الأب بيمن\",\"p\":247,\"n\":186,\"c\":\"جوابًا لأخ قال: أتناول الكثير من الخضار\",\"t\":\"هذا لا يوافقك، فكُلْ خبزك مع قليل من الخضار فقط. ولا تذهب إلى بيت أبيك من أجل حاجتك.\",\"g\":[\"الزهد\",\"التمييز\"],\"k\":\"247.186\"},{\"i\":455,\"f\":\"الأب بيمن\",\"p\":247,\"n\":187,\"c\":\"قالوا عن الأب بيمن إنه لما كان يجالس الآباء ويدور الحديث على شيوخ غائبين ويذكر اسم الأب سيسوى، كان يقول\",\"t\":\"اتركوا سيسوى وشأنه لأن أموره لم يصل أحد إلى قامة الحديث عنها.\",\"g\":[\"الاتضاع\",\"الإدانة\"],\"k\":\"247.187\"},{\"i\":456,\"f\":\"الأب بمفو\",\"p\":248,\"n\":2,\"c\":\"جوابًا لأخوين سأله أحدهما عن صيامه يومين وأكله خبزتين، وسأله الآخر عن عمل يده وصدقته\",\"t\":\"حسنة هي الأعمال، لكن إذا حفظتما ضميركما نقياً تجاه القريب، تخلصان.\",\"g\":[\"المحبة\",\"الإدانة\",\"الصوم\",\"الرحمة\"],\"k\":\"248.2\"},{\"i\":457,\"f\":\"الأب بمفو\",\"p\":249,\"n\":4,\"c\":\"جوابًا لمرافقيه حين رأى في الإسكندرية ممثّلة فبكى وقال لهم هذا\",\"t\":\"تأثرت لأمرين: الأول هو ضياع هذه المرأة، والثاني أنني لا أملك الحماس والغيرة الكافية لأرضي الله كما ترضي هذه المرأة الناس.\",\"g\":[\"الدموع\",\"خوف الله\"],\"k\":\"249.4\"},{\"i\":458,\"f\":\"الأب بمفو\",\"p\":249,\"n\":5,\"t\":\"الشكر لله أنني منذ أن رفضت العالم، لم أندم على كلمة تلفظت بها.\",\"g\":[\"اللسان\",\"الصمت\",\"الشكر\"],\"k\":\"249.5\"},{\"i\":459,\"f\":\"الأب بمفو\",\"p\":249,\"n\":6,\"t\":\"الراهب يجب أن يرتدي لباساً بحيث إذا رُمي خارج القلاية ثلاثة أيام، لا يلتقطه أحد.\",\"g\":[\"الزهد\"],\"k\":\"249.6\"},{\"i\":460,\"f\":\"الأب بمفو\",\"p\":249,\"n\":7,\"c\":\"لما رأى أناساً من أهل العالم يجلسون في نواحي مصر وهو يمشي مع بعض الإخوة\",\"t\":\"انهضوا وقبّلوا الرهبان لكي تتباركوا. فهؤلاء يتكلمون مع الله على الدوام وأفواههم طاهرة.\",\"g\":[\"الصلاة\",\"الاتضاع\",\"اللسان\"],\"k\":\"249.7\"},{\"i\":461,\"f\":\"الأب بمفو\",\"p\":249,\"n\":8,\"c\":\"قالها للحاضرين معه من الرجال القديسين لمّا أوشك أن ينتقل من هذا العالم\",\"t\":\"منذ أن أتيت إلى هذا المكان وبنيت قلايتي فيه، لا أذكر أنني أكلت خبزاً لم أصنعه أنا. ولم أندم إلى الآن على كلمة تلفظت بها. وها أنا الآن ذاهب إليه، وكأنني لم أبدأ تعبّدي له بعد.\",\"g\":[\"العمل\",\"اللسان\",\"الاتضاع\"],\"k\":\"249.8\"},{\"i\":462,\"f\":\"الأب بمفو\",\"p\":249,\"n\":10,\"t\":\"إذا كان لك قلب يمكنك أن تخلص.\",\"g\":[\"الرجاء\",\"التوبة\"],\"k\":\"249.10\"},{\"i\":463,\"f\":\"الأب بمفو\",\"p\":250,\"n\":11,\"c\":\"جوابًا لكاهن من النطرون سأله: كيف يمكن للإخوة أن يسلكوا؟\",\"t\":\"بنسك كبير وهم يحفظون ضميرهم طاهراً نقياً تجاه القريب.\",\"g\":[\"المحبة\",\"الإدانة\",\"الجهاد\"],\"k\":\"250.11\"},{\"i\":464,\"f\":\"الأب بمفو\",\"p\":250,\"n\":13,\"c\":\"جوابًا لما ضحك وقد ربطت الشياطين طيراً بخشبة تمسكه\",\"t\":\"لم أكن أضحك بل كنت أهزأ من ضعفكم كونكم جميعاً تمسكون طيراً واحداً.\",\"g\":[\"الجهاد\",\"الأفكار\",\"الاتضاع\"],\"k\":\"250.13\"},{\"i\":465,\"f\":\"الأب بمفو\",\"p\":250,\"n\":14,\"c\":\"جوابًا للأب ثيوذورس الفرمي الذي توسل إليه: قل لي كلمة\",\"t\":\"يا ثيوذورس، اذهب وكن رحيماً نحو الجميع، لأن الرحمة قد وجدت حظوة في عيني الرب.\",\"g\":[\"الرحمة\",\"المحبة\"],\"k\":\"250.14\"},{\"i\":466,\"f\":\"الأب سيسوى\",\"p\":252,\"n\":1,\"c\":\"جوابًا لأخ سأل: ما هي الغربة يا أبت؟ (رواه الأب بيستوس)\",\"t\":\"أصمت وقل: لا أملك شيئاً، لا أملك شيئاً. هذا ردّده حيثما ذهبت وأينما كنت. هذه هي الغربة.\",\"g\":[\"الزهد\",\"الصمت\",\"الاتضاع\"],\"k\":\"252.1\"},{\"i\":467,\"f\":\"الأب بيور\",\"p\":252,\"n\":2,\"c\":\"جوابًا لأخ سأله: ولماذا تأكل هكذا يا أبت وأنت تمشي؟\",\"t\":\"لا أريد أن يكون الطعام مهنة، إنما عمل ثانوي.\",\"g\":[\"الزهد\",\"الصوم\",\"الجهاد\"],\"k\":\"252.2\"},{\"i\":468,\"f\":\"الأب بيور\",\"p\":253,\"n\":3,\"c\":\"جوابًا لما سأله الآباء عن سبب حمله كيساً مملوءاً رملاً في اجتماع بسبب أخ مخطئ\",\"t\":\"إن هذا الكيس المليء بالرمال هو خطاياي أنا، وهي كثيرة العدد، وقد تركتها وراءي لئلا أتألم بسببها فأبكي. أما خطيئة أخي فهي أمامي، وبها انشغل إذ أدينه. وبالطبع لا يليق أن أفعل هكذا، إنما يجب بالأحرى أن أضع خطاياي نصب عيني وأهتم بها متضرعاً إلى الله أن يسامحني.\",\"g\":[\"الإدانة\",\"الاتضاع\",\"التوبة\"],\"k\":\"253.3\"},{\"i\":469,\"f\":\"الأب بيتيريون\",\"p\":253,\"n\":1,\"t\":\"من أراد أن يطرد الشياطين، عليه أن يخضع الأهواء أولاً، لأننا إذا تغلبنا على الأهواء نقدر أن نطرد الشياطين. فالشيطان يتبع الغضب. وإذا ضبط الغضب، يطرد شيطانه. والشيء نفسه يقال عن كل هوى.\",\"g\":[\"الغضب\",\"الجهاد\",\"الأفكار\"],\"k\":\"253.1a\"},{\"i\":470,\"f\":\"الأب بيستامون\",\"p\":253,\"n\":1,\"c\":\"جوابًا لأخ سأل: ماذا أعمل إذا انزعجت وأنا أبيع عمل يدي؟\",\"t\":\"عندما تبيع، قل ثمن السلال مرة واحدة فقط. وإذا رغبت في تخفيض الثمن قليلاً، فهذا متروك لك. بهذا تجد راحة.\",\"g\":[\"العمل\",\"السلام\",\"الحكمة\"],\"k\":\"253.1b\"},{\"i\":471,\"f\":\"الأب بيستامون\",\"p\":253,\"n\":2,\"c\":\"جوابًا لأخ سأل: إذا كانت حاجاتي مؤمّنة لي، هل تنصحني أن أهتم بعمل اليد؟\",\"t\":\"مهما كان لديك، لا تتخلَّ عن عمل اليد. فقط اعمل ما في وسعك، لكن دونما اضطراب.\",\"g\":[\"العمل\",\"السلام\"],\"k\":\"253.2\"},{\"i\":472,\"f\":\"الأب بطرس\",\"p\":255,\"n\":4,\"t\":\"لا ينبغي أن تتكبر عندما يجري الرب أمراً على أيدينا. بل ينبغي بالأحرى أن نشكره لأنه أهّلنا أن ننجذب إليه. وفي كل فضيلة أيضاً، يليق بنا التفكير هكذا.\",\"g\":[\"الاتضاع\",\"الشكر\",\"الكبرياء\"],\"k\":\"255.4\"},{\"i\":473,\"f\":\"الأب بفنوتيوس\",\"p\":256,\"n\":1,\"c\":\"قاله له ملاك يحمل سيفاً حين وقف يصلّي من أجل خطاياه بينما كان بعض الناس يتحدثون\",\"t\":\"إن الذين يدينون إخوتهم يهلكون بحد هذا السيف. أما أنت، فكونك لا تدين أحداً بل تتضع أمام الله وكأنك أنت الذي يرتكب الخطيئة، فإن اسمك قد كتب في سفر الأحياء.\",\"g\":[\"الإدانة\",\"الاتضاع\",\"التوبة\"],\"k\":\"256.1\"},{\"i\":474,\"f\":\"الأب بفنوتيوس\",\"p\":256,\"n\":3,\"c\":\"رواه الأب بيمن: كنت أكشف للشيوخ كل فكر من أفكاري، فلم يكونوا يقولون لي سوى هذا\",\"t\":\"حيثما ذهبت، لا تقم لنفسك وزناً، فترتاح.\",\"g\":[\"الاتضاع\",\"الأفكار\",\"السلام\"],\"k\":\"256.3\"},{\"i\":475,\"f\":\"الأب بولس\",\"p\":258,\"n\":1,\"c\":\"جوابًا للإخوة الذين سألوه عن عمله وهو يمسك الأفاعي\",\"t\":\"الإنسان إذا ما اقتنى الطهارة، فإن كل شيء يخضع له ويطيعه، كحال آدم عندما كان في الفردوس قبل أن يعصى الوصية.\",\"g\":[\"الشهوة\",\"الجهاد\"],\"k\":\"258.1a\"},{\"i\":476,\"f\":\"الأب بولس الكوزميتي\",\"p\":258,\"n\":2,\"c\":\"جوابًا لأخيه تيموثاوس حين انزعجا من الإخوة وقال: إننا لا نقدر أن نهدأ طول النهار\",\"t\":\"يكفينا هدوء الليل إذا كان ذهننا صاحياً.\",\"g\":[\"السهر\",\"الخلوة\",\"الصبر\"],\"k\":\"258.2a\"},{\"i\":477,\"f\":\"الأب بولس الكبير\",\"p\":258,\"n\":1,\"t\":\"إن الراهب الذي له حاجات قليلة في قلايته، متى خرج للإهتمام بها، فإن الشياطين كلها ترزأ به، وأنا نفسي تألمت من هذا.\",\"g\":[\"الخلوة\",\"الزهد\",\"الجهاد\"],\"k\":\"258.1b\"},{\"i\":478,\"f\":\"الأب بولس الكبير\",\"p\":258,\"n\":2,\"t\":\"في الضوضاء أكون غرقاً حتى عنقي، فأبكي أمام الله قائلاً: «ارحمني».\",\"g\":[\"الصلاة\",\"الدموع\",\"الضيقات\"],\"k\":\"258.2b\"},{\"i\":479,\"f\":\"الأب بولس البسيط\",\"p\":260,\"n\":1,\"c\":\"خاتمة رواية الأب بولس البسيط تلميذ القديس أنطونيوس عن أخٍ تاب عند سماعه سفر أشعياء في الكنيسة\",\"t\":\"فاعلموا يا أيها المسيحيون، من الكتب والإعلانات الإلهية صلاح الله للذين يهرعون إليه بصدق فيصلحون بالتوبة سيرتهم السابقة، وإن الله يهب الخيرات الموعود بها بدون أن يعاقب على الخطايا السالفة، فلا نيأس من خلاصنا لأنه كما وعدنا بنبيّه أشعياء أنه سيطهر خطايانا القائمة ويجعلنا بيض كالثلج، فنؤهل لخيرات أورشليم السماوية.\",\"g\":[\"التوبة\",\"الرجاء\",\"الرحمة\"],\"k\":\"260.1\"},{\"i\":480,\"f\":\"الأب روماوس\",\"p\":263,\"n\":2,\"c\":\"قاله لتلميذ صالح لأحد الشيوخ، بعدما طرده ثم رآه ثابتاً عند الباب\",\"t\":\"إن تواضعك وطول أناتك قد هزمت إهمالي وغلبته. هلمّ إلى الداخل. من الآن تكون الأب وأنا التلميذ.\",\"g\":[\"الاتضاع\",\"الصبر\"],\"k\":\"263.2\"},{\"i\":481,\"f\":\"الأب روفو\",\"p\":263,\"n\":1,\"c\":\"جوابًا لأخ سأل: ما السكينة وما هي منافعها؟\",\"t\":\"السكينة هي أن يقيم المرء في قلايته بمعرفة الله وخوفه مبتعداً عن الإساءة والعجب. إن سكينة كهذه تتولد منها كل الفضائل ومن شأنها أن تحمي الراهب من سهام العدو الملتهبة فلا تدعه ينجرح. اقتنِ هذه السكينة وتذكّر ساعة خروجك لأنك لا تعلم متى يأتي اللص. بهذا إذن، إسهر من أجل خلاص نفسك.\",\"g\":[\"الخلوة\",\"السهر\",\"خوف الله\"],\"k\":\"263.1\"},{\"i\":482,\"f\":\"الأب روفو\",\"p\":264,\"n\":2,\"t\":\"إن من يبقى تلميذاً لأب روحي له أجر أكبر من الذي يعيش في البرية كناسك. أيتها الطاعة، يا خلاص جميع المؤمنين. أيتها الطاعة، يا أمّ جميع الفضائل. أيتها الطاعة، يا محقِّقة الملكوت وفاتحة أبواب السموات. أيتها الطاعة التي منها نغتذي فنبلغ الكمال.\",\"g\":[\"الطاعة\",\"الاتضاع\"],\"k\":\"264.2\"},{\"i\":483,\"f\":\"الأب رومانوس\",\"p\":264,\"n\":1,\"c\":\"جوابًا لتلاميذه عندما أوشك أن يغادر هذا العالم وسألوه: كيف ينبغي أن نسلك بعد رحيلك؟\",\"t\":\"لا أذكر أني طلبت من أحدكم شيئاً دون التفكير به قبل طلبه. وهكذا كنا نعيش بسلام كل زمان حياتنا.\",\"g\":[\"السلام\",\"الحكمة\",\"الصبر\"],\"k\":\"264.1\"},{\"i\":484,\"f\":\"الأب سيسوى\",\"p\":265,\"n\":1,\"c\":\"جوابًا لأخ أُسيء إليه فجاء يريد أن ينتقم لنفسه، فقام الشيخ يصلّي هكذا فسقط الأخ عند قدميه وقال: لن أخاصم أخي بعد اليوم\",\"t\":\"يا رب لم نعد بحاجة إلى عنايتك واهتمامك بنا، لأننا ننتقم لأنفسنا.\",\"g\":[\"الغفران\",\"الصلاة\",\"المحبة\"],\"k\":\"265.1\"},{\"i\":485,\"f\":\"الأب سيسوى\",\"p\":265,\"n\":2,\"c\":\"جوابًا لتلميذه إبراهيم حين قال له: إذا جرى لقاء في السبت أو الأحد وشرب الأخ ثلاثة كؤوس، هل هذا كثير؟\",\"t\":\"إذا لم يكن في الوسط شيطان، فالعدد ليس بكثير.\",\"g\":[\"الحكمة\",\"التمييز\",\"الصوم\"],\"k\":\"265.2\"},{\"i\":486,\"f\":\"الأب سيسوى\",\"p\":266,\"n\":5,\"c\":\"مرة قال جهاراً: تشجّع يا أخي، إذ لي ثلاثون سنة لا أتضرع إلى الله من أجل خطيئة، لكني أصلّي هكذا\",\"t\":\"يا ربي يسوع المسيح، استرني من لساني لأني بسببه أسقط كل يوم وأخطأ.\",\"g\":[\"الصلاة\",\"اللسان\",\"التوبة\"],\"k\":\"266.5\"},{\"i\":487,\"f\":\"الأب سيسوى\",\"p\":266,\"n\":8,\"c\":\"لما رفض كأس الخمر للمرة الثالثة في جبل القديس أنطونيوس\",\"t\":\"كفاني ما أخذتُ، ألا تعرف يا أخي، أن ثمة شيطاناً؟\",\"g\":[\"الشهوة\",\"الصوم\",\"السهر\"],\"k\":\"266.8\"},{\"i\":488,\"f\":\"الأب سيسوى\",\"p\":266,\"n\":9,\"c\":\"جوابًا لأخ سأله: ألم تبلغ بعد إلى قامة الأب أنطونيوس يا أبت؟\",\"t\":\"لو كان عندي شيء من فكره، لأصبحتُ ناراً. إلا أني أعرف إنساناً بالجهد يستطيع أن يحتمل فكر الأب أنطونيوس.\",\"g\":[\"الاتضاع\",\"الجهاد\"],\"k\":\"266.9\"},{\"i\":489,\"f\":\"الأب سيسوى\",\"p\":267,\"n\":11,\"c\":\"جوابًا لأخ سأل: ترى هل كان الشيطان يطارد المبتدئين هكذا؟\",\"t\":\"الآن يطاردهم أكثر من قبل، لأن أيامه باتت معدودة وهو قلق ومضطرب.\",\"g\":[\"الجهاد\",\"الأفكار\",\"الرجاء\"],\"k\":\"267.11\"},{\"i\":490,\"f\":\"الأب سيسوى\",\"p\":267,\"n\":13,\"c\":\"جوابًا لأخ قال: أرى أن ذكر الله يبقى في داخلي\",\"t\":\"ليس بالأمر الهام أن يكون فكرك مع الله، المهمّ حقاً هو أن تعاين نفسك دون الخليقة كلها، لأن هذا يقود، مع التعب الجسدي إلى سبيل التواضع.\",\"g\":[\"الاتضاع\",\"الجهاد\",\"الصلاة\"],\"k\":\"267.13\"},{\"i\":491,\"f\":\"الأب سيسوى\",\"p\":268,\"n\":15,\"c\":\"جوابًا للأسقف أذلفيوس الذي اعتذر له لأنه خشي أن يقول الناس إنه أكل عند الصباح\",\"t\":\"إذا لم يمجّدنا الله، فمجد الناس باطل.\",\"g\":[\"المجد الباطل\",\"الاتضاع\"],\"k\":\"268.15\"},{\"i\":492,\"f\":\"الأب سيسوى\",\"p\":268,\"n\":17,\"c\":\"جوابًا للأب عمون الريتي: عندما أقرأ في الكتب المقدسة يجنح فكري إلى التوقف عند كلمة يجعل منها علّة لسؤال\",\"t\":\"لا حاجة لك إلى هذا، يكفي أن تقتني نقاوة الذهن وعدم الهمّ والكلام.\",\"g\":[\"الكتاب المقدس\",\"الصمت\",\"الأفكار\"],\"k\":\"268.17\"},{\"i\":493,\"f\":\"الأب سيسوى\",\"p\":269,\"n\":19,\"c\":\"جوابًا لثلاثة شيوخ سأله الأول عن النهر الناري، والثاني عن صريف الأسنان والدود الذي لا ينام، والثالث عن الظلمة الخارجية\",\"t\":\"أنا لا أذكر شيئاً من هذه كلها، لأني أعرف أن الله محب وأرجو أن يرحمني.\",\"g\":[\"الرجاء\",\"الرحمة\",\"الإيمان\"],\"k\":\"269.19\"},{\"i\":494,\"f\":\"الأب سيسوى\",\"p\":269,\"n\":20,\"c\":\"جوابًا لمن سأله: إذا سقط أخ، ألا ينبغي أن يتوب سنة كاملة؟\",\"t\":\"تكفيه فترة وجيزة حتى يتوب، لأني أؤمن أن الإنسان إذا تاب من كل قلبه، فإن الله يقبله في غضون ثلاثة أيام.\",\"g\":[\"التوبة\",\"الرجاء\",\"الرحمة\"],\"k\":\"269.20\"},{\"i\":495,\"f\":\"الأب سيسوى\",\"p\":270,\"n\":22,\"c\":\"جوابًا للأب يوسف: متى ينبغي أن يقطع الإنسان أهواءه؟\",\"t\":\"عندما يأتيك الهوى، اقطعه في الحال.\",\"g\":[\"الجهاد\",\"الأفكار\",\"السهر\"],\"k\":\"270.22\"},{\"i\":496,\"f\":\"الأب سيسوى\",\"p\":271,\"n\":29,\"t\":\"إذا كان ثمة من يعتني بك، لا ينبغي أن تأمره.\",\"g\":[\"الاتضاع\",\"الخدمة\"],\"k\":\"271.29\"},{\"i\":497,\"f\":\"الأب سيسوى\",\"p\":271,\"n\":30,\"c\":\"بعد أن ضلّ مرشد الإخوة الطريق في الظلام وصمتوا جميعاً حتى الفجر دون أن يلوموه\",\"t\":\"إن الإخوة يضبطون أنفسهم حتى الموت دون أن يتكلموا. فمجّد الله.\",\"g\":[\"الصمت\",\"الصبر\",\"اللسان\"],\"k\":\"271.30\"},{\"i\":498,\"f\":\"الأب سيسوى\",\"p\":272,\"n\":34,\"c\":\"جوابًا لأحد الآباء: إذا كنت في البرية وجاء بربري يريد قتلي وقويت عليه، هل أقتله؟\",\"t\":\"إنما سلّمه إلى الله، لأنه عندما تحل تجربة ما بالإنسان، فليقل: «إن هذا حدث من أجل خطيئتي». وإذا كان الأمر صالحاً، قل: هذا تدبير يمين الله.\",\"g\":[\"الضيقات\",\"الاتضاع\",\"الإيمان\"],\"k\":\"272.34\"},{\"i\":499,\"f\":\"الأب سيسوى\",\"p\":272,\"n\":35,\"c\":\"جوابًا لأخ توسّل إليه: قل لي كلمة\",\"t\":\"إني أقرأ العهد القديم وأرجع إلى العهد الجديد.\",\"g\":[\"الكتاب المقدس\",\"الحكمة\"],\"k\":\"272.35\"},{\"i\":500,\"f\":\"الأب سيسوى\",\"p\":272,\"n\":36,\"t\":\"أنا في الخطيئة أنام وفي الخطيئة أستيقظ.\",\"g\":[\"الاتضاع\",\"التوبة\"],\"k\":\"272.36\"},{\"i\":501,\"f\":\"الأب سيسوى\",\"p\":272,\"n\":38,\"c\":\"جوابًا لأخ سأل: ماذا أعمل وقد سقطت يا أبت؟\",\"t\":\"انهض من جديد. قال الأخ: لقد نهضت لكنني عدت وسقطت. قال له الشيخ: انهض أيضاً من جديد. قال له الأخ: وإلى متى يكون ذلك؟ أجابه الشيخ: إلى أن تنتهي، إمّا إلى الخير أو إلى السقطة، لأن الإنسان يسلك حيثما وجد.\",\"g\":[\"التوبة\",\"الرجاء\",\"الجهاد\"],\"k\":\"272.38\"},{\"i\":502,\"f\":\"الأب سيسوى\",\"p\":272,\"n\":39,\"c\":\"جوابًا لأخ سأل: ماذا أعمل إذا تضايقت من عمل اليد؟\",\"t\":\"إنه لا يليق بنا أن نمارس الأعمال التي تريحنا.\",\"g\":[\"الجهاد\",\"العمل\"],\"k\":\"272.39\"},{\"i\":503,\"f\":\"الأب سيسوى\",\"p\":273,\"n\":40,\"t\":\"أطلب الله ولا تسأل عن مكان سكناه.\",\"g\":[\"الإيمان\",\"الصلاة\"],\"k\":\"273.40\"},{\"i\":504,\"f\":\"الأب سيسوى\",\"p\":273,\"n\":41,\"t\":\"الخجل وعدم مخافة الله كثيراً ما يحملان الخطيئة.\",\"g\":[\"خوف الله\",\"الشهوة\"],\"k\":\"273.41\"},{\"i\":505,\"f\":\"الأب سيسوى\",\"p\":273,\"n\":42,\"c\":\"جوابًا لأخ سأل: ماذا أعمل؟\",\"t\":\"إن ما تطلبه هو الصمت الكثير مع التواضع، لأنه مكتوب «هنيئاً للذين يثبتون فيه» (أشعياء ٣٠: ١٨). هكذا يمكنك أن تخلص.\",\"g\":[\"الصمت\",\"الاتضاع\"],\"k\":\"273.42\"},{\"i\":506,\"f\":\"الأب سيسوى\",\"p\":273,\"n\":43,\"t\":\"ازدر بنفسك واجعل مشيئتك وراءك وكن عديم الهمّ، فتجد راحة.\",\"g\":[\"الاتضاع\",\"الطاعة\",\"السلام\"],\"k\":\"273.43\"},{\"i\":507,\"f\":\"الأب سيسوى\",\"p\":273,\"n\":44,\"c\":\"جوابًا لأخ سأل: ماذا أعمل بالأهواء يا أبت؟\",\"t\":\"«إن كل واحد منا يجرّب من شهوته» (يعقوب ١: ١٤).\",\"g\":[\"الشهوة\",\"الأفكار\",\"الكتاب المقدس\"],\"k\":\"273.44\"},{\"i\":508,\"f\":\"الأب سيسوى\",\"p\":273,\"n\":45,\"c\":\"جوابًا لأخ توسّل إليه: قل لي كلمة واحدة فقط\",\"t\":\"لماذا ترغمني على الكلام؟ ما تراه، إياه افعل.\",\"g\":[\"الصمت\",\"العمل\",\"اللسان\"],\"k\":\"273.45\"},{\"i\":509,\"f\":\"الأب سلوان\",\"p\":275,\"n\":1,\"c\":\"جوابًا لتلميذه زخريا حين أراد أن يشرب في الطريق وقال: ألم نأكل يا أبت؟ (بعد أن أُجبرا على الأكل قليلاً في أحد الأديار قبل السفر)\",\"t\":\"ما أكلناه، كان من المحبة. أمّا هنا، فلنحتفظ بصيامنا يا ولدي.\",\"g\":[\"الصوم\",\"المحبة\",\"الضيافة\"],\"k\":\"275.1\"},{\"i\":510,\"f\":\"الأب سلوان\",\"p\":275,\"n\":4,\"c\":\"جوابًا لزائر سأله: لماذا كنت تغطّي وجهك بالعمامة وأنت تروي البستان؟\",\"t\":\"لئلا تنشغل عيناي بالشجر يا ولدي، فينشغل عقلي بها دون العمل الحقيقي.\",\"g\":[\"السهر\",\"العمل\",\"الأفكار\"],\"k\":\"275.4\"},{\"i\":511,\"f\":\"الأب سلوان\",\"p\":276,\"n\":5,\"c\":\"جوابًا لأخ سأله: لماذا لم تدعوني إلى تناول الطعام؟\",\"t\":\"لأنك إنسان روحي ولا تحتاج إلى هذا الطعام. أمّا نحن فإننا بشر ونحتاج إليه، لهذا نعمل. اخترت النصيب الصالح لأنك كنت تقرأ طوال النهار، ولا تريد أن تأكل طعاماً بشرياً (جسدياً). في كل الأحوال، تحتاج مريم إلى مرثا، لأن مريم تُمتدح بسبب مرثا.\",\"g\":[\"الخدمة\",\"العمل\",\"الشركة\"],\"k\":\"276.5\"},{\"i\":512,\"f\":\"الأب سلوان\",\"p\":276,\"n\":6,\"c\":\"جوابًا للإخوة الذين سألوه: أيّ نسك مارست يا أبت حتى اكتسبت هذه الحصافة؟\",\"t\":\"في الحقيقة يا إخوتي إنني لم أترك في قلبي فكراً يغضب الله.\",\"g\":[\"الأفكار\",\"خوف الله\",\"الجهاد\"],\"k\":\"276.6\"},{\"i\":513,\"f\":\"الأب سلوان\",\"p\":277,\"n\":9,\"t\":\"أنا عبد وسيدي قال لي: أتمم عملي وأنا أعولك. من أين؟ لا تسأل. سواء عندي أم أني أسرق، أو أقترض، أنت لا تسأل، لأن هذا لا يعنيك. ما عليك إلاّ أن تعمل وحسب، وأنا أعولك. لذا إذا عملتُ، فإني أعيش من أجري. وإذا لم أعمل، أعيش من التصدق والإحسان.\",\"g\":[\"العمل\",\"الرجاء\",\"الإيمان\"],\"k\":\"277.9\"},{\"i\":514,\"f\":\"الأب سلوان\",\"p\":277,\"n\":10,\"t\":\"وا حسرتاه على من كان اسمه أكبر من عمله!!\",\"g\":[\"العمل\",\"الاتضاع\",\"المجد الباطل\"],\"k\":\"277.10\"},{\"i\":515,\"f\":\"الأب سلوان\",\"p\":277,\"n\":11,\"c\":\"جوابًا للأب موسى: هل يمكن أن يبتدىء المرء من جديد كل يوم؟\",\"t\":\"إذا كان نشيطاً، يمكنه أن يبتدىء كل ساعة.\",\"g\":[\"الجهاد\",\"التوبة\",\"الرجاء\"],\"k\":\"277.11\"},{\"i\":516,\"f\":\"الأب سوباتروس\",\"p\":278,\"n\":1,\"c\":\"جوابًا لأخ توسّل إليه: أعطني وصيّة أحفظها\",\"t\":\"لا تدع امرأة تدخل قلايتك. لا تقرأ كتباً منحولة. لا تتباحث عن صورة الله، فهذه ليست هرطقة إنما هي جهالة ونزاع بين الطرفين. في الحقيقة إن هذا أمر يستحيل إدراكه من البشر.\",\"g\":[\"الحكمة\",\"التمييز\",\"الخلوة\"],\"k\":\"278.1\"},{\"i\":517,\"f\":\"الأب سارمتا\",\"p\":279,\"n\":1,\"t\":\"أفضل إنساناً خاطئاً، لكنه يعرف خطيئته ويتوب عليها، على إنسان لا يخطئ بل يرى نفسه باراً.\",\"g\":[\"التوبة\",\"الاتضاع\",\"الكبرياء\"],\"k\":\"279.1\"},{\"i\":518,\"f\":\"الأب سارمتا\",\"p\":279,\"n\":3,\"c\":\"جوابًا لأخ قال: أفكاري تقول لي «لا تعمل» بل كل واشرب ونم\",\"t\":\"كُلْ عندما تجوع. واشرب عندما تعطش. ونم عندما يضربك النعاس.\",\"g\":[\"التمييز\",\"الأفكار\",\"الحكمة\"],\"k\":\"279.3\"},{\"i\":519,\"f\":\"الأب سارمتا\",\"p\":279,\"n\":4,\"c\":\"جوابًا لأخ قال: أفكاري تقول لي: أخرج وتفقّد الإخوة\",\"t\":\"لا تنصت إلى ما يقوله فكرك في هذا الشأن، إنما قلْ: في المرة الأولى استجيب لك، لكن هذه المرة لا أقدر أن أطيعك.\",\"g\":[\"الأفكار\",\"الجهاد\",\"الخلوة\"],\"k\":\"279.4\"},{\"i\":520,\"f\":\"الأب سيرابيون\",\"p\":281,\"n\":3,\"t\":\"كما أن جنود الملك لا يستطيعون أن يلتفتوا يمنة ويسرة عندما يكونون في خدمته، هكذا حال الإنسان عندما يمثل في حضرة الله على الدوام، إذ لا يمكن أن تخيفه أعمال العدو.\",\"g\":[\"الصلاة\",\"خوف الله\",\"الجهاد\"],\"k\":\"281.3\"},{\"i\":521,\"f\":\"الأب سيرابيون\",\"p\":281,\"n\":4,\"c\":\"وصية لأخ زاره وتصنّع الاتضاع\",\"t\":\"يا ولدي، إذا ابتغيت المنفعة، لا تغادر قلايتك. انتبه لنفسك وعمل يديك. فالخروج لا يجديك نفعاً كالبكاء.\",\"g\":[\"الخلوة\",\"الدموع\",\"السهر\"],\"k\":\"281.4\"},{\"i\":522,\"f\":\"الأب سيرابيون\",\"p\":281,\"n\":5,\"c\":\"للأخ الذي ادّعى أنه خاطئ غير مستحق ثم تمرمر عند أول ملاحظة بمحبة\",\"t\":\"إذا أردت أن تكون متواضعاً، درّب نفسك على تحمل ما يأتيك من الآخرين ولا ترضى بالكلمات العديمة النفع وحسب.\",\"g\":[\"الاتضاع\",\"الصبر\",\"الإدانة\"],\"k\":\"281.5\"},{\"i\":523,\"f\":\"الأب سيرينيوس\",\"p\":282,\"n\":1,\"c\":\"جوابًا للأب أيوب زميله الذي قال: في قلايتي احتفظ بقانوني لكن عندما أخرج أتنازل للإخوة\",\"t\":\"إن حفظك لقانونك ليس فضيلة كبيرة عندما تكون في قلايتك، لأن المهم هو أن تحفظه عندما تخرج.\",\"g\":[\"الجهاد\",\"الخلوة\",\"التمييز\"],\"k\":\"282.1\"},{\"i\":524,\"f\":\"الأب سيرينيوس\",\"p\":282,\"n\":2,\"t\":\"أمضيت السنة وأنا أجني وأخيط وأحوك. لكن بالرغم من كل هذا، لولا يد الله التي كانت تشبعني، ما كان بالإمكان أن أشبع أبداً.\",\"g\":[\"العمل\",\"الشكر\",\"الإيمان\"],\"k\":\"282.2\"},{\"i\":525,\"f\":\"الأم سارة\",\"p\":284,\"n\":1,\"c\":\"قالوا عنها إن شيطان الزنى حاربها بقوة طيلة ثلاث سنين وما صلّت إلى الله أن تغادرها الحرب، بل كانت تقول هذا\",\"t\":\"يا الله أعطني القوة.\",\"g\":[\"الصلاة\",\"الشهوة\",\"الصبر\"],\"k\":\"284.1\"},{\"i\":526,\"f\":\"الأم سارة\",\"p\":284,\"n\":2,\"c\":\"جوابًا لروح الزنى الذي ظهر لها جسدانياً وقال: لقد غلبتني يا سارة\",\"t\":\"سيدي المسيح هو الذي غلبك لا أنا.\",\"g\":[\"الشهوة\",\"الاتضاع\",\"الجهاد\"],\"k\":\"284.2\"},{\"i\":527,\"f\":\"الأم سارة\",\"p\":284,\"n\":4,\"c\":\"جوابًا لشيخين ناسكين قالا: هلمّ نذلّل هذه العجوز، وقالا لها: انتبهي أن يناهضك فكرك فتقولي ها قد جاء النساك إليّ مع أنيّ امرأة\",\"t\":\"أنا في الطبيعة امرأة، لكني في الفكر لست هكذا.\",\"g\":[\"الأفكار\",\"الاتضاع\",\"الجهاد\"],\"k\":\"284.4\"},{\"i\":528,\"f\":\"الأم سارة\",\"p\":284,\"n\":5,\"t\":\"إذا طلبت إلى الله أن يكون الجميع مرتاحين من جهتي، فسأكون عند باب كل واحد تائبة. إلاّ أني سأصلّي كي يكون قلبي عفيفاً تجاه كل واحد.\",\"g\":[\"الصلاة\",\"الاتضاع\",\"المحبة\"],\"k\":\"284.5\"},{\"i\":529,\"f\":\"الأم سارة\",\"p\":284,\"n\":6,\"t\":\"أضع رجلي على السلّم، وقبل أن أصعد عليه، أجعل الموت نصب عيني.\",\"g\":[\"ذكر الموت\",\"السهر\"],\"k\":\"284.6\"},{\"i\":530,\"f\":\"الأم سارة\",\"p\":284,\"n\":7,\"t\":\"يحسن للبشر أن يتصدّقوا حتى ولو كان السبب إرضاء للناس، لأن الإحسان يحقق لنا إرضاء الله.\",\"g\":[\"الرحمة\",\"الخدمة\"],\"k\":\"284.7\"},{\"i\":531,\"f\":\"الأم سينكليتيكي\",\"p\":285,\"n\":1,\"t\":\"يكثر في البداية التعب والجهاد عند الذين يتقدمون نحو الله، لكن بعد ذلك يغمرهم فرح لا يوصف. وهم كالذين يريدون إشعال النار، يلفحهم الدخان فتدمع عيونهم لكنهم يبلغون إلى ما يرومون، لأنه يقول: «إن إلهنا نار آكلة» (عبرانيين ١٢: ٢٩). هكذا يجب علينا أن نضرم النار الإلهية بدموع وأتعاب.\",\"g\":[\"الجهاد\",\"الدموع\",\"الصبر\",\"الفرح\"],\"k\":\"285.1\"},{\"i\":532,\"f\":\"الأم سينكليتيكي\",\"p\":285,\"n\":3,\"t\":\"كما تبعد الأدوية القوية الحادة الوحوش السامة، هكذا تبعد الصلاة مع الصوم الفكر الشرير.\",\"g\":[\"الصلاة\",\"الصوم\",\"الأفكار\"],\"k\":\"285.3\"},{\"i\":533,\"f\":\"الأم سينكليتيكي\",\"p\":285,\"n\":4,\"t\":\"لا يغريك تنعّم أهل العالم الأغنياء كما لو أن فيه شيئاً ثميناً بسبب اللذة الجوفاء. أولئك يوقّرون فن الطهي، أمّا أنت فبالصوم عن الأطعمة تسمو فوق لذائذ وطيّبات أطعمتهم، لأنه يقول: «إن النفس التي تحيا بالتنعّم، تهزأ بالشهد» (أمثال ٢٧: ٧).\",\"g\":[\"الصوم\",\"الزهد\",\"الطمع\"],\"k\":\"285.4\"},{\"i\":534,\"f\":\"الأم سينكليتيكي\",\"p\":285,\"n\":5,\"c\":\"جوابًا لسؤال: هل عدم القنية هو صلاح كامل؟\",\"t\":\"إنه الأكمل عند من يقدر، لأن من يحتمله يزرع في جسده حزناً، إلا أنه يزرع في نفسه سروراً وراحة. فكما أن الثياب الخشنة عندما تداس وتدلك بعنف، تنغسل، هكذا النفس القوية، تتقوى أكثر بالجوع الطوعي.\",\"g\":[\"الزهد\",\"الصوم\",\"الفرح\"],\"k\":\"285.5\"},{\"i\":535,\"f\":\"الأم سينكليتيكي\",\"p\":286,\"n\":6,\"t\":\"إذا كنت تعيش في شركة، لا تغيّر مكانك، لأنك بذلك تتأذى كثيراً. في الحقيقة كما أن الدجاجة عندما تغادر البيضة، تهملها، هكذا حال الراهب أو العذراء، عندما يتنقل من موضع إلى آخر، يفتر وتنطفئ جذوة الإيمان فيه.\",\"g\":[\"الشركة\",\"الصبر\",\"الإيمان\"],\"k\":\"286.6\"},{\"i\":536,\"f\":\"الأم سينكليتيكي\",\"p\":287,\"n\":8,\"t\":\"إذا أزعجنا المرض، لا نحزن إذا لم نقدر أن نسبّح الرب بصوتنا، لأن هذا يكون لتنقية الأهواء. في الحقيقة إن الصوم والإنطراح في الفراش شُرّعا لنا من أجل الشهوات. هذا هو النسك الكبير: أن نحتمل الأمراض ونرفع التسابيح الشكرية لله.\",\"g\":[\"الضيقات\",\"الشكر\",\"الصبر\"],\"k\":\"287.8\"},{\"i\":537,\"f\":\"الأم سينكليتيكي\",\"p\":287,\"n\":9,\"t\":\"إذا كنت صائماً، لا تتخذ المرض ذريعة، لأن الذين لا يصومون قد سقطوا كثيراً في هذه الأمراض. هل ابتدأت بالعمل الصالح؟ لا تتوقف لئلا يعترضك العدو، لأنك بصبرك تبطله. هكذا نحن عندما يعاكسنا ريح ونرفع الصليب بدل الأشرعة، فلنكمل الإبحار بلا فزع وخوف.\",\"g\":[\"الصوم\",\"الصبر\",\"الجهاد\"],\"k\":\"287.9\"},{\"i\":538,\"f\":\"الأم سينكليتيكي\",\"p\":287,\"n\":10,\"t\":\"إن الذين يجمعون الغنى الحسّي بأتعاب البحر وأخطاره، لا يكتفون بما يجنون، إنما يطلبون المزيد. أمّا نحن، فبدون أن يكون لنا شيء من الأمور المرغوب فيها، لا نريد أن نقتني شيئاً بسبب مخافة الله.\",\"g\":[\"الطمع\",\"الزهد\",\"خوف الله\"],\"k\":\"287.10\"},{\"i\":539,\"f\":\"الأم سينكليتيكي\",\"p\":287,\"n\":11,\"t\":\"مثِّل العشّار لئلا تدان مع الفرّيسي (لوقا ٨: ١٠). آثر وداعة موسى لكي تحوِّل قلبك الصلد إلى ينابيع مياه (مزمور ١١٣: ٨).\",\"g\":[\"الاتضاع\",\"الوداعة\",\"الكبرياء\"],\"k\":\"287.11\"},{\"i\":540,\"f\":\"الأم سينكليتيكي\",\"p\":288,\"n\":13,\"t\":\"حسن أن لا تغضب. ولكن إذا حصل وغضبت، لا يسمح لك الرب بغضب يوم كامل قائلاً: «لا تغرب الشمس على غضبكم» (أفسس ٤: ٢٦). فهل تنتظر أنت إذن، حتى يغرب زمان حياتك كله؟ لماذا تمقت من أحزنك؟ ليس هو الذي ظلمك، بل الشيطان. فأنت مدعو أن تمقت المرض لا المريض.\",\"g\":[\"الغضب\",\"الغفران\",\"الصبر\"],\"k\":\"288.13\"},{\"i\":541,\"f\":\"الأم سينكليتيكي\",\"p\":288,\"n\":14,\"t\":\"كلما تقدّم الرياضيون، فإنهم يبارون بمنافسة أشد.\",\"g\":[\"الجهاد\",\"الصبر\"],\"k\":\"288.14\"},{\"i\":542,\"f\":\"الأم سينكليتيكي\",\"p\":288,\"n\":16,\"t\":\"عندما نكون في دير ذي حياة مشتركة، يجب أن نؤثر الطاعة على النسك، لأن هذه تعلّم التشامخ، أمّا الأولى (أي الطاعة)، فمن شأنها أن تعلّم التواضع.\",\"g\":[\"الطاعة\",\"الاتضاع\",\"الشركة\"],\"k\":\"288.16\"},{\"i\":543,\"f\":\"الأم سينكليتيكي\",\"p\":288,\"n\":17,\"t\":\"بالتمييز الروحي ينبغي أن نسوس أنفسنا. وعندما نكون في شركة من الإخوة، لا ينبغي أن نطلب ما هو لنا، ولا يليق أن نستعبد لرأينا، فالأحرى أن نكون مطيعين لأبينا في الإذعان.\",\"g\":[\"التمييز\",\"الطاعة\",\"الشركة\"],\"k\":\"288.17\"},{\"i\":544,\"f\":\"الأم سينكليتيكي\",\"p\":288,\"n\":18,\"t\":\"كُتب: «كونوا حكماء كالحيّات ودعاء كالحمام» (متى ١٠: ١٦). ففي قوله أن نكون كالحيّات، يعني أن لا تنطلي علينا ألاعيب الشيطان، لأن الشبيه يُعرف مما يماثله. أمّا قوله في أن نكون ودعاء كالحمام، فيشير إلى نقاوة السيرة.\",\"g\":[\"الحكمة\",\"الوداعة\",\"الكتاب المقدس\"],\"k\":\"288.18\"},{\"i\":545,\"f\":\"الأب تيثوى\",\"p\":289,\"n\":2,\"t\":\"الغربة هي أن يمسك المرء فمه.\",\"g\":[\"الصمت\",\"اللسان\",\"الزهد\"],\"k\":\"289.2\"},{\"i\":546,\"f\":\"الأب تيثوى\",\"p\":289,\"n\":3,\"c\":\"جوابًا لأخ سأل: كيف أحفظ قلبي؟\",\"t\":\"كيف يمكننا أن نحفظ قلبنا عندما يكون لساننا وبطننا مفتوحين؟\",\"g\":[\"اللسان\",\"الصوم\",\"السهر\"],\"k\":\"289.3\"},{\"i\":547,\"f\":\"الأب تيثوى\",\"p\":289,\"n\":7,\"c\":\"جوابًا لأخ سأل: ما هي الطريق التي تقود إلى التواضع؟\",\"t\":\"إن طريق التواضع هي ضبط النفس، والصلاة، وأن يكون المرء دون الخليقة كلها.\",\"g\":[\"الاتضاع\",\"الصلاة\",\"الجهاد\"],\"k\":\"289.7\"},{\"i\":548,\"f\":\"الأب إيبريخيوس\",\"p\":291,\"n\":1,\"t\":\"كما أن الأسد يخيف الحمار الوحشي، هكذا يسود الراهب الممتحَن على أفكار الشهوة.\",\"g\":[\"الشهوة\",\"الجهاد\",\"الأفكار\"],\"k\":\"291.1\"},{\"i\":549,\"f\":\"الأب إيبريخيوس\",\"p\":291,\"n\":2,\"t\":\"الصوم لجام للراهب أمام الخطيئة. وكل من يرميها يصبح حصاناً مولعاً بالأنثى.\",\"g\":[\"الصوم\",\"الشهوة\"],\"k\":\"291.2\"},{\"i\":550,\"f\":\"الأب إيبريخيوس\",\"p\":291,\"n\":3,\"t\":\"إن من لا يضبط لسانه ساعة الغضب، لا يمكنه أن يضبط أهواءه.\",\"g\":[\"الغضب\",\"اللسان\",\"الأفكار\"],\"k\":\"291.3\"},{\"i\":551,\"f\":\"الأب إيبريخيوس\",\"p\":291,\"n\":4,\"t\":\"حسن أن تأكل اللحم وتحتسي الخمرة، بدل أن تأكل بالوقيعة لحوم الإخوة.\",\"g\":[\"الإدانة\",\"اللسان\",\"التمييز\"],\"k\":\"291.4\"},{\"i\":552,\"f\":\"الأب إيبريخيوس\",\"p\":291,\"n\":5,\"t\":\"بالنميمة أخرجت الحية حواء من الفردوس. هكذا هو حال من يثلب أخاه. فإنه يهلك نفس الذي يسمعه، ونفسه هو لا يقدر أن يخلّصها.\",\"g\":[\"اللسان\",\"الإدانة\"],\"k\":\"291.5\"},{\"i\":553,\"f\":\"الأب إيبريخيوس\",\"p\":291,\"n\":6,\"t\":\"كنز الراهب هو عدم القنية الطوعي. فاكنز يا أخي في السماء، لأن أزمنة الراحة لا تنتهي.\",\"g\":[\"الزهد\",\"الطمع\"],\"k\":\"291.6\"},{\"i\":554,\"f\":\"الأب إيبريخيوس\",\"p\":291,\"n\":7,\"t\":\"فليكن ذكر ملكوت السماوات أمامك كل حين، فترثه سريعاً.\",\"g\":[\"الرجاء\",\"السهر\"],\"k\":\"291.7\"},{\"i\":555,\"f\":\"الأب إيبريخيوس\",\"p\":291,\"n\":8,\"t\":\"الطاعة هي جوهرة الراهب الموروثة. ومن يمتلكها، يحفظه المصلوب بدالة، ويسمع له الله، لأن الرب الذي صلب من أجلنا، أطاع حتى الموت.\",\"g\":[\"الطاعة\",\"الاتضاع\"],\"k\":\"291.8\"},{\"i\":556,\"f\":\"الأب فيليكس\",\"p\":294,\"n\":1,\"c\":\"جوابًا لبعض الإخوة ومعهم جماعة من أهل العالم طلبوا منه كلمة واحدة\",\"t\":\"الآن، ليس هناك من كلام. فالإخوة عندما كانوا يسألون الشيوخ ويعملون بما يسمعونه، كان الله يمنحهم القدرة على كيفية الكلام. أمّا الآن فإنهم يسألون ولا يفعلون بما يسمعون، فإن الله قد رفع نعمة الكلام عن الشيوخ، ولم يعد لديهم ما يتشدقون به، إذ ليس هناك من يعمل بما يقال.\",\"g\":[\"اللسان\",\"الصمت\",\"الطاعة\"],\"k\":\"294.1\"},{\"i\":557,\"f\":\"الأب فورتا\",\"p\":295,\"n\":1,\"t\":\"إذا أرادني الله أن أعيش، هو يعرف تماماً كيف يدبّرني. وإذا لم يكن يريد ذلك، ما حاجتي إلى هذه الحياة؟\",\"g\":[\"الإيمان\",\"الرجاء\",\"السلام\"],\"k\":\"295.1a\"},{\"i\":558,\"f\":\"الأب خومة\",\"p\":295,\"n\":1,\"c\":\"قاله لأبنائه الروحيين عندما أوشك أن يغادر العالم\",\"t\":\"لا تساكنوا الهراطقة. ولا تصاحبوا الوجهاء، ولا تمدّوا أيديكم للأخذ، إنما للعطاء.\",\"g\":[\"الحكمة\",\"الرحمة\",\"الزهد\"],\"k\":\"295.1b\"},{\"i\":559,\"f\":\"الأب أور\",\"p\":297,\"n\":5,\"t\":\"إذا رأيتُ فكراً ما ضد أحد، أعلمُ أن ذاك أيضاً عنده فكر مماثل ضدي.\",\"g\":[\"الإدانة\",\"الأفكار\",\"الاتضاع\"],\"k\":\"297.5\"},{\"i\":560,\"f\":\"الأب أور\",\"p\":298,\"n\":9,\"t\":\"التواضع هو إكليل الراهب.\",\"g\":[\"الاتضاع\"],\"k\":\"298.9\"},{\"i\":561,\"f\":\"الأب أور\",\"p\":298,\"n\":10,\"t\":\"إن من يُحترم ويُمتدح، أكثر مما هو عليه، يهلك كثيراً. أمّا الذي لا يمتدحه أحد، فإنه يتمجد من فوق.\",\"g\":[\"المجد الباطل\",\"الاتضاع\"],\"k\":\"298.10\"},{\"i\":562,\"f\":\"الأب أور\",\"p\":298,\"n\":11,\"t\":\"عندما يأتيك فكر التشامخ والكبرياء، افحص ضميرك إذا كنت قد حفظت كل الوصايا، أو أحببت كل أعدائك. وهل تحزن لهلاكهم. وإذا كنت تعتبر نفسك عبداً بطّالاً وخاطئاً أكثر من جميع الناس. ولا تظن أبداً أنك قد قمت بهذه كلها، عالماً أن هذا الفكر يلاشي هذه كلها.\",\"g\":[\"الكبرياء\",\"الاتضاع\",\"المحبة\"],\"k\":\"298.11\"},{\"i\":563,\"f\":\"الأب أور\",\"p\":298,\"n\":12,\"t\":\"في كل تجربة لا تلم أحداً، بل نفسك فقط، قائلاً: إن هذه أصابتني من جراء خطاياي.\",\"g\":[\"الضيقات\",\"الاتضاع\",\"الإدانة\"],\"k\":\"298.12\"},{\"i\":564,\"f\":\"الأب أور\",\"p\":298,\"n\":13,\"t\":\"لا تقل في قلبك نحو أخيك: أنا أكثر نسكاً وانتباهاً منه، إنما أطع نعمة المسيح بروح الفقر والمحبة التي لا رياء فيها لئلا تقع في روح الزهو والافتخار، فتخسر كل أتعابك، لأنه كُتب: «فليحذر السقوط من توهّم أنه واقف» (١كورنثوس ١٠: ١٢). لذلك، كن مملّحاً بملح المسيح.\",\"g\":[\"الاتضاع\",\"المحبة\",\"الكبرياء\"],\"k\":\"298.13\"},{\"i\":565,\"f\":\"الأب أور\",\"p\":298,\"n\":14,\"t\":\"اهرب من الناس على عجل، أو انخرط في العالم والناس، جاعلاً نفسك جاهلاً في أمور كثيرة.\",\"g\":[\"الخلوة\",\"الاتضاع\"],\"k\":\"298.14\"},{\"i\":566,\"f\":\"الأب أور\",\"p\":299,\"n\":15,\"t\":\"إذا ثلبت أخاك وأنّبك ضميرك، اذهب واصنع له مطانية (سجدة)، وقل: لقد ثلبتك يا أخي. ثم أكّد له أنك لن تتورط في ذلك بعد اليوم. فالوقيعة هي موت النفس.\",\"g\":[\"الإدانة\",\"التوبة\",\"اللسان\",\"الاتضاع\"],\"k\":\"299.15\"}]}";
